insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('0059335bd242', 'Wie geht es dir?', 'wie geht es dir', 'How are you?', 'B1', 'schreiben', 'schreiben_a1', 'einleitung_kontakt', 'greeting', 'Häufige Einstiegsfrage nach der Begrüßung.', '{{Wie}} {{geht}} es dir?', array['Wie','geht','es','dir?']::text[], array['du','Ihnen','dich']::text[], array['einleitung','informell']::text[], 1, '[{"de":"Hallo Lisa, wie geht es dir? Bei mir ist gerade richtig viel los.","en":"Hi Lisa, how are you? Things are really busy for me right now."},{"de":"Lange nicht geschrieben – wie geht es dir eigentlich?","en":"Long time no write – how are you, actually?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('09e118defa3e', 'Liebe Grüße, Anna', 'liebe Grüße Anna', 'Love, Anna', 'B1', 'schreiben', 'schreiben_a1', 'schluss_fazit', 'signoff', 'Standard-Grußformel informell.', '{{Liebe}} {{Grüße,}} Anna', array['Liebe','Grüße,','Anna']::text[], array['Lieber','Grüsse,','Gruß']::text[], array['schluss','informell']::text[], 1, '[{"de":"Ich freue mich schon auf nächste Woche. Liebe Grüße, Anna","en":"I''m already looking forward to next week. Best wishes, Anna"},{"de":"Schreib mir bald wieder! Liebe Grüße, Anna","en":"Write to me again soon! Best wishes, Anna"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
