insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('448cafae0ddf', 'Vielen Dank für deine Nachricht!', 'vielen Dank für deine Nachricht', 'Thanks so much for your message!', 'B1', 'schreiben', 'schreiben_a1', 'einleitung_kontakt', 'greeting', 'Standard-Eröffnung in einer informellen Mail.', '{{Vielen}} {{Dank}} für deine Nachricht!', array['Vielen','Dank','für','deine','Nachricht!']::text[], array['dein','Nachrichten','deinen']::text[], array['einleitung','informell']::text[], 1, '[{"de":"Vielen Dank für deine Nachricht! Ich habe mich riesig gefreut, von dir zu lesen.","en":"Many thanks for your message! I was really happy to hear from you."},{"de":"Vielen Dank für deine Nachricht! Klar, am Freitag passt mir gut.","en":"Many thanks for your message! Sure, Friday works well for me."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
