insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('707b747b3124', 'Ich hoffe, dir geht es gut!', 'ich hoffe dir geht es gut', 'I hope you''re doing well!', 'B1', 'schreiben', 'schreiben_a1', 'einleitung_kontakt', 'opening', 'Freundlicher Einstieg.', 'Ich {{hoffe,}} dir {{geht}} es gut!', array['Ich','hoffe,','dir','geht','es','gut!']::text[], array['hoffe','dich','Ihnen']::text[], array['einleitung','informell']::text[], 1, '[{"de":"Hallo Max, ich hoffe, dir geht es gut! Bei uns ist alles beim Alten.","en":"Hi Max, I hope you''re doing well! Everything''s the same as ever here."},{"de":"Ich hoffe, dir geht es gut! Lange haben wir nichts voneinander gehört.","en":"I hope you''re doing well! We haven''t heard from each other in a long time."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
