insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('a1beed2223c0', 'Bis bald!', 'bis bald', 'See you soon!', 'B1', 'schreiben', 'schreiben_a1', 'schluss_fazit', 'closing', 'Kurzer informeller Gruß.', '{{Bis}} {{bald!}}', array['Bis','bald!']::text[], array['Biss','Bist','Bald']::text[], array['schluss','informell']::text[], 1, '[{"de":"Ich muss los, mein Bus kommt gleich. Bis bald!","en":"I have to go, my bus is coming soon. See you soon!"},{"de":"Danke für alles und bis bald!","en":"Thanks for everything and see you soon!"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('b748fc4a7dc8', 'Lange nichts von dir gehört!', 'lange nichts von dir gehört', 'Haven''t heard from you in a while!', 'B1', 'schreiben', 'schreiben_a1', 'einleitung_kontakt', 'greeting', 'Lockerer Einstieg nach längerer Pause.', '{{Lange}} {{nichts}} von dir gehört!', array['Lange','nichts','von','dir','gehört!']::text[], array['Langem','hören','Ihnen']::text[], array['einleitung','informell']::text[], 1, '[{"de":"Hallo Sara, lange nichts von dir gehört! Wie läuft es bei dir?","en":"Hi Sara, haven''t heard from you in a while! How are things with you?"},{"de":"Lange nichts von dir gehört – ich hoffe, dir geht es gut.","en":"Haven''t heard from you in a while – I hope you''re doing well."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
