insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('d723e95b959c', 'Viele Grüße und bis dann!', 'viele Grüße und bis dann', 'Best wishes and see you then!', 'B1', 'schreiben', 'schreiben_a1', 'schluss_fazit', 'signoff', 'Kombinierte Grußformel.', '{{Viele}} {{Grüße}} und bis dann!', array['Viele','Grüße','und','bis','dann!']::text[], array['Vielen','Grüsse','denn!']::text[], array['schluss','informell']::text[], 1, '[{"de":"Ich freue mich schon aufs Wochenende mit dir. Viele Grüße und bis dann!","en":"I''m already looking forward to the weekend with you. Best wishes and see you then!"},{"de":"Sag deiner Familie liebe Grüße von mir. Viele Grüße und bis dann!","en":"Say hi to your family from me. Best wishes and see you then!"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('dc6b8e7ed58d', 'Schön, von dir zu hören!', 'schön von dir zu hören', 'Nice to hear from you!', 'B1', 'schreiben', 'schreiben_a1', 'einleitung_kontakt', 'greeting', 'Freundliche Reaktion auf eine erhaltene Mail.', '{{Schön,}} von dir zu {{hören!}}', array['Schön,','von','dir','zu','hören!']::text[], array['dich','Ihnen','hörst']::text[], array['einleitung','informell']::text[], 1, '[{"de":"Schön, von dir zu hören! Ich habe oft an dich gedacht.","en":"Nice to hear from you! I''ve thought of you often."},{"de":"Schön, von dir zu hören! Wie geht es deiner Familie?","en":"Nice to hear from you! How is your family doing?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('df14133032eb', 'Das ist wirklich lieb von dir!', 'das ist wirklich lieb von dir', 'That''s really kind of you!', 'B1', 'schreiben', 'schreiben_a1', 'danken_bedauern', 'thanks', 'Persönlicher Dank.', 'Das ist {{wirklich}} {{lieb}} von dir!', array['Das','ist','wirklich','lieb','von','dir!']::text[], array['dich','Ihnen','liebe']::text[], array['danken','informell']::text[], 1, '[{"de":"Du hast extra für mich eingekauft? Das ist wirklich lieb von dir!","en":"You went shopping just for me? That''s really kind of you!"},{"de":"Danke für die Blumen, das ist wirklich lieb von dir!","en":"Thanks for the flowers, that''s really kind of you!"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('059243bf57bb', 'Ich freue mich riesig auf dich!', 'ich freue mich riesig auf dich', 'I''m super excited to see you!', 'B2', 'schreiben', 'schreiben_a1', 'schluss_fazit', 'closing', 'riesig als umgangssprachlicher Verstärker.', 'Ich {{freue}} mich riesig {{auf}} dich!', array['Ich','freue','mich','riesig','auf','dich!']::text[], array['freut','über','dir!']::text[], array['schluss','informell']::text[], 2, '[{"de":"Nur noch drei Tage bis zu deinem Besuch – ich freue mich riesig auf dich!","en":"Only three more days until your visit – I''m super excited to see you!"},{"de":"Ich freue mich riesig auf dich! Wir haben uns viel zu erzählen.","en":"I''m super excited to see you! We have so much to catch up on."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('0bb9850e8561', 'Würdest du mir einen Gefallen tun?', 'würdest du mir einen Gefallen tun', 'Would you do me a favour?', 'B2', 'schreiben', 'schreiben_a1', 'vorschlag_bitte', 'request', 'jdm. einen Gefallen tun; Konjunktiv.', '{{Würdest}} du mir einen {{Gefallen}} tun?', array['Würdest','du','mir','einen','Gefallen','tun?']::text[], array['Wirst','mich','Gefallen,']::text[], array['bitte','informell','konjunktiv']::text[], 2, '[{"de":"Würdest du mir einen Gefallen tun und kurz die Katze füttern?","en":"Would you do me a favour and quickly feed the cat?"},{"de":"Würdest du mir einen Gefallen tun? Ich brauche jemanden, der mich vom Bahnhof abholt.","en":"Would you do me a favour? I need someone to pick me up from the station."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('0e95d816d4ec', 'Tut mir leid, dass ich so spät antworte.', 'tut mir leid dass ich so spät antworte', 'Sorry that I''m replying so late.', 'B1', 'schreiben', 'schreiben_a1', 'einleitung_kontakt', 'opening', 'Alltagswendung für verspätete Antwort.', '{{Tut}} mir leid, {{dass}} ich so spät antworte.', array['Tut','mir','leid,','dass','ich','so','spät','antworte.']::text[], array['das','antwortet','leiht,']::text[], array['einleitung','informell','dass']::text[], 2, '[{"de":"Tut mir leid, dass ich so spät antworte, ich hatte viel zu tun.","en":"Sorry that I''m replying so late, I had a lot going on."},{"de":"Tut mir leid, dass ich so spät antworte – deine Mail ist im Postfach untergegangen.","en":"Sorry that I''m replying so late – your email got buried in my inbox."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('1a482988507e', 'Wir hören uns bald!', 'wir hören uns bald', 'We''ll talk soon!', 'B2', 'schreiben', 'schreiben_a1', 'schluss_fazit', 'closing', 'Lockerer Abschiedsgruß.', 'Wir {{hören}} {{uns}} bald!', array['Wir','hören','uns','bald!']::text[], array['hört','uns,','Bald!']::text[], array['schluss','informell']::text[], 2, '[{"de":"Ich muss jetzt los – wir hören uns bald!","en":"I have to go now – we''ll talk soon!"},{"de":"Melde dich, wenn du Zeit hast. Wir hören uns bald!","en":"Get in touch when you have time. We''ll talk soon!"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('1a847185f697', 'Ich kann leider erst nächste Woche.', 'ich kann leider erst nächste Woche', 'Unfortunately, I can''t until next week.', 'B2', 'schreiben', 'schreiben_a1', 'danken_bedauern', 'regret', 'Elliptische Konstruktion mit ausgelassenem Verb.', 'Ich {{kann}} leider erst {{nächste}} Woche.', array['Ich','kann','leider','erst','nächste','Woche.']::text[], array['kann,','nächster','Wochen']::text[], array['bedauern','informell']::text[], 2, '[{"de":"Diese Woche schaffe ich es leider nicht – ich kann leider erst nächste Woche.","en":"I won''t manage this week unfortunately – I can''t until next week, sorry."},{"de":"Sollen wir uns treffen? Ich kann leider erst nächste Woche.","en":"Shall we meet up? Unfortunately, I can''t until next week."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('2b389b4e97a6', 'Es tut mir leid, dass ich nicht kommen kann.', 'es tut mir leid dass ich nicht kommen kann', 'I''m sorry that I can''t come.', 'B1', 'schreiben', 'schreiben_a1', 'danken_bedauern', 'regret', 'Bedauern mit dass-Satz und Modalverb am Ende.', 'Es {{tut}} mir leid, {{dass}} ich nicht kommen kann.', array['Es','tut','mir','leid,','dass','ich','nicht','kommen','kann.']::text[], array['das','leiht,','komme']::text[], array['bedauern','informell','dass']::text[], 2, '[{"de":"Es tut mir leid, dass ich nicht kommen kann, aber ich bin an dem Tag krank.","en":"I''m sorry that I can''t come, but I''m sick that day."},{"de":"Zu deiner Party: Es tut mir leid, dass ich nicht kommen kann.","en":"About your party: I''m sorry that I can''t come."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('2b939452b759', 'Ich danke dir für deine Hilfe.', 'ich danke dir für deine Hilfe', 'Thank you for your help.', 'B1', 'schreiben', 'schreiben_a1', 'danken_bedauern', 'thanks', 'danken + Dativ.', 'Ich {{danke}} dir für deine {{Hilfe.}}', array['Ich','danke','dir','für','deine','Hilfe.']::text[], array['dich','Ihnen','Hilfen']::text[], array['danken','informell','dativ']::text[], 2, '[{"de":"Ich danke dir für deine Hilfe beim Umzug – ohne dich wäre das nichts geworden!","en":"Thank you for your help with the move – it wouldn''t have worked without you!"},{"de":"Ich danke dir für deine Hilfe. Das war richtig nett von dir.","en":"Thank you for your help. That was really kind of you."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('609af8de2bb6', 'Entschuldige, dass ich mich erst jetzt melde.', 'entschuldige dass ich mich erst jetzt melde', 'Sorry that I''m only getting in touch now.', 'B2', 'schreiben', 'schreiben_a1', 'einleitung_kontakt', 'opening', 'Reflexives Verb sich melden; Entschuldigung für späte Antwort.', '{{Entschuldige,}} {{dass}} ich mich erst jetzt melde.', array['Entschuldige,','dass','ich','mich','erst','jetzt','melde.']::text[], array['das','Entschuldigen','meldet']::text[], array['einleitung','informell','dass']::text[], 2, '[{"de":"Entschuldige, dass ich mich erst jetzt melde, ich war zwei Wochen im Urlaub.","en":"Sorry that I''m only getting in touch now, I was on holiday for two weeks."},{"de":"Entschuldige, dass ich mich erst jetzt melde – es war einfach so viel los.","en":"Sorry that I''m only getting in touch now – there was just so much going on."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('61cf3e25823a', 'Ich hoffe, bei dir ist alles in Ordnung.', 'ich hoffe bei dir ist alles in Ordnung', 'I hope everything''s okay with you.', 'B2', 'schreiben', 'schreiben_a1', 'einleitung_kontakt', 'opening', 'Höfliche Nachfrage zu Beginn.', 'Ich {{hoffe,}} bei dir ist alles in {{Ordnung.}}', array['Ich','hoffe,','bei','dir','ist','alles','in','Ordnung.']::text[], array['Ihnen','im','Ordnungen']::text[], array['einleitung','informell']::text[], 2, '[{"de":"Ich hoffe, bei dir ist alles in Ordnung. Wir haben ja schon lange nicht mehr telefoniert.","en":"I hope everything''s okay with you. We haven''t spoken on the phone in ages."},{"de":"Ich hoffe, bei dir ist alles in Ordnung und die neue Stelle macht dir Spaß.","en":"I hope everything''s okay with you and you''re enjoying the new job."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('6434145d9d4f', 'Sollen wir uns morgen treffen?', 'sollen wir uns morgen treffen', 'Shall we meet tomorrow?', 'B1', 'schreiben', 'schreiben_a1', 'vorschlag_bitte', 'suggestion', 'Vorschlag mit sollen wir.', '{{Sollen}} wir uns morgen {{treffen?}}', array['Sollen','wir','uns','morgen','treffen?']::text[], array['Sollten','uns,','trifft?']::text[], array['vorschlag','informell']::text[], 2, '[{"de":"Sollen wir uns morgen treffen und für die Prüfung lernen?","en":"Shall we meet tomorrow and study for the exam?"},{"de":"Sollen wir uns morgen treffen, oder passt es dir besser am Wochenende?","en":"Shall we meet tomorrow, or does the weekend suit you better?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('67a21e8af120', 'Ich hoffe, wir sehen uns bald wieder.', 'ich hoffe wir sehen uns bald wieder', 'I hope we''ll see each other again soon.', 'B1', 'schreiben', 'schreiben_a1', 'schluss_fazit', 'closing', 'reflexives sich sehen.', 'Ich {{hoffe,}} wir {{sehen}} uns bald wieder.', array['Ich','hoffe,','wir','sehen','uns','bald','wieder.']::text[], array['hoffe','uns,','seht']::text[], array['schluss','informell']::text[], 2, '[{"de":"Ich hoffe, wir sehen uns bald wieder, am besten schon im Sommer.","en":"I hope we''ll see each other again soon, ideally as early as the summer."},{"de":"Es war so schön mit dir. Ich hoffe, wir sehen uns bald wieder.","en":"It was so nice with you. I hope we''ll see each other again soon."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('7f4387d67b28', 'Pass gut auf dich auf!', 'pass gut auf dich auf', 'Take good care of yourself!', 'B2', 'schreiben', 'schreiben_a1', 'schluss_fazit', 'closing', 'auf sich aufpassen, trennbares Verb.', '{{Pass}} gut {{auf}} dich auf!', array['Pass','gut','auf','dich','auf!']::text[], array['Passt','dir','aufpassen!']::text[], array['schluss','informell','idiomatisch']::text[], 2, '[{"de":"Es wird gerade viel Grippe – pass gut auf dich auf!","en":"There''s a lot of flu going around right now – take good care of yourself!"},{"de":"Bis bald und pass gut auf dich auf!","en":"See you soon and take good care of yourself!"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('86bf7e64c81f', 'Lass uns doch zusammen lernen!', 'lass uns doch zusammen lernen', 'Let''s study together!', 'B2', 'schreiben', 'schreiben_a1', 'vorschlag_bitte', 'suggestion', 'Aufforderung mit lass uns; doch macht es lockerer.', '{{Lass}} uns doch zusammen {{lernen!}}', array['Lass','uns','doch','zusammen','lernen!']::text[], array['Lasst','uns,','lernt']::text[], array['vorschlag','informell']::text[], 2, '[{"de":"Du hast doch auch bald die Prüfung. Lass uns doch zusammen lernen!","en":"You''ve got the exam soon too. Let''s study together!"},{"de":"Allein macht das keinen Spaß – lass uns doch zusammen lernen!","en":"It''s no fun on your own – let''s study together!"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('8f5aa2eec290', 'Wollen wir uns am Wochenende treffen?', 'wollen wir uns am Wochenende treffen', 'Shall we meet up at the weekend?', 'B1', 'schreiben', 'schreiben_a1', 'vorschlag_bitte', 'suggestion', 'Vorschlag mit wollen wir.', '{{Wollen}} wir uns am {{Wochenende}} treffen?', array['Wollen','wir','uns','am','Wochenende','treffen?']::text[], array['Wollt','im','trifft']::text[], array['vorschlag','informell']::text[], 2, '[{"de":"Wollen wir uns am Wochenende treffen und durch die Stadt bummeln?","en":"Shall we meet up at the weekend and stroll through town?"},{"de":"Wollen wir uns am Wochenende treffen? Ich habe lange nichts von dir gehört.","en":"Shall we meet up at the weekend? I haven''t heard from you in ages."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('8f8ddf0aa38a', 'Wie war eigentlich dein Urlaub?', 'wie war eigentlich dein Urlaub', 'How was your holiday, by the way?', 'B2', 'schreiben', 'schreiben_a1', 'einleitung_kontakt', 'opening', 'eigentlich als lockere Partikel.', 'Wie {{war}} eigentlich dein {{Urlaub?}}', array['Wie','war','eigentlich','dein','Urlaub?']::text[], array['waren','deine','Urlaube?']::text[], array['einleitung','informell']::text[], 2, '[{"de":"Wie war eigentlich dein Urlaub? Auf deinen Fotos sah es traumhaft aus.","en":"How was your holiday, by the way? It looked amazing in your photos."},{"de":"Sag mal, wie war eigentlich dein Urlaub in Italien?","en":"Tell me, how was your holiday in Italy, by the way?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('9a338cd9e9d8', 'Ich wollte dir kurz schreiben.', 'ich wollte dir kurz schreiben', 'I wanted to write to you briefly.', 'B2', 'schreiben', 'schreiben_a1', 'einleitung_kontakt', 'opening', 'Präteritum von wollen als höfliche Einleitung.', 'Ich {{wollte}} dir kurz {{schreiben.}}', array['Ich','wollte','dir','kurz','schreiben.']::text[], array['dich','Ihnen','schreibe']::text[], array['einleitung','informell']::text[], 2, '[{"de":"Ich wollte dir kurz schreiben, weil ich am Wochenende in deiner Stadt bin.","en":"I wanted to write to you briefly because I''ll be in your town this weekend."},{"de":"Ich wollte dir kurz schreiben und dir alles Gute zum neuen Job wünschen.","en":"I wanted to write to you briefly and wish you all the best with the new job."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('adf0c4ed2dd0', 'Ich finde es total schade.', 'ich finde es total schade', 'I think it''s a real shame.', 'B2', 'schreiben', 'schreiben_a1', 'danken_bedauern', 'regret', 'total als umgangssprachlicher Verstärker.', 'Ich {{finde}} es {{total}} schade.', array['Ich','finde','es','total','schade.']::text[], array['finden','sehr','das']::text[], array['bedauern','informell']::text[], 2, '[{"de":"Du ziehst weg? Ich finde es total schade, dass wir uns dann seltener sehen.","en":"You''re moving away? I think it''s a real shame that we''ll see each other less then."},{"de":"Schade, dass das Konzert ausfällt – ich finde es total schade.","en":"Too bad the concert is cancelled – I think it''s a real shame."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('b251ba8b526f', 'Schade, dass es nicht geklappt hat.', 'schade dass es nicht geklappt hat', 'It''s a shame it didn''t work out.', 'B2', 'schreiben', 'schreiben_a1', 'danken_bedauern', 'regret', 'Umgangssprachlich klappen für funktionieren.', '{{Schade,}} {{dass}} es nicht geklappt hat.', array['Schade,','dass','es','nicht','geklappt','hat.']::text[], array['das','klappt','haben']::text[], array['bedauern','informell','dass']::text[], 2, '[{"de":"Schade, dass es mit dem Treffen nicht geklappt hat. Vielleicht klappt es ja nächstes Mal.","en":"It''s a shame the meeting didn''t work out. Maybe it''ll work next time."},{"de":"Schade, dass es nicht geklappt hat – ich hatte mich so darauf gefreut.","en":"It''s a shame it didn''t work out – I''d really been looking forward to it."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('e25c5efa602f', 'Melde dich, wenn du Fragen hast!', 'melde dich wenn du Fragen hast', 'Get in touch if you have any questions!', 'B2', 'schreiben', 'schreiben_a1', 'schluss_fazit', 'closing', 'Imperativ + wenn-Satz.', '{{Melde}} dich, {{wenn}} du Fragen hast!', array['Melde','dich,','wenn','du','Fragen','hast!']::text[], array['Melden','wen','hat!']::text[], array['schluss','informell']::text[], 2, '[{"de":"Ich schicke dir die Adresse noch. Melde dich, wenn du Fragen hast!","en":"I''ll still send you the address. Get in touch if you have any questions!"},{"de":"Alles steht im Anhang. Melde dich, wenn du Fragen hast!","en":"Everything''s in the attachment. Get in touch if you have any questions!"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('e28dce3913ea', 'Ich freue mich auf deine Antwort!', 'ich freue mich auf deine Antwort', 'I''m looking forward to your reply!', 'B1', 'schreiben', 'schreiben_a1', 'schluss_fazit', 'closing', 'sich freuen auf + Akkusativ.', 'Ich {{freue}} mich {{auf}} deine Antwort!', array['Ich','freue','mich','auf','deine','Antwort!']::text[], array['freut','über','Antworten']::text[], array['schluss','informell']::text[], 2, '[{"de":"Lass mich wissen, ob das für dich passt. Ich freue mich auf deine Antwort!","en":"Let me know if that works for you. I''m looking forward to your reply!"},{"de":"Schreib mir, sobald du kannst – ich freue mich auf deine Antwort!","en":"Write to me as soon as you can – I''m looking forward to your reply!"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('e47d239d0369', 'Ich freue mich, dass du schreibst.', 'ich freue mich dass du schreibst', 'I''m glad that you''re writing.', 'B1', 'schreiben', 'schreiben_a1', 'einleitung_kontakt', 'opening', 'dass-Satz, typischer Eröffnungssatz.', 'Ich {{freue}} mich, {{dass}} du schreibst.', array['Ich','freue','mich,','dass','du','schreibst.']::text[], array['das','Sie','schreibt']::text[], array['einleitung','informell','dass']::text[], 2, '[{"de":"Ich freue mich, dass du schreibst – ich wollte mich auch schon längst melden.","en":"I''m glad that you''re writing – I''d been meaning to get in touch too."},{"de":"Ich freue mich, dass du schreibst! Erzähl mal, was bei dir so los ist.","en":"I''m glad that you''re writing! Tell me what''s going on with you."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('eac24ba37b50', 'Könntest du mir kurz Bescheid geben?', 'könntest du mir kurz Bescheid geben', 'Could you let me know briefly?', 'B2', 'schreiben', 'schreiben_a1', 'vorschlag_bitte', 'request', 'Konjunktiv II für höflichere Bitte; Bescheid geben.', '{{Könntest}} du mir kurz {{Bescheid}} geben?', array['Könntest','du','mir','kurz','Bescheid','geben?']::text[], array['Kannst','mich','gibst']::text[], array['bitte','informell','konjunktiv']::text[], 2, '[{"de":"Könntest du mir kurz Bescheid geben, wann du ankommst?","en":"Could you let me know briefly when you''re arriving?"},{"de":"Könntest du mir kurz Bescheid geben, ob der Plan so passt?","en":"Could you let me know briefly whether the plan works like this?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('f1a66174cf86', 'Ich würde dir gerne etwas vorschlagen.', 'ich würde dir gerne etwas vorschlagen', 'I would like to suggest something to you.', 'B2', 'schreiben', 'schreiben_a1', 'vorschlag_bitte', 'suggestion', 'Konjunktiv würde + Infinitiv mit trennbarem Verb.', 'Ich {{würde}} dir gerne etwas {{vorschlagen.}}', array['Ich','würde','dir','gerne','etwas','vorschlagen.']::text[], array['werde','dich','vorschlägt']::text[], array['vorschlag','informell','konjunktiv']::text[], 2, '[{"de":"Ich würde dir gerne etwas vorschlagen: Wie wäre ein gemeinsamer Ausflug?","en":"I would like to suggest something to you: how about a trip together?"},{"de":"Bevor wir entscheiden, würde ich dir gerne etwas vorschlagen.","en":"Before we decide, I would like to suggest something to you."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('f23cd5c771e7', 'Es freut mich sehr, von dir zu lesen.', 'es freut mich sehr von dir zu lesen', 'It''s so good to hear from you in writing!', 'B2', 'schreiben', 'schreiben_a1', 'einleitung_kontakt', 'opening', 'unpersönliches es freut mich; Infinitivkonstruktion.', 'Es {{freut}} mich sehr, von dir zu {{lesen.}}', array['Es','freut','mich','sehr,','von','dir','zu','lesen.']::text[], array['freuen','dich','liest.']::text[], array['einleitung','informell']::text[], 2, '[{"de":"Es freut mich sehr, von dir zu lesen! Wir haben uns ewig nicht gehört.","en":"I''m very glad to read from you! We haven''t been in touch for ages."},{"de":"Es freut mich sehr, von dir zu lesen, und dass es dir so gut geht.","en":"I''m very glad to read from you, and that you''re doing so well."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('f7088d46d171', 'Tausend Dank für alles!', 'tausend Dank für alles', 'A thousand thanks for everything!', 'B2', 'schreiben', 'schreiben_a1', 'danken_bedauern', 'thanks', 'Emphatische, lockere Dankesformel.', '{{Tausend}} {{Dank}} für alles!', array['Tausend','Dank','für','alles!']::text[], array['Tausende','Danke','aller']::text[], array['danken','informell']::text[], 2, '[{"de":"Du hast die ganze Woche auf die Kinder aufgepasst – tausend Dank für alles!","en":"You looked after the kids all week – a thousand thanks for everything!"},{"de":"Tausend Dank für alles! Ich melde mich, sobald ich wieder zu Hause bin.","en":"A thousand thanks for everything! I''ll be in touch as soon as I''m home again."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('0b5297e4b47f', 'Ich weiß deine Unterstützung wirklich zu schätzen.', 'ich weiß deine Unterstützung wirklich zu schätzen', 'I really appreciate your support.', 'C1', 'schreiben', 'schreiben_a1', 'danken_bedauern', 'thanks', 'Gehobene Wendung wissen … zu schätzen.', 'Ich {{weiß}} deine Unterstützung wirklich zu {{schätzen.}}', array['Ich','weiß','deine','Unterstützung','wirklich','zu','schätzen.']::text[], array['weiss','schätze','Ihre']::text[], array['danken','informell','idiomatisch']::text[], 3, '[{"de":"Du hast mir echt sehr geholfen – ich weiß deine Unterstützung wirklich zu schätzen.","en":"You really helped me a lot – I really appreciate your support."},{"de":"Danke, dass du immer für mich da bist. Ich weiß deine Unterstützung wirklich zu schätzen.","en":"Thanks for always being there for me. I really appreciate your support."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('18ee39a0310e', 'Lass bald wieder von dir hören!', 'lass bald wieder von dir hören', 'Let me hear from you again soon!', 'B2', 'schreiben', 'schreiben_a1', 'schluss_fazit', 'closing', 'Idiomatischer Abschiedssatz.', '{{Lass}} bald wieder von dir {{hören!}}', array['Lass','bald','wieder','von','dir','hören!']::text[], array['Lasst','dich','hörst!']::text[], array['schluss','informell','idiomatisch']::text[], 3, '[{"de":"Ich denke oft an dich – lass bald wieder von dir hören!","en":"I think of you often – let me hear from you again soon!"},{"de":"Es war schön, von dir zu lesen. Lass bald wieder von dir hören!","en":"It was lovely to hear from you. Let me hear from you again soon!"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('2e835a38e56f', 'Wie wäre es mit Sonntagnachmittag?', 'wie wäre es mit Sonntagnachmittag', 'How about Sunday afternoon?', 'B2', 'schreiben', 'schreiben_a1', 'vorschlag_bitte', 'suggestion', 'Vorschlag mit Wie wäre es mit + Dativ.', 'Wie {{wäre}} es {{mit}} Sonntagnachmittag?', array['Wie','wäre','es','mit','Sonntagnachmittag?']::text[], array['wären','an','über']::text[], array['vorschlag','informell']::text[], 3, '[{"de":"Wir könnten uns am Wochenende treffen. Wie wäre es mit Sonntagnachmittag?","en":"We could meet at the weekend. How about Sunday afternoon?"},{"de":"Wie wäre es mit einem Kaffee nach dem Kurs?","en":"How about a coffee after class?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('2eef706b73f8', 'Es wäre toll, wenn das klappen würde.', 'es wäre toll wenn das klappen würde', 'It would be great if that worked out.', 'C1', 'schreiben', 'schreiben_a1', 'vorschlag_bitte', 'suggestion', 'Doppelter Konjunktiv im wenn-Satz.', 'Es {{wäre}} toll, {{wenn}} das klappen würde.', array['Es','wäre','toll,','wenn','das','klappen','würde.']::text[], array['wären','wen','dass']::text[], array['vorschlag','informell','konjunktiv']::text[], 3, '[{"de":"Ich hoffe, wir bekommen die Wohnung. Es wäre toll, wenn das klappen würde.","en":"I hope we get the flat. It would be great if that worked out."},{"de":"Vielleicht können wir zusammen verreisen – es wäre toll, wenn das klappen würde.","en":"Maybe we can travel together – it would be great if that worked out."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('41c6f7d26a4f', 'Falls es dir passt, komme ich vorbei.', 'falls es dir passt komme ich vorbei', 'If it suits you, I''ll come by.', 'B2', 'schreiben', 'schreiben_a1', 'vorschlag_bitte', 'suggestion', 'falls-Satz mit Inversion im Hauptsatz.', '{{Falls}} es dir passt, {{komme}} ich vorbei.', array['Falls','es','dir','passt,','komme','ich','vorbei.']::text[], array['Fals','dich','vorbeikomme']::text[], array['vorschlag','informell','nebensatz']::text[], 3, '[{"de":"Falls es dir passt, komme ich vorbei und wir lernen zusammen.","en":"If it suits you, I''ll come by and we''ll study together."},{"de":"Am Freitag bin ich frei. Falls es dir passt, komme ich vorbei.","en":"I''m free on Friday. If it suits you, I''ll come by."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('5075a288dd91', 'Ich hätte da einen Vorschlag für dich.', 'ich hätte da einen Vorschlag für dich', 'I''d have a suggestion for you.', 'C1', 'schreiben', 'schreiben_a1', 'vorschlag_bitte', 'suggestion', 'Konjunktiv hätte als höfliche Einleitung.', 'Ich {{hätte}} da einen {{Vorschlag}} für dich.', array['Ich','hätte','da','einen','Vorschlag','für','dich.']::text[], array['habe','dir','Vorschläge']::text[], array['vorschlag','informell','konjunktiv']::text[], 3, '[{"de":"Ich hätte da einen Vorschlag für dich: Lass uns einfach gemeinsam kochen.","en":"I''d have a suggestion for you: let''s just cook together."},{"de":"Wegen deines Geburtstags – ich hätte da einen Vorschlag für dich.","en":"About your birthday – I''d have a suggestion for you."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('69579ea5ae99', 'Hättest du Lust, mitzukommen?', 'hättest du Lust mitzukommen', 'Would you fancy coming along?', 'C1', 'schreiben', 'schreiben_a1', 'vorschlag_bitte', 'suggestion', 'Konjunktiv Hättest du Lust + zu-Infinitiv mit trennbarem Verb.', '{{Hättest}} du Lust, {{mitzukommen?}}', array['Hättest','du','Lust,','mitzukommen?']::text[], array['Hast','Lus,','mitkommen?']::text[], array['vorschlag','informell','konjunktiv']::text[], 3, '[{"de":"Wir gehen heute Abend ins Konzert. Hättest du Lust, mitzukommen?","en":"We''re going to a concert tonight. Would you fancy coming along?"},{"de":"Hättest du Lust, mitzukommen? Es wird bestimmt lustig.","en":"Would you fancy coming along? It''s sure to be fun."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('74a695f02246', 'Es würde mir sehr viel bedeuten.', 'es würde mir sehr viel bedeuten', 'It would mean a great deal to me.', 'C1', 'schreiben', 'schreiben_a1', 'danken_bedauern', 'thanks', 'jdm. etw. bedeuten; emotionaler Ausdruck.', 'Es {{würde}} mir sehr viel {{bedeuten.}}', array['Es','würde','mir','sehr','viel','bedeuten.']::text[], array['werde','mich','bedeutet']::text[], array['danken','informell','idiomatisch']::text[], 3, '[{"de":"Wenn du am Wochenende vorbeikommen könntest, es würde mir sehr viel bedeuten.","en":"If you could come by at the weekend, it would mean a great deal to me."},{"de":"Komm doch zu meiner Feier – es würde mir sehr viel bedeuten.","en":"Do come to my celebration – it would mean a great deal to me."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('79336fb49bd7', 'Ich melde mich, weil ich eine Frage habe.', 'ich melde mich weil ich eine Frage habe', 'I''m getting in touch because I have a question.', 'B2', 'schreiben', 'schreiben_a1', 'einleitung_kontakt', 'opening', 'weil-Satz mit Verb am Ende.', 'Ich {{melde}} mich, {{weil}} ich eine Frage habe.', array['Ich','melde','mich,','weil','ich','eine','Frage','habe.']::text[], array['meldet','dass','hat']::text[], array['einleitung','informell','nebensatz']::text[], 3, '[{"de":"Ich melde mich, weil ich eine Frage zu unserem Treffen am Samstag habe.","en":"I''m getting in touch because I have a question about our meeting on Saturday."},{"de":"Ich melde mich, weil ich eine Frage habe: Bringst du deinen Hund mit?","en":"I''m getting in touch because I have a question: are you bringing your dog?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('c04b34f62306', 'Es ist schon viel zu lange her.', 'es ist schon viel zu lange her', 'It''s been far too long.', 'B1', 'schreiben', 'schreiben_a1', 'einleitung_kontakt', 'opening', 'Idiomatischer Einstieg nach langer Funkstille.', 'Es ist {{schon}} viel zu {{lange}} her.', array['Es','ist','schon','viel','zu','lange','her.']::text[], array['seit','hier','sehr']::text[], array['einleitung','informell','idiomatisch']::text[], 3, '[{"de":"Wir sollten uns endlich mal wiedersehen, es ist schon viel zu lange her.","en":"We really should meet up again at last, it''s been far too long."},{"de":"Hallo Jonas! Es ist schon viel zu lange her, dass wir uns zuletzt gesehen haben.","en":"Hi Jonas! It''s been far too long since we last saw each other."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('cc6bfbc43c5e', 'Es tut mir aufrichtig leid, dich zu enttäuschen.', 'es tut mir aufrichtig leid dich zu enttäuschen', 'I''m sincerely sorry to disappoint you.', 'C1', 'schreiben', 'schreiben_a1', 'danken_bedauern', 'regret', 'aufrichtig als gehobener Verstärker; Infinitivkonstruktion.', 'Es tut mir {{aufrichtig}} leid, dich zu {{enttäuschen.}}', array['Es','tut','mir','aufrichtig','leid,','dich','zu','enttäuschen.']::text[], array['dir','enttäuscht','leiht,']::text[], array['bedauern','informell','idiomatisch']::text[], 3, '[{"de":"Ich kann am Samstag doch nicht mitkommen. Es tut mir aufrichtig leid, dich zu enttäuschen.","en":"I can''t come along on Saturday after all. I''m sincerely sorry to disappoint you."},{"de":"Es tut mir aufrichtig leid, dich zu enttäuschen, aber ich muss leider absagen.","en":"I''m sincerely sorry to disappoint you, but I unfortunately have to cancel."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('cd34115a751f', 'Es wäre super, wenn du Bescheid sagst.', 'es wäre super wenn du Bescheid sagst', 'It would be great if you let me know.', 'C1', 'schreiben', 'schreiben_a1', 'vorschlag_bitte', 'request', 'Konjunktiv + wenn-Satz.', 'Es {{wäre}} super, {{wenn}} du Bescheid sagst.', array['Es','wäre','super,','wenn','du','Bescheid','sagst.']::text[], array['wären','wen','sagt']::text[], array['bitte','informell','konjunktiv']::text[], 3, '[{"de":"Es wäre super, wenn du Bescheid sagst, sobald du den Termin kennst.","en":"It would be great if you let me know as soon as you know the date."},{"de":"Ich plane das Essen für sechs Personen. Es wäre super, wenn du Bescheid sagst, ob du kommst.","en":"I''m planning the meal for six people. It would be great if you let me know whether you''re coming."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('ead0da3afe2a', 'Sag mir einfach, was dir besser passt.', 'sag mir einfach was dir besser passt', 'Just tell me what suits you better.', 'B2', 'schreiben', 'schreiben_a1', 'vorschlag_bitte', 'request', 'Imperativ + indirekter Fragesatz.', '{{Sag}} mir einfach, was dir besser {{passt.}}', array['Sag','mir','einfach,','was','dir','besser','passt.']::text[], array['Sage','dich','passen']::text[], array['bitte','informell']::text[], 3, '[{"de":"Ich habe am Freitag und am Samstag Zeit. Sag mir einfach, was dir besser passt.","en":"I''m free on Friday and Saturday. Just tell me what suits you better."},{"de":"Wir können essen gehen oder kochen – sag mir einfach, was dir besser passt.","en":"We can eat out or cook – just tell me what suits you better."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('f4c25d56ebfb', 'Ich drücke dir die Daumen!', 'ich drücke dir die Daumen', 'I''m keeping my fingers crossed for you!', 'C1', 'schreiben', 'schreiben_a1', 'schluss_fazit', 'closing', 'Idiomatische Redewendung jdm. die Daumen drücken.', 'Ich {{drücke}} dir die {{Daumen!}}', array['Ich','drücke','dir','die','Daumen!']::text[], array['drückst','dich','Daum!']::text[], array['schluss','informell','idiomatisch']::text[], 3, '[{"de":"Morgen hast du deine Prüfung, oder? Ich drücke dir die Daumen!","en":"You''ve got your exam tomorrow, right? I''m keeping my fingers crossed for you!"},{"de":"Viel Erfolg beim Vorstellungsgespräch – ich drücke dir die Daumen!","en":"Good luck with the job interview – I''m keeping my fingers crossed for you!"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('350758ada03e', 'Ich kann dir gar nicht genug danken.', 'ich kann dir gar nicht genug danken', 'I can''t thank you enough.', 'B2', 'schreiben', 'schreiben_a1', 'danken_bedauern', 'thanks', 'Idiomatische Übertreibung des Dankes.', 'Ich {{kann}} dir gar nicht genug {{danken.}}', array['Ich','kann','dir','gar','nicht','genug','danken.']::text[], array['dich','Ihnen','danke']::text[], array['danken','informell','idiomatisch']::text[], 4, '[{"de":"Du hast mir in einer schweren Zeit geholfen – ich kann dir gar nicht genug danken.","en":"You helped me through a hard time – I can''t thank you enough."},{"de":"Ich kann dir gar nicht genug danken, dass du auf meine Katze aufgepasst hast.","en":"I can''t thank you enough for looking after my cat."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('3c71fc741de3', 'Mach''s gut und pass auf dich auf!', 'mach''s gut und pass auf dich auf', 'Take care and look after yourself!', 'B2', 'schreiben', 'schreiben_a1', 'schluss_fazit', 'closing', 'Sehr umgangssprachlich; doppelter Imperativ.', '{{Mach''s}} gut und {{pass}} auf dich auf!', array['Mach''s','gut','und','pass','auf','dich','auf!']::text[], array['Mache','dir','aufpassen!']::text[], array['schluss','informell','idiomatisch']::text[], 4, '[{"de":"Ich muss leider Schluss machen. Mach''s gut und pass auf dich auf!","en":"I have to wrap up now, unfortunately. Take care of yourself!"},{"de":"Bis zum nächsten Mal – mach''s gut und pass auf dich auf!","en":"Until next time – take care of yourself!"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('6d505e8597a2', 'Hast du nicht Lust, mal vorbeizuschauen?', 'hast du nicht Lust mal vorbeizuschauen', 'Don''t you feel like dropping by sometime?', 'C2', 'schreiben', 'schreiben_a1', 'vorschlag_bitte', 'suggestion', 'Negationsfrage als idiomatische Einladung.', '{{Hast}} du nicht Lust, mal {{vorbeizuschauen?}}', array['Hast','du','nicht','Lust,','mal','vorbeizuschauen?']::text[], array['Lus,','vorbeischauen?','Mal']::text[], array['vorschlag','informell','idiomatisch']::text[], 4, '[{"de":"Wir sehen uns kaum noch. Hast du nicht Lust, mal vorbeizuschauen?","en":"We hardly see each other anymore. Don''t you feel like dropping by sometime?"},{"de":"Mein neues Café ist gleich um die Ecke – hast du nicht Lust, mal vorbeizuschauen?","en":"My new café is just around the corner – don''t you feel like dropping by sometime?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('101343bbf55c', 'Das sehe ich anders.', 'das sehe ich anders', 'I see that differently.', 'B1', 'schreiben', 'schreiben_a2', 'widersprechen', 'disagreement', 'Kurze Widerspruchsformel.', '{{Das}} sehe ich anders.', array['Das','sehe','ich','anders.']::text[], array['dass','sieht','andere.']::text[], array['widerspruch']::text[], 1, '[{"de":"Das sehe ich anders, denn die Kosten wären viel zu hoch.","en":"I see that differently, because the costs would be far too high."},{"de":"Du findest das Konzert teuer? Das sehe ich anders.","en":"You think the concert is expensive? I see that differently."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('135f6c586a87', 'Das stimmt meiner Ansicht nach nicht.', 'das stimmt … nicht', 'That is not correct in my view.', 'B1', 'schreiben', 'schreiben_a2', 'widersprechen', 'disagreement', 'Höfliche Verneinung mit ‘meiner Ansicht nach’.', '{{Das}} stimmt meiner Ansicht nach nicht.', array['Das','stimmt','meiner','Ansicht','nach','nicht.']::text[], array['dass','stimmen','meinem']::text[], array['widerspruch']::text[], 1, '[{"de":"Das stimmt meiner Ansicht nach nicht, denn die Zahlen zeigen das Gegenteil.","en":"That is not correct in my view, because the figures show the opposite."},{"de":"Soziale Medien machen nur einsam? Das stimmt meiner Ansicht nach nicht.","en":"Social media only makes you lonely? That is not correct in my view."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('161750de656c', 'Da hast du völlig recht.', 'da hast du recht', 'You are completely right there.', 'B1', 'schreiben', 'schreiben_a2', 'zustimmen', 'agreement', '‘recht haben’ kleingeschrieben.', 'Da hast du völlig {{recht.}}', array['Da','hast','du','völlig','recht.']::text[], array['habt','dir','Recht.']::text[], array['zustimmung']::text[], 1, '[{"de":"Da hast du völlig recht, das sollten wir unbedingt ändern.","en":"You are completely right there, we should definitely change that."},{"de":"Mit deinem Einwand hast du völlig recht.","en":"You are completely right with your objection."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('17046b0b2769', 'Ein weiterer Punkt ist der Umweltschutz.', 'ein weiterer Punkt ist …', 'A further point is environmental protection.', 'B1', 'schreiben', 'schreiben_a2', 'argumentieren', 'argument', '‘ein weiterer Punkt’.', 'Ein {{weiterer}} Punkt ist der Umweltschutz.', array['Ein','weiterer','Punkt','ist','der','Umweltschutz.']::text[], array['weitere','Punkte','die']::text[], array['argument']::text[], 1, '[{"de":"Ein weiterer Punkt ist der Umweltschutz, den viele Firmen noch ignorieren.","en":"A further point is environmental protection, which many companies still ignore."},{"de":"Ein weiterer Punkt ist, dass öffentliche Verkehrsmittel oft zu teuer sind.","en":"A further point is that public transport is often too expensive."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('1aa1e4a18f36', 'Natürlich ist nicht alles perfekt.', 'natürlich ist nicht alles perfekt', 'Of course, not everything is perfect.', 'B1', 'schreiben', 'schreiben_a2', 'konzession', 'concession', 'Einfaches Zugeständnis.', '{{Natürlich}} ist nicht alles perfekt.', array['Natürlich','ist','nicht','alles','perfekt.']::text[], array['Natürliche','sind','perfekte.']::text[], array['konzession']::text[], 1, '[{"de":"Natürlich ist nicht alles perfekt, aber insgesamt bin ich zufrieden.","en":"Of course, not everything is perfect, but overall I am satisfied."},{"de":"Natürlich ist nicht alles perfekt an diesem Plan, trotzdem finde ich ihn gut.","en":"Of course, not everything about this plan is perfect, but I still think it is good."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('20da51c102d6', 'Deshalb sollten wir mehr Bäume pflanzen.', 'deshalb …', 'Therefore we should plant more trees.', 'B1', 'schreiben', 'schreiben_a2', 'argumentieren', 'argument', 'Konsekutiv ‘deshalb’ + Inversion.', '{{Deshalb}} sollten wir mehr Bäume pflanzen.', array['Deshalb','sollten','wir','mehr','Bäume','pflanzen.']::text[], array['Deshalbe','sollen','Bäumen']::text[], array['argument']::text[], 1, '[{"de":"Die Städte werden immer wärmer. Deshalb sollten wir mehr Bäume pflanzen.","en":"Cities are getting warmer and warmer. Therefore we should plant more trees."},{"de":"Deshalb sollten wir mehr Bäume pflanzen, vor allem in den Innenstädten.","en":"Therefore we should plant more trees, especially in the city centres."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('2b4f1676e598', 'Alles in allem bin ich dafür.', 'alles in allem …', 'All in all, I am in favor.', 'B1', 'schreiben', 'schreiben_a2', 'schluss_fazit', 'conclusion', '‘alles in allem’ Resümee.', '{{Alles}} {{in}} {{allem}} bin ich dafür.', array['Alles','in','allem','bin','ich','dafür.']::text[], array['alle','im','dagegen.']::text[], array['fazit']::text[], 1, '[{"de":"Alles in allem bin ich dafür, das Projekt weiterzuführen.","en":"All in all, I am in favor of continuing the project."},{"de":"Alles in allem war es eine gute Entscheidung.","en":"All in all, it was a good decision."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('2ded8f1b3cb4', 'Da gebe ich dir recht.', 'da gebe ich dir recht', 'I agree with you on that.', 'B1', 'schreiben', 'schreiben_a2', 'zustimmen', 'agreement', '‘jemandem recht geben’.', 'Da gebe ich dir {{recht.}}', array['Da','gebe','ich','dir','recht.']::text[], array['gibt','dich','Recht.']::text[], array['zustimmung']::text[], 1, '[{"de":"Da gebe ich dir recht, der Preis ist einfach zu hoch.","en":"I agree with you on that, the price is simply too high."},{"de":"Das ist ein gutes Argument, da gebe ich dir recht.","en":"That is a good argument, I agree with you on that."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('3401f8d72999', 'Ein wichtiger Grund dafür ist die Sicherheit.', 'ein wichtiger Grund dafür ist …', 'An important reason for this is safety.', 'B1', 'schreiben', 'schreiben_a2', 'argumentieren', 'argument', '‘ein Grund dafür’.', 'Ein {{wichtiger}} Grund {{dafür}} ist die Sicherheit.', array['Ein','wichtiger','Grund','dafür','ist','die','Sicherheit.']::text[], array['wichtige','Gründe','dazu']::text[], array['argument']::text[], 1, '[{"de":"Ein wichtiger Grund dafür ist die Sicherheit der Kinder im Straßenverkehr.","en":"An important reason for this is the safety of children in traffic."},{"de":"Viele Menschen ziehen aufs Land. Ein wichtiger Grund dafür ist die Ruhe.","en":"Many people are moving to the countryside. An important reason for this is the quiet."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('34436a1da4ea', 'Meiner Meinung nach lernt man Sprachen am besten im Ausland.', 'meiner Meinung nach …', 'In my opinion, you learn languages best abroad.', 'B1', 'schreiben', 'schreiben_a2', 'meinung_aeussern', 'opinion', '‘meiner Meinung nach’ + Inversion.', '{{Meiner}} {{Meinung}} nach lernt man Sprachen am besten im Ausland.', array['Meiner','Meinung','nach','lernt','man','Sprachen','am','besten','im','Ausland.']::text[], array['nach','Meinungen','bestens']::text[], array['meinung']::text[], 1, '[{"de":"Meiner Meinung nach sollten Schulen mehr praktische Fächer anbieten.","en":"In my opinion, schools should offer more practical subjects."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('34a585bef396', 'In letzter Zeit wird viel über Plastik diskutiert.', 'in letzter Zeit wird viel über … diskutiert', 'Recently, there has been much discussion about plastic.', 'B1', 'schreiben', 'schreiben_a2', 'einleitung_kontakt', 'intro', 'Themeneinstieg mit Passiv.', 'In {{letzter}} {{Zeit}} {{wird}} viel über Plastik diskutiert.', array['In','letzter','Zeit','wird','viel','über','Plastik','diskutiert.']::text[], array['letzte','werden','diskutieren.']::text[], array['einleitung']::text[], 1, '[{"de":"In letzter Zeit wird viel über Plastik diskutiert, vor allem über Verpackungen.","en":"Recently, there has been much discussion about plastic, especially about packaging."},{"de":"In letzter Zeit wird viel über das Homeoffice diskutiert.","en":"Recently, there has been much discussion about working from home."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('5169772e1389', 'Ich finde es gut, dass es Recyclinghöfe gibt.', 'ich finde es gut, dass …', 'I think it is good that there are recycling centers.', 'B1', 'schreiben', 'schreiben_a2', 'meinung_aeussern', 'opinion', '‘es gut finden, dass’.', 'Ich finde es gut, {{dass}} es Recyclinghöfe gibt.', array['Ich','finde','es','gut,','dass','es','Recyclinghöfe','gibt.']::text[], array['das','gute','geben']::text[], array['meinung']::text[], 1, '[{"de":"Ich finde es gut, dass es Recyclinghöfe gibt, denn so wird weniger weggeworfen.","en":"I think it is good that there are recycling centers, because that way less is thrown away."},{"de":"Ich finde es gut, dass immer mehr Menschen mit dem Rad fahren.","en":"I think it is good that more and more people are cycling."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('80b23900aacb', 'Viele Menschen fragen sich, ob das sinnvoll ist.', 'viele Menschen fragen sich, ob …', 'Many people wonder whether that makes sense.', 'B1', 'schreiben', 'schreiben_a2', 'einleitung_kontakt', 'intro', 'Indirekte Frage mit ‘ob’.', 'Viele Menschen fragen sich, {{ob}} das sinnvoll ist.', array['Viele','Menschen','fragen','sich,','ob','das','sinnvoll','ist.']::text[], array['Vieles','fragt','op']::text[], array['einleitung']::text[], 1, '[{"de":"Das neue Gesetz soll vieles verbessern. Viele Menschen fragen sich, ob das wirklich sinnvoll ist.","en":"The new law is supposed to improve a lot. Many people wonder whether that really makes sense."},{"de":"Viele Menschen fragen sich, ob sich der hohe Preis am Ende lohnt.","en":"Many people wonder whether the high price is worth it in the end."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('860fb6ab6cff', 'Zweitens ist es auch gesünder.', 'zweitens …', 'Secondly, it is also healthier.', 'B1', 'schreiben', 'schreiben_a2', 'argumentieren', 'argument', 'Aufzählung mit ‘zweitens’ + Inversion.', '{{Zweitens}} ist es auch gesünder.', array['Zweitens','ist','es','auch','gesünder.']::text[], array['Zweite','sind','gesund']::text[], array['argument']::text[], 1, '[{"de":"Radfahren spart Geld. Zweitens ist es auch gesünder.","en":"Cycling saves money. Secondly, it is also healthier."},{"de":"Erstens ist es billiger, und zweitens ist es auch gesünder.","en":"Firstly it''s cheaper, and secondly, it is also healthier."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('8c2231d164ab', 'Ich glaube, dass das Homeoffice die Zukunft ist.', 'ich glaube, dass …', 'I believe that working from home is the future.', 'B1', 'schreiben', 'schreiben_a2', 'meinung_aeussern', 'opinion', '‘glauben, dass’ einleitend.', 'Ich glaube, {{dass}} das Homeoffice die Zukunft ist.', array['Ich','glaube,','dass','das','Homeoffice','die','Zukunft','ist.']::text[], array['das','glauben','den']::text[], array['meinung']::text[], 1, '[{"de":"Ich glaube, dass viele Firmen bald komplett auf Homeoffice umsteigen werden.","en":"I believe that many companies will soon switch completely to working from home."},{"de":"Ich glaube, dass wir das Problem zusammen lösen können.","en":"I believe that we can solve the problem together."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('8d146060d57d', 'Da bin ich anderer Meinung.', 'da bin ich anderer Meinung', 'I am of a different opinion there.', 'B1', 'schreiben', 'schreiben_a2', 'widersprechen', 'disagreement', '‘anderer Meinung sein’ Genitiv.', 'Da bin ich {{anderer}} {{Meinung.}}', array['Da','bin','ich','anderer','Meinung.']::text[], array['andere','Meinungen','bist']::text[], array['widerspruch']::text[], 1, '[{"de":"Da bin ich anderer Meinung, denn die Risiken sind zu groß.","en":"I am of a different opinion there, because the risks are too great."},{"de":"Du findest das langweilig? Da bin ich anderer Meinung.","en":"You find that boring? I am of a different opinion there."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('95076d8e348f', 'Ich stimme dir völlig zu.', 'ich stimme … zu', 'I completely agree with you.', 'B1', 'schreiben', 'schreiben_a2', 'zustimmen', 'agreement', '‘jemandem zustimmen’ + Dativ, trennbar.', 'Ich {{stimme}} dir völlig {{zu.}}', array['Ich','stimme','dir','völlig','zu.']::text[], array['dich','stimmt','ab.']::text[], array['zustimmung']::text[], 1, '[{"de":"Ich stimme dir völlig zu, der Vorschlag ist sinnvoll.","en":"I completely agree with you, the proposal makes sense."},{"de":"Was die Öffnungszeiten betrifft, stimme ich dir völlig zu.","en":"As far as the opening hours are concerned, I completely agree with you."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('968939e50c26', 'Ich bin nicht überzeugt davon.', 'ich bin nicht überzeugt davon', 'I am not convinced of it.', 'B1', 'schreiben', 'schreiben_a2', 'widersprechen', 'disagreement', 'Verneinte Überzeugung.', 'Ich bin nicht {{überzeugt}} davon.', array['Ich','bin','nicht','überzeugt','davon.']::text[], array['nichts','überzeugen','dafür.']::text[], array['widerspruch']::text[], 1, '[{"de":"Ich bin nicht überzeugt davon, dass diese Methode wirklich funktioniert.","en":"I am not convinced that this method really works."},{"de":"Der Vorschlag klingt gut, aber ich bin nicht überzeugt davon.","en":"The proposal sounds good, but I am not convinced of it."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('99eca71bc961', 'Ich finde, dass man mehr lesen sollte.', 'ich finde, dass …', 'I think that one should read more.', 'B1', 'schreiben', 'schreiben_a2', 'meinung_aeussern', 'opinion', '‘finden, dass’ mit Modalverb am Ende.', 'Ich finde, {{dass}} man mehr lesen sollte.', array['Ich','finde,','dass','man','mehr','lesen','sollte.']::text[], array['das','finden','sollen']::text[], array['meinung']::text[], 1, '[{"de":"Ich finde, dass man im Urlaub auch mal das Handy ausschalten sollte.","en":"I think that one should also turn off the phone on vacation sometimes."},{"de":"Ich finde, dass man Kindern mehr Zeit zum Spielen geben sollte.","en":"I think that one should give children more time to play."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('a6e15222f162', 'Ich denke, dass soziale Medien viele Vorteile haben.', 'ich denke, dass …', 'I think that social media has many advantages.', 'B1', 'schreiben', 'schreiben_a2', 'meinung_aeussern', 'opinion', '‘denken, dass’ mit Verb am Ende.', 'Ich denke, {{dass}} soziale Medien viele Vorteile haben.', array['Ich','denke,','dass','soziale','Medien','viele','Vorteile','haben.']::text[], array['das','denken','Vorteil']::text[], array['meinung']::text[], 1, '[{"de":"Ich denke, dass soziale Medien viele junge Leute verbinden.","en":"I think that social media connects many young people."},{"de":"Ich denke, dass diese Lösung am Ende billiger ist.","en":"I think that this solution is cheaper in the end."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('ac4b6e79d7f4', 'Ein gutes Beispiel dafür ist die Schweiz.', 'ein gutes Beispiel dafür ist …', 'A good example of this is Switzerland.', 'B1', 'schreiben', 'schreiben_a2', 'beispiele', 'example', '‘ein Beispiel dafür’.', 'Ein {{gutes}} Beispiel {{dafür}} ist die Schweiz.', array['Ein','gutes','Beispiel','dafür','ist','die','Schweiz.']::text[], array['gute','Beispiele','dazu']::text[], array['beispiel']::text[], 1, '[{"de":"Viele Länder setzen auf direkte Demokratie. Ein gutes Beispiel dafür ist die Schweiz.","en":"Many countries rely on direct democracy. A good example of this is Switzerland."},{"de":"Manche Städte fördern das Fahrrad stark. Ein gutes Beispiel dafür ist Amsterdam.","en":"Some cities strongly promote cycling. A good example of this is Amsterdam."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('b00636429b11', 'Das finde ich auch.', 'das finde ich auch', 'I think so too.', 'B1', 'schreiben', 'schreiben_a2', 'zustimmen', 'agreement', 'Kurze Zustimmung.', '{{Das}} finde ich auch.', array['Das','finde','ich','auch.']::text[], array['dass','findet','auf.']::text[], array['zustimmung']::text[], 1, '[{"de":"Das finde ich auch, deshalb sollten wir es so machen.","en":"I think so too, so we should do it that way."},{"de":"Mehr Grünflächen in der Stadt? Das finde ich auch.","en":"More green spaces in the city? I think so too."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('b9fed52054dc', 'Das Thema beschäftigt mich schon lange.', 'das Thema beschäftigt mich …', 'The topic has occupied me for a long time.', 'B1', 'schreiben', 'schreiben_a2', 'einleitung_kontakt', 'intro', 'Persönlicher Bezug zum Thema.', '{{Das}} Thema beschäftigt mich schon lange.', array['Das','Thema','beschäftigt','mich','schon','lange.']::text[], array['dass','beschäftigen','mir']::text[], array['einleitung']::text[], 1, '[{"de":"Das Thema Umweltschutz beschäftigt mich schon lange, denn ich wohne nahe an einer großen Straße.","en":"The topic of environmental protection has occupied me for a long time, because I live close to a big road."},{"de":"Das Thema beschäftigt mich schon lange, deshalb möchte ich gern meine Meinung dazu schreiben.","en":"The topic has occupied me for a long time, so I would like to share my opinion on it."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('c079aee9c299', 'Natürlich gibt es auch Nachteile.', 'natürlich gibt es auch …', 'Of course, there are also disadvantages.', 'B1', 'schreiben', 'schreiben_a2', 'konzession', 'concession', 'Einräumen mit ‘natürlich’.', '{{Natürlich}} gibt es auch Nachteile.', array['Natürlich','gibt','es','auch','Nachteile.']::text[], array['Natürliche','gibt','Nachteil.']::text[], array['konzession']::text[], 1, '[{"de":"Das Auto bringt viele Vorteile. Natürlich gibt es auch Nachteile, zum Beispiel die Kosten.","en":"The car brings many advantages. Of course, there are also disadvantages, for example the costs."},{"de":"Natürlich gibt es auch Nachteile, wenn man im Ausland studiert.","en":"Of course, there are also disadvantages to studying abroad."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('c5c0ae4af38c', 'Ich kann dir da nicht zustimmen.', 'ich kann dir nicht zustimmen', 'I cannot agree with you there.', 'B1', 'schreiben', 'schreiben_a2', 'widersprechen', 'disagreement', 'Verneinte Zustimmung, ‘zustimmen’ + Dativ.', 'Ich kann {{dir}} da nicht zustimmen.', array['Ich','kann','dir','da','nicht','zustimmen.']::text[], array['dich','kannst','ab.']::text[], array['widerspruch']::text[], 1, '[{"de":"Ich kann dir da nicht zustimmen, denn die Zahlen zeigen etwas anderes.","en":"I cannot agree with you there, because the figures show something different."},{"de":"In diesem Punkt kann ich dir leider nicht zustimmen.","en":"On this point I unfortunately cannot agree with you."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('c9a594112ee6', 'Das sehe ich genauso.', 'das sehe ich genauso', 'I see it exactly the same way.', 'B1', 'schreiben', 'schreiben_a2', 'zustimmen', 'agreement', 'Kurze Zustimmungsformel.', '{{Das}} sehe ich genauso.', array['Das','sehe','ich','genauso.']::text[], array['dass','sieht','genau.']::text[], array['zustimmung']::text[], 1, '[{"de":"Das sehe ich genauso, vor allem im Hinblick auf die Kosten.","en":"I see it exactly the same way, especially with regard to the costs."},{"de":"Du findest die Idee gut? Das sehe ich genauso.","en":"You think the idea is good? I see it exactly the same way."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('c9ded7e99d2b', 'Zusammenfassend lässt sich sagen, dass beide recht haben.', 'zusammenfassend lässt sich sagen, dass …', 'In summary, one can say that both are right.', 'B1', 'schreiben', 'schreiben_a2', 'schluss_fazit', 'conclusion', 'Standard-Fazit-Einleitung.', '{{Zusammenfassend}} lässt sich sagen, {{dass}} beide recht haben.', array['Zusammenfassend','lässt','sich','sagen,','dass','beide','recht','haben.']::text[], array['Zusammenfassen','lasst','das']::text[], array['fazit']::text[], 1, '[{"de":"Zusammenfassend lässt sich sagen, dass beide Seiten gute Argumente haben.","en":"In summary, one can say that both sides have good arguments."},{"de":"Zusammenfassend lässt sich sagen, dass der Plan mehr Vorteile bringt.","en":"In summary, one can say that the plan brings more advantages."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('cace38968cf4', 'Zum Beispiel kann man Fahrrad fahren.', 'zum Beispiel …', 'For example, one can ride a bike.', 'B1', 'schreiben', 'schreiben_a2', 'beispiele', 'example', '‘zum Beispiel’ + Inversion.', '{{Zum}} {{Beispiel}} kann man Fahrrad fahren.', array['Zum','Beispiel','kann','man','Fahrrad','fahren.']::text[], array['Zur','Beispiele','fährt']::text[], array['beispiel']::text[], 1, '[{"de":"In der Freizeit kann man viel unternehmen. Zum Beispiel kann man Fahrrad fahren oder schwimmen gehen.","en":"There is a lot you can do in your free time. For example, you can ride a bike or go swimming."},{"de":"Es gibt viele Möglichkeiten, Energie zu sparen. Zum Beispiel kann man das Licht ausschalten.","en":"There are many ways to save energy. For example, you can turn off the light."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('cd956f572ef7', 'Erstens spart das viel Zeit.', 'erstens …', 'Firstly, that saves a lot of time.', 'B1', 'schreiben', 'schreiben_a2', 'argumentieren', 'argument', 'Aufzählung mit ‘erstens’ + Inversion.', '{{Erstens}} spart das viel Zeit.', array['Erstens','spart','das','viel','Zeit.']::text[], array['Erste','sparen','vieles']::text[], array['argument']::text[], 1, '[{"de":"Online einzukaufen hat Vorteile. Erstens spart das viel Zeit.","en":"Shopping online has advantages. Firstly, that saves a lot of time."},{"de":"Erstens spart das viel Zeit, und außerdem ist es bequemer.","en":"Firstly, that saves a lot of time, and besides it''s more comfortable."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('d5235f159c7a', 'Meiner Meinung nach ist das Rauchverbot sinnvoll.', 'meiner Meinung nach …', 'In my opinion, the smoking ban makes sense.', 'B1', 'schreiben', 'schreiben_a2', 'meinung_aeussern', 'opinion', 'Feste Wendung ‘meiner Meinung nach’.', '{{Meiner}} {{Meinung}} nach ist das Rauchverbot sinnvoll.', array['Meiner','Meinung','nach','ist','das','Rauchverbot','sinnvoll.']::text[], array['nach','Meinungen','sinnvolle']::text[], array['meinung']::text[], 1, '[{"de":"Meiner Meinung nach ist das Rauchverbot in Restaurants sinnvoll.","en":"In my opinion, the smoking ban in restaurants makes sense."},{"de":"Meiner Meinung nach sollten wir mehr Fahrradwege bauen.","en":"In my opinion, we should build more bike paths."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('d66227df3bde', 'Zwar ist es teuer, aber es lohnt sich.', 'zwar …, aber …', 'It is true that it is expensive, but it is worth it.', 'B1', 'schreiben', 'schreiben_a2', 'konzession', 'concession', '‘zwar …, aber …’ Konzessivpaar.', '{{Zwar}} ist es teuer, {{aber}} es lohnt sich.', array['Zwar','ist','es','teuer,','aber','es','lohnt','sich.']::text[], array['Zwei','sind','lohne']::text[], array['konzession']::text[], 1, '[{"de":"Zwar ist ein Sprachkurs teuer, aber er lohnt sich für den Beruf.","en":"A language course is expensive, true, but it is worth it for your career."},{"de":"Zwar dauert die Reise lange, aber die Landschaft ist wunderschön.","en":"The journey takes a long time, true, but the scenery is beautiful."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('d85064663e61', 'Heute möchte ich über das Reisen schreiben.', 'heute möchte ich über … schreiben', 'Today I would like to write about traveling.', 'B1', 'schreiben', 'schreiben_a2', 'einleitung_kontakt', 'intro', 'Persönlicher Themeneinstieg.', '{{Heute}} {{möchte}} ich über das Reisen schreiben.', array['Heute','möchte','ich','über','das','Reisen','schreiben.']::text[], array['Heut','möchten','den']::text[], array['einleitung']::text[], 1, '[{"de":"Heute möchte ich über das Reisen schreiben, weil ich gerade viel unterwegs bin.","en":"Today I would like to write about traveling, because I am on the road a lot at the moment."},{"de":"Heute möchte ich über das Thema Sport in der Schule schreiben.","en":"Today I would like to write about the topic of sport in school."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('ef1fc308903c', 'Außerdem ist es viel günstiger.', 'außerdem …', 'Besides, it is much cheaper.', 'B1', 'schreiben', 'schreiben_a2', 'argumentieren', 'argument', 'Hinzufügen mit ‘außerdem’ + Inversion.', '{{Außerdem}} ist es viel günstiger.', array['Außerdem','ist','es','viel','günstiger.']::text[], array['Außer','sind','günstige']::text[], array['argument']::text[], 1, '[{"de":"Das Fahrrad ist umweltfreundlich. Außerdem ist es viel günstiger.","en":"The bike is environmentally friendly. Besides, it is much cheaper."},{"de":"Außerdem ist es viel günstiger, wenn man früh bucht.","en":"Besides, it is much cheaper if you book early."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('f2557311d2f1', 'Zum Schluss möchte ich noch etwas hinzufügen.', 'zum Schluss möchte ich …', 'Finally, I would like to add something.', 'B1', 'schreiben', 'schreiben_a2', 'schluss_fazit', 'conclusion', '‘zum Schluss’ Schlussmarker.', '{{Zum}} {{Schluss}} möchte ich noch etwas hinzufügen.', array['Zum','Schluss','möchte','ich','noch','etwas','hinzufügen.']::text[], array['Zur','möchten','hinzufügt.']::text[], array['fazit']::text[], 1, '[{"de":"Zum Schluss möchte ich noch einen wichtigen Punkt hinzufügen.","en":"Finally, I would like to add one more important point."},{"de":"Zum Schluss möchte ich allen Helfern danken.","en":"Finally, I would like to thank all the helpers."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('f4d9bdaef1bf', 'Ich finde, dass Werbung oft übertreibt.', 'ich finde, dass …', 'I think that advertising often exaggerates.', 'B1', 'schreiben', 'schreiben_a2', 'meinung_aeussern', 'opinion', '‘dass’ leitet den Nebensatz ein.', 'Ich finde, {{dass}} Werbung oft übertreibt.', array['Ich','finde,','dass','Werbung','oft','übertreibt.']::text[], array['das','finden','übertreiben']::text[], array['meinung']::text[], 1, '[{"de":"Ich finde, dass Werbung oft mehr verspricht, als sie hält.","en":"I think that advertising often promises more than it delivers."},{"de":"Ich finde, dass diese Idee einfach zu teuer ist.","en":"I think that this idea is simply too expensive."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('fd39162326e0', 'Ich bin ganz deiner Meinung.', 'ich bin deiner Meinung', 'I am entirely of your opinion.', 'B1', 'schreiben', 'schreiben_a2', 'zustimmen', 'agreement', '‘deiner Meinung sein’ Genitiv.', 'Ich bin ganz {{deiner}} {{Meinung.}}', array['Ich','bin','ganz','deiner','Meinung.']::text[], array['deinem','Meinungen','ganzer']::text[], array['zustimmung']::text[], 1, '[{"de":"Ich bin ganz deiner Meinung, das Projekt lohnt sich.","en":"I am entirely of your opinion, the project is worthwhile."},{"de":"Beim Thema Recycling bin ich ganz deiner Meinung.","en":"On the topic of recycling, I am entirely of your opinion."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('02b59ab0e18f', 'In dem Artikel geht es um das Tempolimit.', 'in dem Artikel geht es um …', 'The article is about the speed limit.', 'B2', 'schreiben', 'schreiben_a2', 'einleitung_kontakt', 'intro', '‘es geht um’ + Akkusativ.', 'In dem Artikel geht es {{um}} das Tempolimit.', array['In','dem','Artikel','geht','es','um','das','Tempolimit.']::text[], array['den','gehen','den']::text[], array['einleitung']::text[], 2, '[{"de":"In dem Artikel geht es um das Tempolimit auf deutschen Autobahnen.","en":"The article is about the speed limit on German motorways."},{"de":"In dem Beitrag geht es um die Frage, ob Hausaufgaben noch sinnvoll sind.","en":"The post is about the question of whether homework still makes sense."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('05a7cb6f4711', 'Das ist ein gutes Argument, dennoch zögere ich.', 'das ist ein gutes Argument, dennoch …', 'That is a good argument, yet I hesitate.', 'B2', 'schreiben', 'schreiben_a2', 'konzession', 'concession', '‘dennoch’ als Konzessivadverb + Inversion.', 'Das ist ein gutes Argument, {{dennoch}} zögere ich.', array['Das','ist','ein','gutes','Argument,','dennoch','zögere','ich.']::text[], array['dass','gute','Dennoch']::text[], array['konzession']::text[], 2, '[{"de":"Das ist ein gutes Argument, dennoch zögere ich, dem Plan ganz zuzustimmen.","en":"That is a good argument, yet I hesitate to agree fully with the plan."},{"de":"Das ist ein gutes Argument, dennoch sehe ich auch Risiken.","en":"That is a good argument, yet I also see risks."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('0d5ff8906ce8', 'So zeigt etwa die Erfahrung das Gegenteil.', 'so zeigt etwa …', 'Experience, for instance, shows the opposite.', 'B2', 'schreiben', 'schreiben_a2', 'beispiele', 'example', '‘etwa’ im Sinne von ‘zum Beispiel’.', 'So zeigt {{etwa}} die Erfahrung das Gegenteil.', array['So','zeigt','etwa','die','Erfahrung','das','Gegenteil.']::text[], array['zeigen','etwas','Gegenteile.']::text[], array['beispiel']::text[], 2, '[{"de":"Man glaubt, mehr Geld mache glücklicher. So zeigt etwa die Erfahrung das Gegenteil.","en":"People believe more money makes you happier. Experience, for instance, shows the opposite."},{"de":"Strengere Regeln helfen nicht immer; so zeigt etwa die Erfahrung das Gegenteil.","en":"Stricter rules don''t always help; experience, for instance, shows the opposite."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('14b2b34f5537', 'Persönlich halte ich das Verbot für übertrieben.', 'ich halte … für …', 'Personally, I consider the ban exaggerated.', 'B2', 'schreiben', 'schreiben_a2', 'meinung_aeussern', 'opinion', '‘etwas für + Adjektiv halten’.', 'Persönlich halte ich das Verbot {{für}} übertrieben.', array['Persönlich','halte','ich','das','Verbot','für','übertrieben.']::text[], array['Persönliche','halten','von']::text[], array['meinung']::text[], 2, '[{"de":"Persönlich halte ich das Verbot für übertrieben, weil es kaum etwas bringt.","en":"Personally, I consider the ban exaggerated, because it achieves almost nothing."},{"de":"Ich halte diese Regel für sinnvoll, denn sie schützt alle.","en":"I consider this rule sensible, because it protects everyone."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('14f5d7486b21', 'Letztendlich überwiegen für mich die Vorteile.', 'letztendlich überwiegen … die Vorteile', 'Ultimately, for me the advantages prevail.', 'B2', 'schreiben', 'schreiben_a2', 'schluss_fazit', 'conclusion', '‘letztendlich’ als Fazitmarker.', '{{Letztendlich}} überwiegen für mich die Vorteile.', array['Letztendlich','überwiegen','für','mich','die','Vorteile.']::text[], array['Letztend','überwiegt','der']::text[], array['fazit']::text[], 2, '[{"de":"Letztendlich überwiegen für mich die Vorteile dieser Regelung.","en":"Ultimately, the advantages of this rule outweigh for me."},{"de":"Letztendlich kommt es auf eine faire Lösung an.","en":"Ultimately, what matters is a fair solution."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('1a8807acc128', 'Ein entscheidendes Argument ist die langfristige Wirkung.', 'ein entscheidendes Argument ist …', 'A decisive argument is the long-term effect.', 'B2', 'schreiben', 'schreiben_a2', 'argumentieren', 'argument', 'Adjektivendung nach ‘ein’ (Neutrum).', 'Ein {{entscheidendes}} Argument ist die langfristige Wirkung.', array['Ein','entscheidendes','Argument','ist','die','langfristige','Wirkung.']::text[], array['entscheidende','Argumente','den']::text[], array['argument']::text[], 2, '[{"de":"Ein entscheidendes Argument ist die langfristige Wirkung auf die Gesundheit.","en":"A decisive argument is the long-term effect on health."},{"de":"Ein entscheidendes Argument ist, dass sich die Investition schon nach wenigen Jahren lohnt.","en":"A decisive argument is that the investment pays off after just a few years."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('1eb760708b04', 'Denken wir nur an die vielen Pendler.', 'denken wir nur an …', 'Let''s just think of the many commuters.', 'B2', 'schreiben', 'schreiben_a2', 'beispiele', 'example', '‘denken an’ + Akkusativ.', '{{Denken}} wir nur {{an}} die vielen Pendler.', array['Denken','wir','nur','an','die','vielen','Pendler.']::text[], array['Denkt','dem','vieler']::text[], array['beispiel']::text[], 2, '[{"de":"Höhere Spritpreise treffen viele hart. Denken wir nur an die vielen Pendler.","en":"Higher fuel prices hit many people hard. Just think of the many commuters."},{"de":"Der frühe Zug ist immer voll – denken wir nur an die vielen Pendler.","en":"The early train is always full – just think of the many commuters."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('265c2fb6fa0a', 'Dafür spricht, dass die Kosten sinken.', 'dafür spricht, dass …', 'A point in its favour is that costs are falling.', 'B2', 'schreiben', 'schreiben_a2', 'argumentieren', 'argument', '‘dafür spricht, dass’.', 'Dafür spricht, {{dass}} die Kosten sinken.', array['Dafür','spricht,','dass','die','Kosten','sinken.']::text[], array['Dazu','sprechen,','das']::text[], array['argument']::text[], 2, '[{"de":"Dafür spricht, dass die Kosten sinken und gleichzeitig die Qualität steigt.","en":"What speaks for it is that the costs fall while the quality rises at the same time."},{"de":"Dafür spricht, dass viele Familien davon profitieren würden.","en":"What speaks for it is that many families would benefit from it."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('2f84faa064a8', 'Dem kann ich nur zustimmen.', 'dem kann ich nur zustimmen', 'I can only agree with that.', 'B2', 'schreiben', 'schreiben_a2', 'zustimmen', 'agreement', 'Vorangestelltes Dativobjekt ‘dem’.', '{{Dem}} kann ich nur zustimmen.', array['Dem','kann','ich','nur','zustimmen.']::text[], array['Den','können','ab.']::text[], array['zustimmung']::text[], 2, '[{"de":"Dem kann ich nur zustimmen, denn genau das habe ich auch beobachtet.","en":"I can only agree with that, because that is exactly what I observed too."},{"de":"Du forderst mehr Pausen? Dem kann ich nur zustimmen.","en":"You are demanding more breaks? I can only agree with that."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('37f5b9c14700', 'Nehmen wir das Beispiel der Schule.', 'nehmen wir das Beispiel …', 'Let us take the example of school.', 'B2', 'schreiben', 'schreiben_a2', 'beispiele', 'example', 'Aufforderung mit ‘nehmen wir’.', '{{Nehmen}} wir das Beispiel der Schule.', array['Nehmen','wir','das','Beispiel','der','Schule.']::text[], array['Nimmt','dass','den']::text[], array['beispiel']::text[], 2, '[{"de":"Nehmen wir das Beispiel der Schule: Ohne genug Lehrer leidet die Qualität.","en":"Let us take the example of school: without enough teachers, the quality suffers."},{"de":"Nehmen wir das Beispiel der Schule, um das Problem klarer zu sehen.","en":"Let us take the example of school to see the problem more clearly."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('3f3c35525c24', 'Das ist ein überzeugendes Argument.', 'das ist ein überzeugendes Argument', 'That is a convincing argument.', 'B2', 'schreiben', 'schreiben_a2', 'zustimmen', 'agreement', 'Adjektivendung ‘-es’ nach ‘ein’ (Neutrum).', 'Das ist ein {{überzeugendes}} Argument.', array['Das','ist','ein','überzeugendes','Argument.']::text[], array['dass','überzeugend','Argumente.']::text[], array['zustimmung']::text[], 2, '[{"de":"Das ist ein überzeugendes Argument, das sollten wir berücksichtigen.","en":"That is a convincing argument, we should take it into account."},{"de":"Du nennst die Kosten – das ist ein überzeugendes Argument.","en":"You mention the costs — that is a convincing argument."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('5232e9fff0b8', 'Das halte ich für ein Vorurteil.', 'das halte ich für …', 'I consider that a prejudice.', 'B2', 'schreiben', 'schreiben_a2', 'widersprechen', 'disagreement', '‘etwas für etwas halten’.', 'Das halte ich {{für}} ein Vorurteil.', array['Das','halte','ich','für','ein','Vorurteil.']::text[], array['dass','hältst','von']::text[], array['widerspruch']::text[], 2, '[{"de":"Das halte ich für ein Vorurteil, das man so nicht stehen lassen sollte.","en":"I consider that a prejudice that should not be left unchallenged."},{"de":"Diese Behauptung halte ich für übertrieben.","en":"I consider this claim exaggerated."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('6121e874e172', 'Aus diesen Gründen bin ich gegen das Verbot.', 'aus diesen Gründen bin ich …', 'For these reasons, I am against the ban.', 'B2', 'schreiben', 'schreiben_a2', 'schluss_fazit', 'conclusion', 'Begründetes Fazit; ‘aus diesen Gründen’ Dativ Plural.', 'Aus {{diesen}} {{Gründen}} bin ich gegen das Verbot.', array['Aus','diesen','Gründen','bin','ich','gegen','das','Verbot.']::text[], array['diesem','Gründe','den']::text[], array['fazit']::text[], 2, '[{"de":"Aus diesen Gründen bin ich gegen das geplante Verbot.","en":"For these reasons, I am against the planned ban."},{"de":"Aus diesen Gründen unterstütze ich den Vorschlag.","en":"For these reasons, I support the proposal."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('6fb0b0960167', 'Hinzu kommt noch der finanzielle Aspekt.', 'hinzu kommt noch …', 'On top of that, there is the financial aspect.', 'B2', 'schreiben', 'schreiben_a2', 'argumentieren', 'argument', '‘hinzu kommt’ ergänzend.', '{{Hinzu}} {{kommt}} noch der finanzielle Aspekt.', array['Hinzu','kommt','noch','der','finanzielle','Aspekt.']::text[], array['Hin','kommen','den']::text[], array['argument']::text[], 2, '[{"de":"Das Projekt ist sinnvoll. Hinzu kommt noch der finanzielle Aspekt.","en":"The project makes sense. On top of that, there is the financial aspect."},{"de":"Die Reise ist anstrengend, und hinzu kommt noch der finanzielle Aspekt.","en":"The trip is exhausting, and on top of that there is the financial aspect."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('7b0f5fef335c', 'Damit bin ich nicht einverstanden.', 'damit bin ich nicht einverstanden', 'I do not agree with that.', 'B2', 'schreiben', 'schreiben_a2', 'widersprechen', 'disagreement', '‘mit etwas einverstanden sein’.', '{{Damit}} bin ich nicht einverstanden.', array['Damit','bin','ich','nicht','einverstanden.']::text[], array['Damals','bist','einverstandene']::text[], array['widerspruch']::text[], 2, '[{"de":"Damit bin ich nicht einverstanden, denn so ist es nicht fair.","en":"I do not agree with that, because it is not fair that way."},{"de":"Mit dieser Regel bin ich nicht einverstanden.","en":"I do not agree with this rule."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('7f9570ae2a50', 'Das mag stimmen, trotzdem bleibe ich skeptisch.', 'das mag stimmen, trotzdem …', 'That may be true, nevertheless I remain skeptical.', 'B2', 'schreiben', 'schreiben_a2', 'konzession', 'concession', '‘trotzdem’ als Konzessivadverb + Inversion.', 'Das mag stimmen, {{trotzdem}} bleibe ich skeptisch.', array['Das','mag','stimmen,','trotzdem','bleibe','ich','skeptisch.']::text[], array['magst','stimmt,','Trotzdem']::text[], array['konzession']::text[], 2, '[{"de":"Das mag stimmen, trotzdem bleibe ich skeptisch, ob es wirklich funktioniert.","en":"That may be true, nevertheless I remain skeptical whether it really works."},{"de":"Das mag stimmen, trotzdem würde ich es anders machen.","en":"That may be true, nevertheless I would do it differently."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('84b24a149697', 'Es stimmt, dass es Risiken gibt.', 'es stimmt, dass …', 'It is true that there are risks.', 'B2', 'schreiben', 'schreiben_a2', 'konzession', 'concession', 'Zugeständnis ‘es stimmt, dass’.', 'Es stimmt, {{dass}} es Risiken gibt.', array['Es','stimmt,','dass','es','Risiken','gibt.']::text[], array['stimmen,','das','geben.']::text[], array['konzession']::text[], 2, '[{"de":"Es stimmt, dass es Risiken gibt, aber man kann sie gut kontrollieren.","en":"It is true that there are risks, but they can be controlled well."},{"de":"Es stimmt, dass die Idee anfangs teuer ist.","en":"It is true that the idea is expensive at first."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('90994bfd3612', 'Diesem Argument kann ich nicht folgen.', 'diesem Argument kann ich nicht folgen', 'I cannot follow this argument.', 'B2', 'schreiben', 'schreiben_a2', 'widersprechen', 'disagreement', '‘einem Argument folgen’ + Dativ.', '{{Diesem}} Argument kann ich nicht folgen.', array['Diesem','Argument','kann','ich','nicht','folgen.']::text[], array['Dieses','Argumente','folge.']::text[], array['widerspruch']::text[], 2, '[{"de":"Diesem Argument kann ich nicht folgen, weil es die Fakten ignoriert.","en":"I cannot follow this argument, because it ignores the facts."},{"de":"Deiner Begründung kann ich leider nicht folgen.","en":"Unfortunately, I cannot follow your reasoning."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('9a962929e18d', 'Ich habe deinen Beitrag mit Interesse gelesen.', 'ich habe deinen Beitrag … gelesen', 'I read your post with interest.', 'B2', 'schreiben', 'schreiben_a2', 'einleitung_kontakt', 'intro', 'Bezug auf den Vorbeitrag.', 'Ich habe {{deinen}} Beitrag mit Interesse gelesen.', array['Ich','habe','deinen','Beitrag','mit','Interesse','gelesen.']::text[], array['dein','Beiträge','lese']::text[], array['einleitung']::text[], 2, '[{"de":"Ich habe deinen Beitrag mit Interesse gelesen und stimme dir in vielen Punkten zu.","en":"I read your post with interest and agree with you on many points."},{"de":"Ich habe deinen Beitrag über das Reisen mit Interesse gelesen.","en":"I read your post about traveling with interest."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('a55685cb0314', 'So ist es zum Beispiel in Schweden üblich.', 'so ist es zum Beispiel in … üblich', 'It is customary in Sweden, for example.', 'B2', 'schreiben', 'schreiben_a2', 'beispiele', 'example', '‘zum Beispiel’ eingeschoben.', 'So ist es {{zum}} {{Beispiel}} in Schweden üblich.', array['So','ist','es','zum','Beispiel','in','Schweden','üblich.']::text[], array['Zur','Beispiele','übliche']::text[], array['beispiel']::text[], 2, '[{"de":"In manchen Ländern arbeitet man weniger Stunden. So ist es zum Beispiel in Schweden üblich, früher Feierabend zu machen.","en":"In some countries people work fewer hours. It is customary in Sweden, for example, to finish work earlier."},{"de":"Manche Schulen verzichten ganz auf Noten. So ist es zum Beispiel in Finnland üblich.","en":"Some schools do without grades entirely. It is customary in Finland, for example."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('a858c475e3bd', 'Aus meiner Sicht überwiegen hier die Nachteile.', 'aus meiner Sicht …', 'From my point of view, the disadvantages prevail here.', 'B2', 'schreiben', 'schreiben_a2', 'meinung_aeussern', 'opinion', '‘aus meiner Sicht’ Wendung mit Dativ.', 'Aus {{meiner}} {{Sicht}} überwiegen hier die Nachteile.', array['Aus','meiner','Sicht','überwiegen','hier','die','Nachteile.']::text[], array['meinem','Sichten','überwiegt']::text[], array['meinung']::text[], 2, '[{"de":"Aus meiner Sicht überwiegen bei diesem Plan die Vorteile.","en":"From my point of view, the advantages of this plan outweigh."},{"de":"Aus meiner Sicht braucht die Schule mehr Lehrer.","en":"From my point of view, the school needs more teachers."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('b19195615b23', 'Hinzu kommt, dass viele Menschen davon profitieren.', 'hinzu kommt, dass …', 'Added to that, many people benefit from it.', 'B2', 'schreiben', 'schreiben_a2', 'argumentieren', 'argument', '‘hinzu kommt, dass’ Steigerung.', 'Hinzu kommt, {{dass}} viele Menschen davon profitieren.', array['Hinzu','kommt,','dass','viele','Menschen','davon','profitieren.']::text[], array['Hin','kommen,','das']::text[], array['argument']::text[], 2, '[{"de":"Hinzu kommt, dass viele Menschen davon profitieren, nicht nur die Firmen.","en":"Added to that, many people benefit from it, not just the companies."},{"de":"Die Maßnahme ist günstig. Hinzu kommt, dass viele Menschen davon profitieren.","en":"The measure is cheap. Added to that, many people benefit from it."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('b9314aedc987', 'Das liegt vor allem daran, dass die Mieten steigen.', 'das liegt daran, dass …', 'That is mainly because rents are rising.', 'B2', 'schreiben', 'schreiben_a2', 'argumentieren', 'argument', '‘daran liegen, dass’ kausal.', 'Das liegt vor allem {{daran,}} {{dass}} die Mieten steigen.', array['Das','liegt','vor','allem','daran,','dass','die','Mieten','steigen.']::text[], array['liegen','darum,','das']::text[], array['argument']::text[], 2, '[{"de":"Immer mehr Menschen ziehen weg. Das liegt vor allem daran, dass die Mieten steigen.","en":"More and more people are moving away. That is mainly because rents are rising."},{"de":"Das Geschäft läuft schlecht, und das liegt vor allem daran, dass die Kunden online kaufen.","en":"Business is bad, and that is mainly because customers buy online."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('bbf116a5b9f5', 'Ich bin der Meinung, dass Kinder weniger fernsehen sollten.', 'ich bin der Meinung, dass …', 'I am of the opinion that children should watch less TV.', 'B2', 'schreiben', 'schreiben_a2', 'meinung_aeussern', 'opinion', '‘der Meinung sein, dass’.', 'Ich bin {{der}} Meinung, {{dass}} Kinder weniger fernsehen sollten.', array['Ich','bin','der','Meinung,','dass','Kinder','weniger','fernsehen','sollten.']::text[], array['dem','Meinungen','das']::text[], array['meinung']::text[], 2, '[{"de":"Ich bin der Meinung, dass Kinder weniger Zeit am Bildschirm verbringen sollten.","en":"I am of the opinion that children should spend less time at the screen."},{"de":"Ich bin der Meinung, dass öffentliche Verkehrsmittel günstiger werden müssen.","en":"I am of the opinion that public transport must become cheaper."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('c4c4143cf34c', 'Einerseits ist das praktisch, andererseits riskant.', 'einerseits …, andererseits …', 'On the one hand it is practical, on the other risky.', 'B2', 'schreiben', 'schreiben_a2', 'konzession', 'concession', '‘einerseits … andererseits …’.', '{{Einerseits}} ist das praktisch, {{andererseits}} riskant.', array['Einerseits','ist','das','praktisch,','andererseits','riskant.']::text[], array['Einseits','sind','Anderseits']::text[], array['konzession']::text[], 2, '[{"de":"Einerseits ist das Handy praktisch, andererseits lenkt es oft ab.","en":"On the one hand the phone is practical, on the other it often distracts."},{"de":"Einerseits spart man Zeit, andererseits verliert man den persönlichen Kontakt.","en":"On the one hand you save time, on the other you lose personal contact."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('ce50e7cacf90', 'Wie du schon sagtest, ist das ein heikles Thema.', 'wie du schon sagtest, …', 'As you already said, this is a delicate topic.', 'B2', 'schreiben', 'schreiben_a2', 'einleitung_kontakt', 'intro', 'Rückbezug auf den Vorredner.', '{{Wie}} du schon sagtest, ist das ein heikles Thema.', array['Wie','du','schon','sagtest,','ist','das','ein','heikles','Thema.']::text[], array['dass','sagte,','heikle']::text[], array['einleitung']::text[], 2, '[{"de":"Wie du schon sagtest, ist das ein heikles Thema, über das man nicht leicht spricht.","en":"As you already said, this is a delicate topic that is not easy to talk about."},{"de":"Wie du schon sagtest, hat jede Lösung auch ihre Nachteile.","en":"As you already said, every solution also has its disadvantages."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('d9da78d1df66', 'Ich bezweifle, dass das die Lösung ist.', 'ich bezweifle, dass …', 'I doubt that that is the solution.', 'B2', 'schreiben', 'schreiben_a2', 'widersprechen', 'disagreement', '‘bezweifeln, dass’.', 'Ich bezweifle, {{dass}} das die Lösung ist.', array['Ich','bezweifle,','dass','das','die','Lösung','ist.']::text[], array['bezweifelt','dass','den']::text[], array['widerspruch']::text[], 2, '[{"de":"Ich bezweifle, dass das die Lösung ist, solange die Ursache unklar bleibt.","en":"I doubt that this is the solution as long as the cause remains unclear."},{"de":"Ehrlich gesagt bezweifle ich, dass ein Verbot wirklich hilft.","en":"Honestly, I doubt that a ban really helps."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('e1734c76fbb6', 'Ich bin davon überzeugt, dass Bildung entscheidend ist.', 'ich bin davon überzeugt, dass …', 'I am convinced that education is decisive.', 'B2', 'schreiben', 'schreiben_a2', 'meinung_aeussern', 'opinion', '‘davon überzeugt sein, dass’.', 'Ich bin {{davon}} überzeugt, dass Bildung entscheidend ist.', array['Ich','bin','davon','überzeugt,','dass','Bildung','entscheidend','ist.']::text[], array['dafür','überzeugen','das']::text[], array['meinung']::text[], 2, '[{"de":"Ich bin davon überzeugt, dass Bildung der Schlüssel zu mehr Chancen ist.","en":"I am convinced that education is the key to more opportunities."},{"de":"Ich bin davon überzeugt, dass sich der Aufwand am Ende lohnt.","en":"I am convinced that the effort will pay off in the end."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('e3112bce4fee', 'Genau das wollte ich auch sagen.', 'genau das wollte ich sagen', 'That is exactly what I wanted to say too.', 'B2', 'schreiben', 'schreiben_a2', 'zustimmen', 'agreement', 'Zustimmende Bekräftigung.', '{{Genau}} {{das}} wollte ich auch sagen.', array['Genau','das','wollte','ich','auch','sagen.']::text[], array['dass','wollten','gesagt.']::text[], array['zustimmung']::text[], 2, '[{"de":"Genau das wollte ich auch sagen: Wir brauchen mehr Zeit.","en":"That is exactly what I wanted to say too: we need more time."},{"de":"Genau das wollte ich auch sagen, du bist mir nur zuvorgekommen.","en":"That is exactly what I wanted to say too, you just beat me to it."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('e8c8219dd644', 'Abschließend möchte ich betonen, dass Dialog wichtig ist.', 'abschließend möchte ich betonen, dass …', 'Finally, I would like to emphasize that dialogue is important.', 'B2', 'schreiben', 'schreiben_a2', 'schluss_fazit', 'conclusion', 'Schlussappell mit ‘abschließend’.', '{{Abschließend}} möchte ich betonen, {{dass}} Dialog wichtig ist.', array['Abschließend','möchte','ich','betonen,','dass','Dialog','wichtig','ist.']::text[], array['Abschließen','möchten','das']::text[], array['fazit']::text[], 2, '[{"de":"Abschließend möchte ich betonen, dass ein offener Dialog wichtig ist.","en":"Finally, I would like to emphasize that an open dialogue is important."},{"de":"Abschließend möchte ich betonen, dass wir mehr Zeit brauchen.","en":"Finally, I would like to emphasize that we need more time."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('0c25e6d342e0', 'Daraus ergibt sich, dass Handeln geboten ist.', 'daraus ergibt sich, dass …', 'From this it follows that action is required.', 'C1', 'schreiben', 'schreiben_a2', 'schluss_fazit', 'conclusion', '‘daraus ergibt sich, dass’.', 'Daraus ergibt sich, {{dass}} Handeln geboten ist.', array['Daraus','ergibt','sich,','dass','Handeln','geboten','ist.']::text[], array['Darum','ergeben','das']::text[], array['fazit','gehoben']::text[], 3, '[{"de":"Daraus ergibt sich, dass wir jetzt handeln müssen.","en":"From this it follows that we must act now."},{"de":"Daraus ergibt sich, dass eine reine Verbotspolitik nicht reicht.","en":"From this it follows that a policy of bans alone is not enough."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('0eba336abcd6', 'Meines Erachtens überwiegen die Vorteile deutlich.', 'meines Erachtens …', 'In my view, the advantages clearly outweigh the disadvantages.', 'C1', 'schreiben', 'schreiben_a2', 'meinung_aeussern', 'opinion', '‘meines Erachtens’ ist fester Genitiv.', '{{Meines}} {{Erachtens}} überwiegen die Vorteile deutlich.', array['Meines','Erachtens','überwiegen','die','Vorteile','deutlich.']::text[], array['Mein','Erachten','überwiegt']::text[], array['nominalstil','meinung']::text[], 3, '[{"de":"Meines Erachtens überwiegen die Vorteile des Fahrrads deutlich.","en":"In my view, the advantages of the bicycle clearly outweigh the disadvantages."},{"de":"Meines Erachtens sollte man mehr in Bildung investieren.","en":"In my view, more should be invested in education."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('3940a4f88929', 'Dem ist nichts hinzuzufügen.', 'dem ist nichts hinzuzufügen', 'There is nothing to add to that.', 'C1', 'schreiben', 'schreiben_a2', 'zustimmen', 'agreement', 'Feste idiomatische Wendung, ‘zu’-Infinitiv.', '{{Dem}} ist nichts {{hinzuzufügen.}}', array['Dem','ist','nichts','hinzuzufügen.']::text[], array['Den','sind','hinzufügen.']::text[], array['zustimmung','idiomatisch']::text[], 3, '[{"de":"Du hast alles gesagt – dem ist nichts hinzuzufügen.","en":"You have said everything — there is nothing to add to that."},{"de":"Ein klares Fazit; dem ist nichts hinzuzufügen.","en":"A clear conclusion; there is nothing to add to that."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('3fc783e39568', 'Ich teile diese Einschätzung uneingeschränkt.', 'ich teile diese Einschätzung', 'I share this assessment without reservation.', 'C1', 'schreiben', 'schreiben_a2', 'zustimmen', 'agreement', '‘eine Einschätzung teilen’.', 'Ich teile {{diese}} Einschätzung uneingeschränkt.', array['Ich','teile','diese','Einschätzung','uneingeschränkt.']::text[], array['teilt','dieser','Einschätzungen']::text[], array['zustimmung','gehoben']::text[], 3, '[{"de":"Ich teile diese Einschätzung uneingeschränkt und sehe keinen Grund für Zweifel.","en":"I share this assessment without reservation and see no reason for doubt."},{"de":"Was die Risiken angeht, teile ich diese Einschätzung uneingeschränkt.","en":"As far as the risks are concerned, I share this assessment without reservation."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('464a44455f80', 'Die Frage, ob das Verbot greift, wird heftig debattiert.', 'die Frage, ob …, wird debattiert', 'Whether the ban works is being hotly debated.', 'C1', 'schreiben', 'schreiben_a2', 'einleitung_kontakt', 'intro', 'Eingebetteter ob-Satz als Subjekt.', 'Die {{Frage,}} {{ob}} das Verbot greift, wird heftig debattiert.', array['Die','Frage,','ob','das','Verbot','greift,','wird','heftig','debattiert.']::text[], array['dass','den','debattieren.']::text[], array['einleitung','gehoben']::text[], 3, '[{"de":"Die Frage, ob das Verbot wirklich greift, wird heftig debattiert.","en":"Whether the ban really works is being hotly debated."},{"de":"Die Frage, ob Studiengebühren gerecht sind, wird seit Jahren debattiert.","en":"Whether tuition fees are fair has been debated for years."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('59e9d61a17d3', 'Dem muss ich entschieden widersprechen.', 'dem muss ich widersprechen', 'I have to firmly contradict that.', 'C1', 'schreiben', 'schreiben_a2', 'widersprechen', 'disagreement', '‘widersprechen’ + Dativ, gehoben.', '{{Dem}} muss ich entschieden widersprechen.', array['Dem','muss','ich','entschieden','widersprechen.']::text[], array['Den','müssen','entschiedene']::text[], array['widerspruch','gehoben']::text[], 3, '[{"de":"Dem muss ich entschieden widersprechen, denn die Studie sagt etwas anderes.","en":"I have to firmly contradict that, because the study says something else."},{"de":"Dem muss ich widersprechen: Die Lage ist gar nicht so schlecht.","en":"I have to contradict that: the situation is not so bad at all."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('69c002b33266', 'Ich vertrete den Standpunkt, dass Vielfalt uns bereichert.', 'ich vertrete den Standpunkt, dass …', 'I take the position that diversity enriches us.', 'C1', 'schreiben', 'schreiben_a2', 'meinung_aeussern', 'opinion', 'Gehobene Wendung ‘einen Standpunkt vertreten’.', 'Ich vertrete den Standpunkt, {{dass}} Vielfalt uns bereichert.', array['Ich','vertrete','den','Standpunkt,','dass','Vielfalt','uns','bereichert.']::text[], array['dem','vertreten','das']::text[], array['meinung','gehoben']::text[], 3, '[{"de":"Ich vertrete den Standpunkt, dass Vielfalt unsere Gesellschaft bereichert.","en":"I take the position that diversity enriches our society."},{"de":"Ich vertrete den Standpunkt, dass jeder eine zweite Chance verdient.","en":"I take the position that everyone deserves a second chance."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('6ae72382d7f9', 'Zugegeben, der Aufwand ist beträchtlich.', 'zugegeben, …', 'Admittedly, the effort is considerable.', 'C1', 'schreiben', 'schreiben_a2', 'konzession', 'concession', '‘zugegeben’ als Konzessionsmarker.', '{{Zugegeben,}} der Aufwand ist beträchtlich.', array['Zugegeben,','der','Aufwand','ist','beträchtlich.']::text[], array['Zugeben,','den','beträchtliche.']::text[], array['konzession','gehoben']::text[], 3, '[{"de":"Zugegeben, der Aufwand ist beträchtlich, doch das Ergebnis lohnt sich.","en":"Admittedly, the effort is considerable, but the result is worth it."},{"de":"Zugegeben, am Anfang ist es schwer, aber mit der Zeit wird es leichter.","en":"Admittedly, it is hard at the start, but it gets easier over time."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('73cedc5ac906', 'Diese Auffassung halte ich für verfehlt.', 'diese Auffassung halte ich für …', 'I consider this view mistaken.', 'C1', 'schreiben', 'schreiben_a2', 'widersprechen', 'disagreement', '‘für verfehlt halten’.', 'Diese Auffassung halte ich {{für}} verfehlt.', array['Diese','Auffassung','halte','ich','für','verfehlt.']::text[], array['Dieser','hältst','verfehlte']::text[], array['widerspruch','gehoben']::text[], 3, '[{"de":"Diese Auffassung halte ich für verfehlt, weil sie die Realität ignoriert.","en":"I consider this view mistaken, because it ignores reality."},{"de":"Den Plan halte ich für verfehlt.","en":"I consider the plan mistaken."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('814493371345', 'Dieser Schluss erscheint mir voreilig.', 'dieser Schluss erscheint mir …', 'This conclusion seems premature to me.', 'C1', 'schreiben', 'schreiben_a2', 'widersprechen', 'disagreement', 'Höflicher Widerspruch mit ‘erscheinen’.', '{{Dieser}} Schluss erscheint mir voreilig.', array['Dieser','Schluss','erscheint','mir','voreilig.']::text[], array['Diese','erscheinen','voreilige']::text[], array['widerspruch','gehoben']::text[], 3, '[{"de":"Dieser Schluss erscheint mir voreilig, da wichtige Daten noch fehlen.","en":"This conclusion seems premature to me, since important data is still missing."},{"de":"Die Entscheidung erscheint mir etwas voreilig.","en":"The decision seems a bit premature to me."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('84a6199547c7', 'Im Großen und Ganzen halte ich es für sinnvoll.', 'im Großen und Ganzen …', 'By and large, I consider it sensible.', 'C1', 'schreiben', 'schreiben_a2', 'schluss_fazit', 'conclusion', 'Idiom ‘im Großen und Ganzen’ (großgeschrieben).', 'Im {{Großen}} und {{Ganzen}} halte ich es für sinnvoll.', array['Im','Großen','und','Ganzen','halte','ich','es','für','sinnvoll.']::text[], array['großen','Ganze','von']::text[], array['fazit','idiomatisch']::text[], 3, '[{"de":"Im Großen und Ganzen halte ich die Reform für sinnvoll.","en":"By and large, I consider the reform sensible."},{"de":"Im Großen und Ganzen sind wir mit dem Ergebnis zufrieden.","en":"By and large, we are satisfied with the result."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('900675a2ce6f', 'Belegen lässt sich dies durch zahlreiche Studien.', 'belegen lässt sich dies durch …', 'This can be substantiated by numerous studies.', 'C1', 'schreiben', 'schreiben_a2', 'beispiele', 'example', 'Vorangestelltes ‘belegen lässt sich’.', '{{Belegen}} lässt sich dies durch zahlreiche Studien.', array['Belegen','lässt','sich','dies','durch','zahlreiche','Studien.']::text[], array['Belegt','lasst','diese']::text[], array['beispiel','gehoben']::text[], 3, '[{"de":"Rauchen schadet der Gesundheit. Belegen lässt sich dies durch zahlreiche Studien.","en":"Smoking harms your health. This can be substantiated by numerous studies."},{"de":"Belegen lässt sich dies durch die Erfahrungen vieler anderer Länder.","en":"This can be substantiated by the experiences of many other countries."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('ab604cb6ef08', 'Ich vertrete die Ansicht, dass Vorbeugung entscheidend ist.', 'ich vertrete die Ansicht, dass …', 'I hold the view that prevention is decisive.', 'C1', 'schreiben', 'schreiben_a2', 'meinung_aeussern', 'opinion', '‘eine Ansicht vertreten’.', 'Ich vertrete die Ansicht, {{dass}} Vorbeugung entscheidend ist.', array['Ich','vertrete','die','Ansicht,','dass','Vorbeugung','entscheidend','ist.']::text[], array['der','vertritt','das']::text[], array['meinung','gehoben']::text[], 3, '[{"de":"Ich vertrete die Ansicht, dass Vorbeugung billiger ist als Reparatur.","en":"I hold the view that prevention is cheaper than repair."},{"de":"Ich vertrete die Ansicht, dass Bildung allen offenstehen muss.","en":"I hold the view that education must be open to everyone."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('b28fd9d78965', 'Nicht zuletzt zeigt die Statistik einen klaren Trend.', 'nicht zuletzt …', 'Not least, the statistics show a clear trend.', 'C1', 'schreiben', 'schreiben_a2', 'argumentieren', 'argument', '‘nicht zuletzt’ als letztes, gewichtiges Argument.', '{{Nicht}} {{zuletzt}} zeigt die Statistik einen klaren Trend.', array['Nicht','zuletzt','zeigt','die','Statistik','einen','klaren','Trend.']::text[], array['zuletze','zeigen','klares']::text[], array['argument','gehoben']::text[], 3, '[{"de":"Nicht zuletzt zeigt die Statistik einen klaren Trend zu mehr Homeoffice.","en":"Not least, the statistics show a clear trend towards more working from home."},{"de":"Die Vorteile sind bekannt, und nicht zuletzt zeigt die Statistik einen klaren Trend.","en":"The advantages are well known, and not least, the statistics show a clear trend."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('bb02aa23a6bd', 'Ein anschauliches Beispiel hierfür liefert die Geschichte.', 'ein anschauliches Beispiel hierfür liefert …', 'History provides a vivid example of this.', 'C1', 'schreiben', 'schreiben_a2', 'beispiele', 'example', 'Gehoben ‘ein Beispiel liefern’.', 'Ein {{anschauliches}} Beispiel hierfür liefert die Geschichte.', array['Ein','anschauliches','Beispiel','hierfür','liefert','die','Geschichte.']::text[], array['anschauliche','Beispiele','liefern']::text[], array['beispiel','gehoben']::text[], 3, '[{"de":"Technischer Fortschritt bringt nicht nur Vorteile. Ein anschauliches Beispiel hierfür liefert die Geschichte des Autos.","en":"Technological progress does not only bring advantages. History provides a vivid example of this with the car."},{"de":"Ein anschauliches Beispiel hierfür liefert die Entwicklung des Internets.","en":"The development of the internet provides a vivid example of this."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('bbe4ce4dc01a', 'Vor diesem Hintergrund erscheint die Forderung berechtigt.', 'vor diesem Hintergrund …', 'Against this backdrop, the demand appears justified.', 'C1', 'schreiben', 'schreiben_a2', 'einleitung_kontakt', 'intro', '‘vor diesem Hintergrund’ als Bezug.', 'Vor {{diesem}} {{Hintergrund}} erscheint die Forderung berechtigt.', array['Vor','diesem','Hintergrund','erscheint','die','Forderung','berechtigt.']::text[], array['diesen','Hintergründe','berechtigte.']::text[], array['einleitung','gehoben']::text[], 3, '[{"de":"Die Preise steigen, und viele Familien haben weniger Geld. Vor diesem Hintergrund erscheint die Forderung berechtigt.","en":"Prices are rising and many families have less money. Against this backdrop, the demand appears justified."},{"de":"Vor diesem Hintergrund erscheint mir eine schnelle Lösung dringend nötig.","en":"Against this backdrop, a quick solution seems urgently necessary to me."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('bf58f3d29fc4', 'Aus meiner Perspektive ist diese Entwicklung bedenklich.', 'aus meiner Perspektive …', 'From my perspective, this development is worrying.', 'C1', 'schreiben', 'schreiben_a2', 'meinung_aeussern', 'opinion', 'Variante zu ‘aus meiner Sicht’.', 'Aus meiner {{Perspektive}} ist diese Entwicklung bedenklich.', array['Aus','meiner','Perspektive','ist','diese','Entwicklung','bedenklich.']::text[], array['meinem','Perspektiven','bedenkliche']::text[], array['meinung']::text[], 3, '[{"de":"Aus meiner Perspektive ist diese Entwicklung eher gefährlich.","en":"From my perspective, this development is rather dangerous."},{"de":"Aus meiner Perspektive fehlt dem Vorschlag ein klarer Plan.","en":"From my perspective, the proposal lacks a clear plan."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('ce962cec282b', 'Unterm Strich überwiegen die langfristigen Vorteile.', 'unterm Strich …', 'At the end of the day, the long-term advantages prevail.', 'C1', 'schreiben', 'schreiben_a2', 'schluss_fazit', 'conclusion', 'Idiom ‘unterm Strich’.', '{{Unterm}} {{Strich}} überwiegen die langfristigen Vorteile.', array['Unterm','Strich','überwiegen','die','langfristigen','Vorteile.']::text[], array['Unter','überwiegt','langfristige']::text[], array['fazit','idiomatisch']::text[], 3, '[{"de":"Unterm Strich hat sich die Investition gelohnt.","en":"At the end of the day, the investment was worth it."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('d31f1d76fcb6', 'Daraus folgt, dass wir umdenken müssen.', 'daraus folgt, dass …', 'It follows that we must rethink.', 'C1', 'schreiben', 'schreiben_a2', 'argumentieren', 'argument', 'Logische Schlussfolgerung.', 'Daraus folgt, {{dass}} wir umdenken müssen.', array['Daraus','folgt,','dass','wir','umdenken','müssen.']::text[], array['Darum','folgen,','das']::text[], array['argument','gehoben']::text[], 3, '[{"de":"Die Ressourcen werden knapp. Daraus folgt, dass wir umdenken müssen.","en":"Resources are becoming scarce. It follows that we must rethink."},{"de":"Die alten Methoden funktionieren nicht mehr; daraus folgt, dass wir umdenken müssen.","en":"The old methods no longer work; it follows that we must rethink."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('de74b838ac6c', 'Angesichts steigender Preise ist die Debatte verständlich.', 'angesichts … ist die Debatte verständlich', 'Given rising prices, the debate is understandable.', 'C1', 'schreiben', 'schreiben_a2', 'einleitung_kontakt', 'intro', '‘angesichts’ + Genitiv.', '{{Angesichts}} steigender Preise ist die Debatte verständlich.', array['Angesichts','steigender','Preise','ist','die','Debatte','verständlich.']::text[], array['Angesicht','steigende','verständliche.']::text[], array['einleitung','gehoben']::text[], 3, '[{"de":"Angesichts steigender Preise ist die Debatte über Löhne verständlich.","en":"Given rising prices, the debate about wages is understandable."},{"de":"Angesichts der vielen Staus ist der Ruf nach besseren Bussen und Bahnen verständlich.","en":"Given the many traffic jams, the call for better buses and trains is understandable."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('e48d1a2c5a83', 'Da kann ich dir nur beipflichten.', 'da kann ich dir nur beipflichten', 'I can only agree with you on that.', 'C1', 'schreiben', 'schreiben_a2', 'zustimmen', 'agreement', '‘beipflichten’ + Dativ.', 'Da kann ich {{dir}} nur beipflichten.', array['Da','kann','ich','dir','nur','beipflichten.']::text[], array['dich','kannst','beipflichte.']::text[], array['zustimmung','gehoben']::text[], 3, '[{"de":"Da kann ich dir nur beipflichten, die Lage hat sich klar verbessert.","en":"I can only agree with you on that, the situation has clearly improved."},{"de":"Was den Zeitplan angeht, da kann ich dir nur beipflichten.","en":"As far as the schedule is concerned, I can only agree with you on that."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('ee1a57ddab59', 'Ein gewichtiges Argument hierfür ist die Nachhaltigkeit.', 'ein gewichtiges Argument hierfür ist …', 'A weighty argument for this is sustainability.', 'C1', 'schreiben', 'schreiben_a2', 'argumentieren', 'argument', 'Gehobenes Attribut ‘gewichtig’.', 'Ein {{gewichtiges}} Argument {{hierfür}} ist die Nachhaltigkeit.', array['Ein','gewichtiges','Argument','hierfür','ist','die','Nachhaltigkeit.']::text[], array['gewichtige','Argumente','dazu']::text[], array['argument','gehoben']::text[], 3, '[{"de":"Ein gewichtiges Argument hierfür ist die Nachhaltigkeit der neuen Technik.","en":"A weighty argument for this is the sustainability of the new technology."},{"de":"Ein gewichtiges Argument hierfür ist, dass künftige Generationen davon profitieren.","en":"A weighty argument for this is that future generations will benefit from it."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('fec149baae72', 'Dies lässt sich am Fall Japans gut veranschaulichen.', 'dies lässt sich an … veranschaulichen', 'This can be well illustrated by the case of Japan.', 'C1', 'schreiben', 'schreiben_a2', 'beispiele', 'example', '‘sich veranschaulichen lassen’.', 'Dies {{lässt}} {{sich}} am Fall Japans gut veranschaulichen.', array['Dies','lässt','sich','am','Fall','Japans','gut','veranschaulichen.']::text[], array['lasst','sie','Japan']::text[], array['beispiel','gehoben']::text[], 3, '[{"de":"Wirtschaftliche Krisen können lange dauern. Dies lässt sich am Fall Japans gut veranschaulichen.","en":"Economic crises can last a long time. This can be well illustrated by the case of Japan."},{"de":"Dies lässt sich an einem einfachen Alltagsbeispiel gut veranschaulichen.","en":"This can be well illustrated by a simple everyday example."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('ff187b970a1c', 'Sicherlich hat diese Sorge ihre Berechtigung.', 'sicherlich hat … ihre Berechtigung', 'This concern certainly has its justification.', 'C1', 'schreiben', 'schreiben_a2', 'konzession', 'concession', 'Höfliches Zugeständnis.', '{{Sicherlich}} hat diese Sorge ihre Berechtigung.', array['Sicherlich','hat','diese','Sorge','ihre','Berechtigung.']::text[], array['Sicherliche','haben','Berechtigungen.']::text[], array['konzession','gehoben']::text[], 3, '[{"de":"Sicherlich hat diese Sorge ihre Berechtigung, dennoch sollte man es einmal versuchen.","en":"This concern certainly has its justification, yet one should try it once."},{"de":"Sicherlich hat deine Kritik ihre Berechtigung.","en":"Your criticism certainly has its justification."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('06a2198833d2', 'Mag das auch zutreffen, so bleibt ein Restzweifel.', 'mag das auch zutreffen, so …', 'Even if that may be true, a residual doubt remains.', 'C2', 'schreiben', 'schreiben_a2', 'konzession', 'concession', 'Konzessives ‘mögen … so’ mit Inversion.', '{{Mag}} das auch zutreffen, {{so}} bleibt ein Restzweifel.', array['Mag','das','auch','zutreffen,','so','bleibt','ein','Restzweifel.']::text[], array['Magst','zutrifft,','bleiben']::text[], array['konzession','gehoben']::text[], 4, '[{"de":"Mag das auch zutreffen, so bleibt ein Restzweifel, ob die Kosten nicht zu hoch sind.","en":"Even if that may be true, a residual doubt remains as to whether the costs are not too high."},{"de":"Mag der Plan auch gut klingen, so bleibt die Frage nach dem Geld.","en":"Even if the plan may sound good, the question of money remains."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('14ffac41cbec', 'So berechtigt der Einwand ist, er überzeugt mich nicht.', 'so … der Einwand ist, …', 'Justified as the objection is, it does not convince me.', 'C2', 'schreiben', 'schreiben_a2', 'konzession', 'concession', 'Konzessives ‘so … ist’-Muster.', '{{So}} berechtigt der Einwand ist, er überzeugt mich nicht.', array['So','berechtigt','der','Einwand','ist,','er','überzeugt','mich','nicht.']::text[], array['berechtigte','den','überzeugen']::text[], array['konzession','gehoben']::text[], 4, '[{"de":"So berechtigt der Einwand ist, er überzeugt mich nicht ganz.","en":"Justified as the objection is, it does not quite convince me."},{"de":"So schwierig die Lage ist, eine Lösung muss trotzdem gefunden werden.","en":"Difficult as the situation is, a solution must nevertheless be found."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('305938ab7e3d', 'Diese Annahme entbehrt jeder Grundlage.', 'diese Annahme entbehrt jeder Grundlage', 'This assumption is utterly without foundation.', 'C2', 'schreiben', 'schreiben_a2', 'widersprechen', 'disagreement', '‘entbehren’ + Genitiv, gehoben.', 'Diese Annahme {{entbehrt}} {{jeder}} Grundlage.', array['Diese','Annahme','entbehrt','jeder','Grundlage.']::text[], array['Dieser','entbehren','jede']::text[], array['widerspruch','gehoben']::text[], 4, '[{"de":"Diese Annahme entbehrt jeder Grundlage, denn es gibt keine Belege dafür.","en":"This assumption is utterly without foundation, as there is no evidence for it."},{"de":"Der Vorwurf entbehrt jeder Grundlage.","en":"The accusation is utterly without foundation."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('417887a275d2', 'So gesehen führt an einer Lösung kein Weg vorbei.', 'so gesehen führt an … kein Weg vorbei', 'Seen this way, there is no way around a solution.', 'C2', 'schreiben', 'schreiben_a2', 'schluss_fazit', 'conclusion', 'Idiom ‘kein Weg führt an etwas vorbei’.', 'So {{gesehen}} führt an einer Lösung kein Weg {{vorbei.}}', array['So','gesehen','führt','an','einer','Lösung','kein','Weg','vorbei.']::text[], array['gesehene','führen','den']::text[], array['fazit','idiomatisch']::text[], 4, '[{"de":"So gesehen führt an einer gemeinsamen Lösung kein Weg vorbei.","en":"Seen this way, there is no way around a joint solution."},{"de":"So gesehen führt an mehr Investitionen in Schulen kein Weg vorbei.","en":"Seen this way, there is no way around more investment in schools."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('52ce76f358eb', 'Es ist meine feste Überzeugung, dass Ehrlichkeit zählt.', 'es ist meine feste Überzeugung, dass …', 'It is my firm conviction that honesty counts.', 'C2', 'schreiben', 'schreiben_a2', 'meinung_aeussern', 'opinion', 'Emphatische Nominalkonstruktion.', 'Es ist meine feste Überzeugung, {{dass}} Ehrlichkeit zählt.', array['Es','ist','meine','feste','Überzeugung,','dass','Ehrlichkeit','zählt.']::text[], array['meiner','Überzeugungen','das']::text[], array['meinung','gehoben']::text[], 4, '[{"de":"Es ist meine feste Überzeugung, dass Ehrlichkeit am Ende immer zählt.","en":"It is my firm conviction that honesty always counts in the end."},{"de":"Es ist meine feste Überzeugung, dass Bildung jedem helfen kann.","en":"It is my firm conviction that education can help everyone."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('56aa7f9ca605', 'Stellvertretend sei hier nur ein Fall genannt.', 'stellvertretend sei … genannt', 'Let just one case be mentioned here as representative.', 'C2', 'schreiben', 'schreiben_a2', 'beispiele', 'example', 'Konjunktiv I ‘sei genannt’.', '{{Stellvertretend}} {{sei}} hier nur ein Fall genannt.', array['Stellvertretend','sei','hier','nur','ein','Fall','genannt.']::text[], array['Stellvertreter','ist','genennt.']::text[], array['beispiel','gehoben']::text[], 4, '[{"de":"Es gibt viele Probleme im Verkehr. Stellvertretend sei hier nur ein Fall genannt: der tägliche Stau am Stadtrand.","en":"There are many problems with traffic. Let just one case be mentioned here as representative: the daily traffic jam on the edge of the city."},{"de":"Stellvertretend sei nur ein Beispiel genannt, das die Lage gut zeigt.","en":"Let just one example be mentioned as representative, one that illustrates the situation well."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('5c585b6967a1', 'Ich pflichte dir in diesem Punkt bei.', 'ich pflichte … bei', 'I concur with you on this point.', 'C1', 'schreiben', 'schreiben_a2', 'zustimmen', 'agreement', '‘beipflichten’ trennbar + Dativ.', 'Ich {{pflichte}} dir in diesem Punkt {{bei.}}', array['Ich','pflichte','dir','in','diesem','Punkt','bei.']::text[], array['dich','pflichtet','ab.']::text[], array['zustimmung','gehoben']::text[], 4, '[{"de":"Ich pflichte dir in diesem Punkt bei: Ohne klare Regeln geht es nicht.","en":"I concur with you on this point: it won’t work without clear rules."},{"de":"In Bezug auf die Umwelt pflichte ich dir in diesem Punkt bei.","en":"Regarding the environment, I concur with you on this point."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('6bd26baab095', 'Treffender hätte man es nicht formulieren können.', 'treffender hätte man es nicht … können', 'One could not have put it more aptly.', 'C2', 'schreiben', 'schreiben_a2', 'zustimmen', 'agreement', 'Emphatische Zustimmung im Konjunktiv II.', '{{Treffender}} hätte man es nicht formulieren können.', array['Treffender','hätte','man','es','nicht','formulieren','können.']::text[], array['Treffende','hatte','formuliert']::text[], array['zustimmung','gehoben']::text[], 4, '[{"de":"Treffender hätte man es nicht formulieren können – das bringt es auf den Punkt.","en":"One could not have put it more aptly — that gets right to the point."},{"de":"Dein Schlusssatz überzeugt mich; treffender hätte man es nicht formulieren können.","en":"Your closing sentence convinces me; one could not have put it more aptly."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('6ee679dbfaaa', 'Als Beleg dafür mag eine aktuelle Studie dienen.', 'als Beleg dafür mag … dienen', 'A recent study may serve as evidence for this.', 'C2', 'schreiben', 'schreiben_a2', 'beispiele', 'example', 'Gehobenes ‘als Beleg dienen’ mit ‘mögen’.', 'Als {{Beleg}} dafür {{mag}} eine aktuelle Studie dienen.', array['Als','Beleg','dafür','mag','eine','aktuelle','Studie','dienen.']::text[], array['Belege','dazu','dient']::text[], array['beispiel','gehoben']::text[], 4, '[{"de":"Als Beleg dafür mag eine aktuelle Studie dienen, die einen klaren Trend zeigt.","en":"A recent study, which shows a clear trend, may serve as evidence for this."},{"de":"Viele Menschen ernähren sich heute gesünder. Als Beleg dafür mag der Erfolg vieler Bio-Läden dienen.","en":"Many people eat more healthily today. The success of many organic shops may serve as evidence for this."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('7033adab0ea3', 'Diese Sichtweise lässt einen wichtigen Aspekt außer Acht.', 'diese Sichtweise lässt … außer Acht', 'This view disregards an important aspect.', 'C2', 'schreiben', 'schreiben_a2', 'widersprechen', 'disagreement', '‘außer Acht lassen’; ‘Acht’ großgeschrieben.', 'Diese Sichtweise lässt einen wichtigen Aspekt außer {{Acht.}}', array['Diese','Sichtweise','lässt','einen','wichtigen','Aspekt','außer','Acht.']::text[], array['Dieser','lasst','acht.']::text[], array['widerspruch','gehoben']::text[], 4, '[{"de":"Diese Sichtweise lässt einen wichtigen Aspekt außer Acht: die Kosten.","en":"This view disregards an important aspect: the costs."},{"de":"Man darf dabei die Folgen für die Umwelt nicht außer Acht lassen.","en":"One must not disregard the consequences for the environment."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('8a93111f20f0', 'Letztlich läuft alles auf eine Kostenfrage hinaus.', 'letztlich läuft alles auf … hinaus', 'Ultimately, it all comes down to a question of cost.', 'C1', 'schreiben', 'schreiben_a2', 'argumentieren', 'argument', '‘auf etwas hinauslaufen’.', 'Letztlich läuft alles auf eine Kostenfrage {{hinaus.}}', array['Letztlich','läuft','alles','auf','eine','Kostenfrage','hinaus.']::text[], array['Letztliche','laufen','heraus.']::text[], array['argument','idiomatisch']::text[], 4, '[{"de":"Man kann lange diskutieren, aber letztlich läuft alles auf eine Kostenfrage hinaus.","en":"One can debate for a long time, but ultimately it all comes down to a question of cost."},{"de":"Egal, welches Modell man wählt – letztlich läuft alles auf eine Kostenfrage hinaus.","en":"No matter which model you choose – ultimately it all comes down to a question of cost."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('94e3540835aa', 'Ich bin geneigt, dieser These zuzustimmen.', 'ich bin geneigt, … zuzustimmen', 'I am inclined to agree with this thesis.', 'C2', 'schreiben', 'schreiben_a2', 'zustimmen', 'agreement', '‘geneigt sein zu’; ‘zustimmen’ regiert Dativ.', 'Ich bin geneigt, {{dieser}} These zuzustimmen.', array['Ich','bin','geneigt,','dieser','These','zuzustimmen.']::text[], array['geneigte','diese','zustimmen.']::text[], array['zustimmung','gehoben']::text[], 4, '[{"de":"Ich bin geneigt, dieser These zuzustimmen, möchte aber noch Belege sehen.","en":"I am inclined to agree with this thesis, but would still like to see evidence."},{"de":"Nach langem Überlegen bin ich geneigt, dieser These zuzustimmen.","en":"After long consideration, I am inclined to agree with this thesis."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('9ace09ce6e3f', 'Es bleibt festzuhalten, dass ein Kompromiss nötig ist.', 'es bleibt festzuhalten, dass …', 'It remains to be noted that a compromise is necessary.', 'C1', 'schreiben', 'schreiben_a2', 'schluss_fazit', 'conclusion', 'Gehobene Fazit-Formel mit ‘zu’-Infinitiv.', 'Es bleibt festzuhalten, {{dass}} ein Kompromiss nötig ist.', array['Es','bleibt','festzuhalten,','dass','ein','Kompromiss','nötig','ist.']::text[], array['bleiben','festhalten,','das']::text[], array['fazit','gehoben']::text[], 4, '[{"de":"Es bleibt festzuhalten, dass beide Seiten einen Kompromiss brauchen.","en":"It remains to be noted that both sides need a compromise."},{"de":"Es bleibt festzuhalten, dass sich die Lage deutlich verbessert hat.","en":"It remains to be noted that the situation has clearly improved."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('9b3a5ab4ab8a', 'In Anbetracht all dieser Argumente plädiere ich für Reformen.', 'in Anbetracht … plädiere ich für …', 'In view of all these arguments, I argue for reforms.', 'C2', 'schreiben', 'schreiben_a2', 'schluss_fazit', 'conclusion', '‘in Anbetracht’ + Genitiv, ‘plädieren für’.', 'In {{Anbetracht}} all dieser Argumente {{plädiere}} ich für Reformen.', array['In','Anbetracht','all','dieser','Argumente','plädiere','ich','für','Reformen.']::text[], array['Anbetrachte','plädiert','den']::text[], array['fazit','gehoben']::text[], 4, '[{"de":"In Anbetracht all dieser Argumente plädiere ich für eine schnelle Reform.","en":"In view of all these arguments, I argue for a swift reform."},{"de":"In Anbetracht der hohen Kosten plädiere ich für eine günstigere Lösung.","en":"In view of the high costs, I argue for a cheaper solution."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('9d33ef4ea7be', 'Dem kann so pauschal nicht zugestimmt werden.', 'dem kann so nicht zugestimmt werden', 'That cannot be agreed with in such general terms.', 'C2', 'schreiben', 'schreiben_a2', 'widersprechen', 'disagreement', 'Unpersönliches Passiv, distanziert.', '{{Dem}} kann so pauschal nicht zugestimmt werden.', array['Dem','kann','so','pauschal','nicht','zugestimmt','werden.']::text[], array['Den','pauschale','zustimmen']::text[], array['widerspruch','gehoben']::text[], 4, '[{"de":"Dem kann so pauschal nicht zugestimmt werden, denn jeder Fall ist anders.","en":"That cannot be agreed with in such general terms, because every case is different."},{"de":"Dieser Behauptung kann so pauschal nicht zugestimmt werden.","en":"This claim cannot be agreed with in such general terms."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('a91b945a0b2c', 'Das greift meines Erachtens zu kurz.', 'das greift zu kurz', 'That falls short, in my view.', 'C1', 'schreiben', 'schreiben_a2', 'widersprechen', 'disagreement', 'Idiomatisch ‘zu kurz greifen’.', 'Das greift meines Erachtens zu {{kurz.}}', array['Das','greift','meines','Erachtens','zu','kurz.']::text[], array['dass','greifen','kurzem']::text[], array['widerspruch','idiomatisch']::text[], 4, '[{"de":"Das greift meines Erachtens zu kurz, weil die sozialen Folgen fehlen.","en":"That falls short, in my view, because the social consequences are missing."},{"de":"Nur über Geld zu reden, greift hier zu kurz.","en":"Talking only about money falls short here."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('aa0ca7e128a2', 'Bei aller Kritik darf man die Vorzüge nicht übersehen.', 'bei aller Kritik …', 'For all the criticism, one must not overlook the merits.', 'C2', 'schreiben', 'schreiben_a2', 'konzession', 'concession', '‘bei aller Kritik’ konzessiv.', 'Bei {{aller}} Kritik darf man die Vorzüge nicht übersehen.', array['Bei','aller','Kritik','darf','man','die','Vorzüge','nicht','übersehen.']::text[], array['alle','darfst','übersieht']::text[], array['konzession','gehoben']::text[], 4, '[{"de":"Bei aller Kritik darf man die Vorzüge des neuen Systems nicht übersehen.","en":"For all the criticism, one must not overlook the merits of the new system."},{"de":"Bei aller Kritik sollte man auch sehen, dass sich vieles verbessert hat.","en":"For all the criticism, one should also see that much has improved."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('b6c5ed16d55c', 'Es liegt auf der Hand, dass Prävention günstiger ist.', 'es liegt auf der Hand, dass …', 'It is obvious that prevention is cheaper.', 'C2', 'schreiben', 'schreiben_a2', 'argumentieren', 'argument', 'Idiom ‘auf der Hand liegen’.', 'Es liegt auf der Hand, {{dass}} Prävention günstiger ist.', array['Es','liegt','auf','der','Hand,','dass','Prävention','günstiger','ist.']::text[], array['liegen','den','das']::text[], array['argument','idiomatisch']::text[], 4, '[{"de":"Es liegt auf der Hand, dass Prävention günstiger ist als eine spätere Behandlung.","en":"It is obvious that prevention is cheaper than later treatment."},{"de":"Es liegt auf der Hand, dass wir ohne Investitionen nicht weiterkommen.","en":"It is obvious that we won''t get anywhere without investment."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('c51158a961b3', 'Mit deinem Einwand sprichst du einen wunden Punkt an.', 'mit deinem Einwand sprichst du … an', 'With your objection you touch on a sore point.', 'C2', 'schreiben', 'schreiben_a2', 'einleitung_kontakt', 'intro', 'Idiom ‘einen wunden Punkt ansprechen’.', 'Mit deinem Einwand sprichst du einen wunden Punkt {{an.}}', array['Mit','deinem','Einwand','sprichst','du','einen','wunden','Punkt','an.']::text[], array['deinen','sprecht','wundes']::text[], array['einleitung','idiomatisch']::text[], 4, '[{"de":"Mit deinem Einwand sprichst du einen wunden Punkt an, denn das Geld fehlt wirklich überall.","en":"With your objection you touch on a sore point, because money really is lacking everywhere."},{"de":"Mit deiner Frage sprichst du einen wunden Punkt an.","en":"With your question you touch on a sore point."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('cd1ff13e01b0', 'Damit erübrigt sich jede weitere Diskussion.', 'damit erübrigt sich …', 'This renders any further discussion unnecessary.', 'C2', 'schreiben', 'schreiben_a2', 'argumentieren', 'argument', '‘sich erübrigen’ idiomatisch.', '{{Damit}} {{erübrigt}} sich jede weitere Diskussion.', array['Damit','erübrigt','sich','jede','weitere','Diskussion.']::text[], array['Damals','erübrigen','jeder']::text[], array['argument','gehoben']::text[], 4, '[{"de":"Die Zahlen sind eindeutig. Damit erübrigt sich jede weitere Diskussion.","en":"The figures are clear. This renders any further discussion unnecessary."},{"de":"Der Chef hat schon entschieden – damit erübrigt sich jede weitere Diskussion.","en":"The boss has already decided – this renders any further discussion unnecessary."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('d53d216ccb36', 'Ich neige zu der Auffassung, dass Strenge hier hilft.', 'ich neige zu der Auffassung, dass …', 'I tend towards the view that strictness helps here.', 'C1', 'schreiben', 'schreiben_a2', 'meinung_aeussern', 'opinion', '‘zu der Auffassung neigen’.', 'Ich neige zu der {{Auffassung,}} dass Strenge hier hilft.', array['Ich','neige','zu','der','Auffassung,','dass','Strenge','hier','hilft.']::text[], array['zur','Auffassungen','das']::text[], array['meinung','gehoben']::text[], 4, '[{"de":"Ich neige zu der Auffassung, dass klare Regeln am Ende allen helfen.","en":"I tend towards the view that clear rules help everyone in the end."},{"de":"Ich neige zu der Auffassung, dass der Markt sich selbst nicht regelt.","en":"I tend towards the view that the market does not regulate itself."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('e09afcaec2bd', 'Wenn man mich fragt, gehört dieses Thema dringend diskutiert.', 'wenn man mich fragt, …', 'If you ask me, this topic urgently needs discussing.', 'C2', 'schreiben', 'schreiben_a2', 'meinung_aeussern', 'opinion', 'Idiomatische Einleitung; ‘gehört + Partizip’ süddeutsch-umgangssprachlich.', 'Wenn man {{mich}} fragt, gehört dieses Thema dringend diskutiert.', array['Wenn','man','mich','fragt,','gehört','dieses','Thema','dringend','diskutiert.']::text[], array['man','fragen','dringende']::text[], array['meinung','idiomatisch']::text[], 4, '[{"de":"Wenn man mich fragt, gehört dieses Thema endlich offen diskutiert.","en":"If you ask me, this topic finally needs to be discussed openly."},{"de":"Wenn man mich fragt, ist die ganze Aufregung übertrieben.","en":"If you ask me, the whole fuss is exaggerated."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('f0a291419552', 'Dieser Befund lässt nur einen Schluss zu.', 'dieser Befund lässt nur einen Schluss zu', 'This finding permits only one conclusion.', 'C2', 'schreiben', 'schreiben_a2', 'argumentieren', 'argument', '‘zulassen’ trennbar, gehoben.', 'Dieser Befund {{lässt}} nur einen Schluss {{zu.}}', array['Dieser','Befund','lässt','nur','einen','Schluss','zu.']::text[], array['Diese','lasst','ab.']::text[], array['argument','gehoben']::text[], 4, '[{"de":"Alle Studien weisen in dieselbe Richtung. Dieser Befund lässt nur einen Schluss zu.","en":"All studies point in the same direction. This finding permits only one conclusion."},{"de":"Dieser Befund lässt nur einen Schluss zu: Wir müssen sofort handeln.","en":"This finding permits only one conclusion: we must act immediately."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('f70b31910524', 'Ich kann mich dieser Argumentation nur anschließen.', 'ich kann mich … anschließen', 'I can only endorse this line of argument.', 'C2', 'schreiben', 'schreiben_a2', 'zustimmen', 'agreement', '‘sich einer Sache anschließen’ + Dativ.', 'Ich kann mich {{dieser}} Argumentation nur anschließen.', array['Ich','kann','mich','dieser','Argumentation','nur','anschließen.']::text[], array['mir','diese','anschließe.']::text[], array['zustimmung','gehoben']::text[], 4, '[{"de":"Ich kann mich dieser Argumentation nur anschließen, sie ist gut belegt.","en":"I can only endorse this line of argument, it is well supported."},{"de":"Nach all den Beispielen kann ich mich dieser Argumentation nur anschließen.","en":"After all these examples, I can only endorse this line of argument."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('fb236666b62d', 'Kaum ein Thema wird derzeit so kontrovers diskutiert.', 'kaum ein Thema wird so … diskutiert', 'Hardly any topic is currently discussed so controversially.', 'C2', 'schreiben', 'schreiben_a2', 'einleitung_kontakt', 'intro', 'Emphatischer Themeneinstieg.', '{{Kaum}} ein Thema wird derzeit so kontrovers diskutiert.', array['Kaum','ein','Thema','wird','derzeit','so','kontrovers','diskutiert.']::text[], array['Kaume','werden','kontroverse']::text[], array['einleitung','gehoben']::text[], 4, '[{"de":"Kaum ein Thema wird derzeit so kontrovers diskutiert wie der Klimaschutz.","en":"Hardly any topic is currently discussed so controversially as climate protection."},{"de":"Kaum ein Thema wird derzeit so kontrovers diskutiert, und jeder hat eine Meinung dazu.","en":"Hardly any topic is currently discussed so controversially, and everyone has an opinion on it."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('0bda2a6927eb', 'Vielen Dank für Ihr Vertrauen.', 'vielen Dank für Ihr Vertrauen', 'Many thanks for your trust.', 'B1', 'schreiben', 'schreiben_a3', 'danken_bedauern', 'thanks', 'Formeller Dank.', '{{Vielen}} {{Dank}} für Ihr Vertrauen.', array['Vielen','Dank','für','Ihr','Vertrauen.']::text[], array['ihr','Ihren','Vertrauen,']::text[], array['danken','formell']::text[], 1, '[{"de":"Vielen Dank für Ihr Vertrauen. Wir werden Ihr Anliegen so schnell wie möglich bearbeiten.","en":"Many thanks for your trust. We will process your request as quickly as possible."},{"de":"Vielen Dank für Ihr Vertrauen in unsere Sprachschule – wir freuen uns, Sie als Kursteilnehmer begrüßen zu dürfen.","en":"Many thanks for your trust in our language school – we are pleased to welcome you as a course participant."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('6996ed7fb695', 'Vielen Dank für Ihre Antwort.', 'vielen Dank für Ihre Antwort', 'Many thanks for your reply.', 'B1', 'schreiben', 'schreiben_a3', 'danken_bedauern', 'thanks', 'Formeller Dank mit Ihre.', '{{Vielen}} {{Dank}} für Ihre Antwort.', array['Vielen','Dank','für','Ihre','Antwort.']::text[], array['ihre','Antworten','Ihren']::text[], array['danken','formell']::text[], 1, '[{"de":"Vielen Dank für Ihre Antwort. Der vorgeschlagene Termin passt mir sehr gut.","en":"Many thanks for your reply. The proposed appointment suits me very well."},{"de":"Vielen Dank für Ihre Antwort – damit sind alle meine Fragen geklärt.","en":"Many thanks for your reply – with that all my questions are answered."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('978565001183', 'Mit freundlichen Grüßen', 'mit freundlichen Grüßen', 'Kind regards', 'B1', 'schreiben', 'schreiben_a3', 'schluss_fazit', 'signoff', 'Standard-Grußformel formell.', 'Mit {{freundlichen}} {{Grüßen}}', array['Mit','freundlichen','Grüßen']::text[], array['freundlich','Grüssen','Gruß']::text[], array['schluss','formell']::text[], 1, '[{"de":"Vielen Dank für Ihre Hilfe.\n\nMit freundlichen Grüßen\nLena Schmidt","en":"Many thanks for your help.\n\nKind regards\nLena Schmidt"},{"de":"Ich hoffe auf eine baldige Antwort.\n\nMit freundlichen Grüßen","en":"I hope for a prompt reply.\n\nKind regards"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('aa4a8242a992', 'Danke für Ihre Geduld.', 'danke für Ihre Geduld', 'Thank you for your patience.', 'B1', 'schreiben', 'schreiben_a3', 'danken_bedauern', 'thanks', 'Knapper formeller Dank.', '{{Danke}} für Ihre {{Geduld.}}', array['Danke','für','Ihre','Geduld.']::text[], array['ihre','Ihren','Geduld,']::text[], array['danken','formell']::text[], 1, '[{"de":"Die Lieferung verzögert sich um wenige Tage. Danke für Ihre Geduld.","en":"The delivery is delayed by a few days. Thank you for your patience."},{"de":"Wir prüfen Ihren Antrag gerade sorgfältig. Danke für Ihre Geduld.","en":"We are currently reviewing your application carefully. Thank you for your patience."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('bb9e7d694db2', 'Mit besten Grüßen', 'mit besten Grüßen', 'With best regards', 'B1', 'schreiben', 'schreiben_a3', 'schluss_fazit', 'signoff', 'Alternative Grußformel.', 'Mit {{besten}} {{Grüßen}}', array['Mit','besten','Grüßen']::text[], array['beste','Grüssen','Gruß']::text[], array['schluss','formell']::text[], 1, '[{"de":"Vielen Dank für die schnelle Bearbeitung.\n\nMit besten Grüßen\nTom Albrecht","en":"Many thanks for the quick processing.\n\nWith best regards\nTom Albrecht"},{"de":"Ich freue mich auf die Zusammenarbeit.\n\nMit besten Grüßen","en":"I look forward to the collaboration.\n\nWith best regards"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('dd67e9ee0204', 'Sehr geehrte Damen und Herren,', 'sehr geehrte Damen und Herren', 'Dear Sir or Madam,', 'B1', 'schreiben', 'schreiben_a3', 'anliegen', 'greeting', 'Standard-Anrede ohne bekannten Empfänger.', 'Sehr {{geehrte}} {{Damen}} und Herren,', array['Sehr','geehrte','Damen','und','Herren,']::text[], array['geehrten','Herrn,','Dame']::text[], array['anliegen','formell','anrede']::text[], 1, '[{"de":"Sehr geehrte Damen und Herren, ich interessiere mich für Ihr Angebot.","en":"Dear Sir or Madam, I am interested in your offer."},{"de":"Sehr geehrte Damen und Herren, hiermit bewerbe ich mich bei Ihnen.","en":"Dear Sir or Madam, I hereby apply to you."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('eb1ed879c021', 'Leider kann ich nicht teilnehmen.', 'leider kann ich nicht teilnehmen', 'Unfortunately, I cannot attend.', 'B1', 'schreiben', 'schreiben_a3', 'absagen_entschuldigen', 'declining', 'Klare Absage mit leider.', '{{Leider}} {{kann}} ich nicht teilnehmen.', array['Leider','kann','ich','nicht','teilnehmen.']::text[], array['Leiber','teilnehme.','kann,']::text[], array['absagen','formell']::text[], 1, '[{"de":"Leider kann ich nicht teilnehmen, weil ich an dem Tag verreist bin.","en":"Unfortunately, I cannot attend, because I am away travelling that day."},{"de":"Vielen Dank für die Einladung, doch leider kann ich nicht teilnehmen.","en":"Many thanks for the invitation, but unfortunately I cannot attend."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('04b3ebdd47cc', 'Ich bitte Sie, die Verspätung zu entschuldigen.', 'ich bitte Sie die Verspätung zu entschuldigen', 'I ask you to excuse the delay.', 'B2', 'schreiben', 'schreiben_a3', 'absagen_entschuldigen', 'apology', 'bitten + zu-Infinitiv; Höflichkeit.', 'Ich {{bitte}} Sie, die {{Verspätung}} zu entschuldigen.', array['Ich','bitte','Sie,','die','Verspätung','zu','entschuldigen.']::text[], array['bitten','sie,','entschuldigt']::text[], array['entschuldigen','formell']::text[], 2, '[{"de":"Ich bitte Sie, die Verspätung zu entschuldigen; der Zug hatte Ausfall.","en":"I ask you to excuse the delay; the train was cancelled."},{"de":"Ich bitte Sie, die Verspätung meiner Antwort zu entschuldigen.","en":"I ask you to excuse the delay in my reply."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('1285de395a8f', 'Ich wende mich mit einer Frage an Sie.', 'ich wende mich mit einer Frage an Sie', 'I am contacting you with a question.', 'B2', 'schreiben', 'schreiben_a3', 'anliegen', 'opening', 'sich wenden an + Akkusativ.', 'Ich {{wende}} mich mit einer {{Frage}} an Sie.', array['Ich','wende','mich','mit','einer','Frage','an','Sie.']::text[], array['wenden','sie.','Fragen']::text[], array['anliegen','formell']::text[], 2, '[{"de":"Ich wende mich mit einer Frage an Sie, da auf Ihrer Website nichts dazu steht.","en":"I am contacting you with a question, as there is nothing about it on your website."},{"de":"Ich wende mich mit einer Frage zur Rückerstattung an Sie.","en":"I am contacting you with a question about the refund."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('1815081a4f3a', 'Könnten Sie mir bitte weiterhelfen?', 'könnten Sie mir bitte weiterhelfen', 'Could you please help me further?', 'B1', 'schreiben', 'schreiben_a3', 'vorschlag_bitte', 'request', 'Konjunktiv II für höfliche Bitte.', '{{Könnten}} {{Sie}} mir bitte weiterhelfen?', array['Könnten','Sie','mir','bitte','weiterhelfen?']::text[], array['Können','sie','weiterhilft?']::text[], array['bitte','formell','konjunktiv']::text[], 2, '[{"de":"Ich verstehe das Formular nicht ganz. Könnten Sie mir bitte weiterhelfen?","en":"I don''t quite understand the form. Could you please help me further?"},{"de":"Ich habe noch eine Frage zur Anmeldung. Könnten Sie mir bitte weiterhelfen?","en":"I still have a question about the registration. Could you please help me further?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('40b2be25a5c7', 'Ich danke Ihnen für Ihre Mühe.', 'ich danke Ihnen für Ihre Mühe', 'Thank you for your effort.', 'B1', 'schreiben', 'schreiben_a3', 'danken_bedauern', 'thanks', 'danken + Dativ Sie-Form.', 'Ich {{danke}} Ihnen für Ihre {{Mühe.}}', array['Ich','danke','Ihnen','für','Ihre','Mühe.']::text[], array['ihnen','Mühen','ihre']::text[], array['danken','formell','dativ']::text[], 2, '[{"de":"Ich danke Ihnen für Ihre Mühe und melde mich, sobald die Unterlagen vollständig sind.","en":"Thank you for your effort, and I will get in touch as soon as the documents are complete."},{"de":"Ich danke Ihnen für Ihre Mühe, mir den Sachverhalt so ausführlich zu erklären.","en":"Thank you for your effort in explaining the matter to me in such detail."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('69c7f0566ec3', 'Ich bitte um Ihr Verständnis.', 'ich bitte um Ihr Verständnis', 'I ask for your understanding.', 'B1', 'schreiben', 'schreiben_a3', 'vorschlag_bitte', 'request', 'um Verständnis bitten.', 'Ich {{bitte}} {{um}} Ihr Verständnis.', array['Ich','bitte','um','Ihr','Verständnis.']::text[], array['bitten','ihr','Verständnisse']::text[], array['bitte','formell']::text[], 2, '[{"de":"Der Termin muss leider verschoben werden. Ich bitte um Ihr Verständnis.","en":"Unfortunately, the appointment has to be postponed. I ask for your understanding."},{"de":"Aus organisatorischen Gründen ist das nicht möglich. Ich bitte um Ihr Verständnis.","en":"For organizational reasons this is not possible. I ask for your understanding."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('7ddfdfc50f60', 'Bitte entschuldigen Sie die Unannehmlichkeiten.', 'bitte entschuldigen Sie die Unannehmlichkeiten', 'Please excuse the inconvenience.', 'B2', 'schreiben', 'schreiben_a3', 'absagen_entschuldigen', 'apology', 'Höflichkeitsformel mit Sie-Imperativ.', 'Bitte {{entschuldigen}} {{Sie}} die Unannehmlichkeiten.', array['Bitte','entschuldigen','Sie','die','Unannehmlichkeiten.']::text[], array['entschuldige','sie','Unannehmlichkeit']::text[], array['entschuldigen','formell']::text[], 2, '[{"de":"Bitte entschuldigen Sie die Unannehmlichkeiten; wir kümmern uns sofort darum.","en":"Please excuse the inconvenience; we will take care of it immediately."},{"de":"Bitte entschuldigen Sie die Unannehmlichkeiten durch die Bauarbeiten.","en":"Please excuse the inconvenience caused by the construction work."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('813a74e14384', 'Ich muss meine Teilnahme leider absagen.', 'ich muss meine Teilnahme leider absagen', 'Unfortunately, I have to cancel my participation.', 'B2', 'schreiben', 'schreiben_a3', 'absagen_entschuldigen', 'declining', 'Teilnahme absagen.', 'Ich {{muss}} meine {{Teilnahme}} leider absagen.', array['Ich','muss','meine','Teilnahme','leider','absagen.']::text[], array['müssen','meiner','absage']::text[], array['absagen','formell']::text[], 2, '[{"de":"Ich muss meine Teilnahme leider absagen, weil ich beruflich verhindert bin.","en":"Unfortunately, I have to cancel my participation, because I am prevented by work."},{"de":"Aus gesundheitlichen Gründen muss ich meine Teilnahme leider absagen.","en":"For health reasons, I unfortunately have to cancel my participation."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('835ad1cf7c7f', 'Würden Sie mir bitte einen Termin nennen?', 'würden Sie mir bitte einen Termin nennen', 'Would you please suggest an appointment time?', 'B2', 'schreiben', 'schreiben_a3', 'vorschlag_bitte', 'request', 'Würde-Form für höfliche Bitte.', '{{Würden}} {{Sie}} mir bitte einen Termin nennen?', array['Würden','Sie','mir','bitte','einen','Termin','nennen?']::text[], array['Werden','sie','nennt?']::text[], array['bitte','formell','konjunktiv']::text[], 2, '[{"de":"Ich möchte gern einen Beratungstermin vereinbaren. Würden Sie mir bitte einen Termin nennen?","en":"I would like to arrange a consultation. Would you please name an appointment for me?"},{"de":"Würden Sie mir bitte einen Termin nennen, der auch am Nachmittag möglich ist?","en":"Would you please name an appointment for me that is also possible in the afternoon?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('89dd133cbc36', 'Ich bitte Sie um eine kurze Rückmeldung.', 'ich bitte Sie um eine kurze Rückmeldung', 'I ask you for a brief reply.', 'B2', 'schreiben', 'schreiben_a3', 'vorschlag_bitte', 'request', 'bitten um + Akkusativ.', 'Ich {{bitte}} Sie {{um}} eine kurze Rückmeldung.', array['Ich','bitte','Sie','um','eine','kurze','Rückmeldung.']::text[], array['bitten','sie','Rückmeldungen']::text[], array['bitte','formell']::text[], 2, '[{"de":"Ich bitte Sie um eine kurze Rückmeldung, ob der vorgeschlagene Termin passt.","en":"I ask you for a brief reply as to whether the proposed appointment suits."},{"de":"Damit ich weiterplanen kann, bitte ich Sie um eine kurze Rückmeldung.","en":"So that I can plan further, I ask you for a brief reply."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('95b56ab90d1f', 'Ich freue mich auf Ihre Antwort.', 'ich freue mich auf Ihre Antwort', 'I look forward to your reply.', 'B1', 'schreiben', 'schreiben_a3', 'schluss_fazit', 'closing', 'sich freuen auf + Akkusativ, formell.', 'Ich {{freue}} mich {{auf}} Ihre Antwort.', array['Ich','freue','mich','auf','Ihre','Antwort.']::text[], array['freut','ihre','über']::text[], array['schluss','formell']::text[], 2, '[{"de":"Ich freue mich auf Ihre Antwort und wünsche Ihnen ein schönes Wochenende.","en":"I look forward to your reply and wish you a pleasant weekend."},{"de":"Bei weiteren Fragen melde ich mich gerne. Ich freue mich auf Ihre Antwort.","en":"I''ll be glad to get in touch with further questions. I look forward to your reply."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('9780a55ae9b0', 'Ich muss den Termin leider absagen.', 'ich muss den Termin leider absagen', 'Unfortunately, I have to cancel the appointment.', 'B1', 'schreiben', 'schreiben_a3', 'absagen_entschuldigen', 'declining', 'Termin absagen.', 'Ich {{muss}} den {{Termin}} leider absagen.', array['Ich','muss','den','Termin','leider','absagen.']::text[], array['müssen','dem','absage']::text[], array['absagen','formell']::text[], 2, '[{"de":"Ich muss den Termin leider absagen und schlage Ihnen einen neuen vor.","en":"Unfortunately, I have to cancel the appointment and suggest a new one to you."},{"de":"Wegen einer Erkrankung muss ich den Termin leider absagen.","en":"Due to an illness, I unfortunately have to cancel the appointment."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('98b16708491a', 'Ich schreibe Ihnen bezüglich meiner Buchung.', 'ich schreibe Ihnen bezüglich meiner Buchung', 'I am writing to you regarding my booking.', 'B2', 'schreiben', 'schreiben_a3', 'anliegen', 'opening', 'bezüglich + Genitiv.', 'Ich {{schreibe}} Ihnen {{bezüglich}} meiner Buchung.', array['Ich','schreibe','Ihnen','bezüglich','meiner','Buchung.']::text[], array['ihnen','meine','Buchungen']::text[], array['anliegen','formell']::text[], 2, '[{"de":"Ich schreibe Ihnen bezüglich meiner Buchung, die ich gern ändern möchte.","en":"I am writing to you regarding my booking, which I would like to change."},{"de":"Ich schreibe Ihnen bezüglich meiner Buchung vom letzten Montag.","en":"I am writing to you regarding my booking from last Monday."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('9be91f1e417f', 'Ich möchte mich über ein Problem beschweren.', 'ich möchte mich über ein Problem beschweren', 'I would like to complain about a problem.', 'B2', 'schreiben', 'schreiben_a3', 'anliegen', 'opening', 'sich beschweren über + Akkusativ.', 'Ich {{möchte}} mich {{über}} ein Problem beschweren.', array['Ich','möchte','mich','über','ein','Problem','beschweren.']::text[], array['möchten','auf','beschwert']::text[], array['anliegen','formell']::text[], 2, '[{"de":"Ich möchte mich über ein Problem beschweren, das seit Tagen besteht.","en":"I would like to complain about a problem that has existed for days."},{"de":"Ich möchte mich über ein Problem mit der Lieferung beschweren.","en":"I would like to complain about a problem with the delivery."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('9f7f7065a271', 'Leider muss ich Ihnen absagen.', 'leider muss ich Ihnen absagen', 'Unfortunately, I have to decline.', 'B2', 'schreiben', 'schreiben_a3', 'absagen_entschuldigen', 'declining', 'jdm. absagen + Dativ.', '{{Leider}} muss ich {{Ihnen}} absagen.', array['Leider','muss','ich','Ihnen','absagen.']::text[], array['müssen','ihnen','absage']::text[], array['absagen','formell','dativ']::text[], 2, '[{"de":"Leider muss ich Ihnen absagen, da der Termin nicht mehr passt.","en":"Unfortunately, I have to decline, as the date no longer suits me."},{"de":"So gern ich käme, leider muss ich Ihnen absagen.","en":"As much as I would like to come, unfortunately I have to decline."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('af54a4a833e4', 'Könnten Sie mir die Unterlagen zusenden?', 'könnten Sie mir die Unterlagen zusenden', 'Could you send me the documents?', 'B2', 'schreiben', 'schreiben_a3', 'vorschlag_bitte', 'request', 'jdm. etw. zusenden.', '{{Könnten}} {{Sie}} mir die Unterlagen zusenden?', array['Könnten','Sie','mir','die','Unterlagen','zusenden?']::text[], array['Können','sie','zusendet?']::text[], array['bitte','formell']::text[], 2, '[{"de":"Für meine Anmeldung fehlen mir noch einige Papiere. Könnten Sie mir die Unterlagen zusenden?","en":"I am still missing some papers for my registration. Could you send me the documents?"},{"de":"Könnten Sie mir die Unterlagen bitte per E-Mail zusenden?","en":"Could you please send me the documents by email?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('bb823766bc6a', 'ich schreibe Ihnen wegen Ihrer Anzeige.', 'ich schreibe Ihnen wegen Ihrer Anzeige', 'I am writing to you regarding your advertisement.', 'B1', 'schreiben', 'schreiben_a3', 'anliegen', 'opening', 'wegen + Genitiv; Anliegen nennen. Kleinschreibung nach Anredekomma.', 'ich {{schreibe}} Ihnen {{wegen}} Ihrer Anzeige.', array['ich','schreibe','Ihnen','wegen','Ihrer','Anzeige.']::text[], array['ihnen','ihrer','Anzeigen']::text[], array['anliegen','formell']::text[], 2, '[{"de":"Sehr geehrte Damen und Herren, ich schreibe Ihnen wegen Ihrer Anzeige im Internet.","en":"Dear Sir or Madam, I am writing to you regarding your advertisement on the internet."},{"de":"ich schreibe Ihnen wegen Ihrer Anzeige und hätte einige Fragen.","en":"I am writing to you regarding your advertisement and would have a few questions."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('cd5861a626b4', 'Bitte teilen Sie mir Ihre Entscheidung mit.', 'bitte teilen Sie mir Ihre Entscheidung mit', 'Please inform me of your decision.', 'B2', 'schreiben', 'schreiben_a3', 'vorschlag_bitte', 'request', 'jdm. etw. mitteilen, trennbares Verb mit, Sie-Imperativ.', 'Bitte {{teilen}} {{Sie}} mir Ihre Entscheidung mit.', array['Bitte','teilen','Sie','mir','Ihre','Entscheidung','mit.']::text[], array['teile','sie','Entscheidungen']::text[], array['bitte','formell']::text[], 2, '[{"de":"Bitte teilen Sie mir Ihre Entscheidung bis Freitag mit, damit ich die Plätze reservieren kann.","en":"Please inform me of your decision by Friday so that I can reserve the spots."},{"de":"Bitte teilen Sie mir Ihre Entscheidung mit, sobald Sie alles geprüft haben.","en":"Please inform me of your decision as soon as you have checked everything."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('d190175a6eea', 'Ich danke Ihnen im Voraus.', 'ich danke Ihnen im Voraus', 'Thank you in advance.', 'B2', 'schreiben', 'schreiben_a3', 'danken_bedauern', 'thanks', 'im Voraus als feste Wendung.', 'Ich {{danke}} Ihnen im {{Voraus.}}', array['Ich','danke','Ihnen','im','Voraus.']::text[], array['ihnen','voraus.','in']::text[], array['danken','formell']::text[], 2, '[{"de":"Bitte schicken Sie mir die Bestätigung bis Freitag. Ich danke Ihnen im Voraus.","en":"Please send me the confirmation by Friday. Thank you in advance."},{"de":"Für Ihre Unterstützung bei der Anmeldung danke ich Ihnen im Voraus.","en":"I thank you in advance for your support with the registration."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('0db2f1a89852', 'Ich hoffe sehr auf Ihr Verständnis.', 'ich hoffe sehr auf Ihr Verständnis', 'I very much hope for your understanding.', 'C1', 'schreiben', 'schreiben_a3', 'absagen_entschuldigen', 'apology', 'hoffen auf + Akkusativ; nach Absage.', 'Ich {{hoffe}} sehr {{auf}} Ihr Verständnis.', array['Ich','hoffe','sehr','auf','Ihr','Verständnis.']::text[], array['hoffen','über','ihr']::text[], array['entschuldigen','formell']::text[], 3, '[{"de":"Ich hoffe sehr auf Ihr Verständnis und melde mich, sobald es möglich ist.","en":"I very much hope for your understanding and will get in touch as soon as possible."},{"de":"Für die kurzfristige Absage hoffe ich sehr auf Ihr Verständnis.","en":"For the short-notice cancellation, I very much hope for your understanding."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('0e7578726baf', 'Ich bitte vielmals um Entschuldigung für mein Versäumnis.', 'ich bitte vielmals um Entschuldigung für mein Versäumnis', 'I sincerely apologize for my oversight.', 'C1', 'schreiben', 'schreiben_a3', 'absagen_entschuldigen', 'apology', 'um Entschuldigung bitten; vielmals als Verstärker.', 'Ich {{bitte}} vielmals um {{Entschuldigung}} für mein Versäumnis.', array['Ich','bitte','vielmals','um','Entschuldigung','für','mein','Versäumnis.']::text[], array['bitten','Versäumnisse','meinem']::text[], array['entschuldigen','formell','idiomatisch']::text[], 3, '[{"de":"Ich bitte vielmals um Entschuldigung für mein Versäumnis und hole alles nach.","en":"I sincerely apologize for my oversight and will make up for everything."},{"de":"Für die fehlenden Unterlagen bitte ich vielmals um Entschuldigung.","en":"For the missing documents, I sincerely apologize."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('32aaa7b6caf0', 'Ich bedauere, Ihnen nicht helfen zu können.', 'ich bedauere Ihnen nicht helfen zu können', 'I regret that I cannot help you.', 'C1', 'schreiben', 'schreiben_a3', 'absagen_entschuldigen', 'declining', 'bedauern + zu-Infinitiv; gehobene Absage.', 'Ich {{bedauere,}} Ihnen nicht helfen zu {{können.}}', array['Ich','bedauere,','Ihnen','nicht','helfen','zu','können.']::text[], array['bedauern,','ihnen','gekonnt']::text[], array['absagen','formell']::text[], 3, '[{"de":"Ich bedauere, Ihnen nicht helfen zu können, da ich selbst nicht zuständig bin.","en":"I regret that I cannot help you, as I am not responsible myself."},{"de":"Leider bedauere ich, Ihnen in dieser Sache nicht helfen zu können.","en":"Unfortunately, I regret that I cannot help you in this matter."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('5096078e6d16', 'Für Ihr Verständnis danken wir Ihnen herzlich.', 'für Ihr Verständnis danken wir Ihnen herzlich', 'We thank you warmly for your understanding.', 'C1', 'schreiben', 'schreiben_a3', 'danken_bedauern', 'thanks', 'Inversion mit vorangestellter Präpositionalgruppe.', 'Für Ihr {{Verständnis}} {{danken}} wir Ihnen herzlich.', array['Für','Ihr','Verständnis','danken','wir','Ihnen','herzlich.']::text[], array['ihr','ihnen','herzliche']::text[], array['danken','formell']::text[], 3, '[{"de":"Die Veranstaltung muss leider verschoben werden. Für Ihr Verständnis danken wir Ihnen herzlich.","en":"Unfortunately, the event has to be postponed. We thank you warmly for your understanding."},{"de":"Die Bearbeitung dauert etwas länger als gewohnt. Für Ihr Verständnis danken wir Ihnen herzlich.","en":"Processing is taking a little longer than usual. We thank you warmly for your understanding."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('538b009cb30e', 'Leider müssen wir Ihnen mitteilen, dass es nicht klappt.', 'leider müssen wir Ihnen mitteilen dass es nicht klappt', 'Unfortunately, we must inform you that it won''t work out.', 'B2', 'schreiben', 'schreiben_a3', 'danken_bedauern', 'regret', 'jdm. mitteilen; dass-Satz.', 'Leider {{müssen}} wir Ihnen {{mitteilen,}} dass es nicht klappt.', array['Leider','müssen','wir','Ihnen','mitteilen,','dass','es','nicht','klappt.']::text[], array['müsst','ihnen','das']::text[], array['bedauern','formell','dass']::text[], 3, '[{"de":"Leider müssen wir Ihnen mitteilen, dass es mit dem gewünschten Termin nicht klappt.","en":"Unfortunately, we must inform you that the desired appointment won''t work out."},{"de":"Leider müssen wir Ihnen mitteilen, dass der Kurs in dieser Woche ausfällt.","en":"Unfortunately, we must inform you that the course is cancelled this week."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('5bf90b6ad3f9', 'Ich verbleibe mit freundlichen Grüßen.', 'ich verbleibe mit freundlichen Grüßen', 'I remain, with kind regards.', 'C1', 'schreiben', 'schreiben_a3', 'schluss_fazit', 'signoff', 'verbleiben als formeller Abschluss.', 'Ich {{verbleibe}} mit {{freundlichen}} Grüßen.', array['Ich','verbleibe','mit','freundlichen','Grüßen.']::text[], array['verbleiben','freundlich','Grüssen.']::text[], array['schluss','formell','idiomatisch']::text[], 3, '[{"de":"Ich danke Ihnen nochmals für Ihre Hilfe und verbleibe mit freundlichen Grüßen.","en":"I thank you again for your help and remain, with kind regards."},{"de":"In Erwartung Ihrer Rückmeldung verbleibe ich mit freundlichen Grüßen.","en":"Awaiting your reply, I remain, with kind regards."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('64a112667278', 'Für Rückfragen stehe ich Ihnen gerne zur Verfügung.', 'für Rückfragen stehe ich Ihnen gerne zur Verfügung', 'I am happy to be available for any questions.', 'B2', 'schreiben', 'schreiben_a3', 'schluss_fazit', 'closing', 'zur Verfügung stehen; feste Schlussformel.', 'Für Rückfragen {{stehe}} ich Ihnen gerne zur {{Verfügung.}}', array['Für','Rückfragen','stehe','ich','Ihnen','gerne','zur','Verfügung.']::text[], array['stehen','ihnen','Verfügungen']::text[], array['schluss','formell','idiomatisch']::text[], 3, '[{"de":"Für Rückfragen stehe ich Ihnen gerne zur Verfügung. Sie erreichen mich täglich bis 17 Uhr.","en":"I am happy to be available for any questions. You can reach me daily until 5 p.m."},{"de":"Sollte etwas unklar sein: Für Rückfragen stehe ich Ihnen gerne zur Verfügung.","en":"Should anything be unclear: I am happy to be available for any questions."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('6cf94b2d172d', 'Sollten Sie Fragen haben, melden Sie sich gerne.', 'sollten Sie Fragen haben melden Sie sich gerne', 'Should you have any questions, feel free to get in touch.', 'C1', 'schreiben', 'schreiben_a3', 'schluss_fazit', 'closing', 'Konditionalsatz mit vorangestelltem sollten (uneingeleitet).', '{{Sollten}} Sie Fragen haben, {{melden}} Sie sich gerne.', array['Sollten','Sie','Fragen','haben,','melden','Sie','sich','gerne.']::text[], array['Sollte','sie','meldet']::text[], array['schluss','formell','konjunktiv']::text[], 3, '[{"de":"Sollten Sie Fragen haben, melden Sie sich gerne bei mir.","en":"Should you have any questions, feel free to get in touch with me."},{"de":"Sollten Sie Fragen haben, melden Sie sich gerne – ich helfe Ihnen jederzeit weiter.","en":"Should you have any questions, feel free to get in touch – I''ll be glad to help you anytime."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('6ec1bf803319', 'Über eine baldige Rückmeldung würde ich mich freuen.', 'über eine baldige Rückmeldung würde ich mich freuen', 'I would be pleased to receive a prompt reply.', 'C1', 'schreiben', 'schreiben_a3', 'schluss_fazit', 'closing', 'Inversion; sich freuen über + Akkusativ.', 'Über eine {{baldige}} Rückmeldung {{würde}} ich mich freuen.', array['Über','eine','baldige','Rückmeldung','würde','ich','mich','freuen.']::text[], array['Auf','baldigen','freut']::text[], array['schluss','formell']::text[], 3, '[{"de":"Über eine baldige Rückmeldung würde ich mich freuen, da ich bald planen muss.","en":"I would be pleased to receive a prompt reply, as I need to plan soon."},{"de":"Über eine baldige Rückmeldung würde ich mich sehr freuen.","en":"I would be very pleased to receive a prompt reply."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('85c564820fcd', 'Wir bedauern diese Entwicklung sehr.', 'wir bedauern diese Entwicklung sehr', 'We greatly regret this development.', 'C1', 'schreiben', 'schreiben_a3', 'danken_bedauern', 'regret', 'Gehobener Ausdruck des Bedauerns.', 'Wir {{bedauern}} diese {{Entwicklung}} sehr.', array['Wir','bedauern','diese','Entwicklung','sehr.']::text[], array['bedauert','diesen','Entwicklungen']::text[], array['bedauern','formell']::text[], 3, '[{"de":"Wir bedauern diese Entwicklung sehr und arbeiten an einer schnellen Lösung.","en":"We greatly regret this development and are working on a quick solution."},{"de":"Wir bedauern diese Entwicklung sehr, sehen uns aber gezwungen, die Preise anzupassen.","en":"We greatly regret this development but find ourselves forced to adjust the prices."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('85fa2b26a131', 'Ich würde mich über eine Rückmeldung sehr freuen.', 'ich würde mich über eine Rückmeldung sehr freuen', 'I would be very pleased about a reply.', 'C1', 'schreiben', 'schreiben_a3', 'vorschlag_bitte', 'request', 'sich freuen über + Akkusativ; höfliche Bitte um Antwort.', 'Ich {{würde}} mich {{über}} eine Rückmeldung sehr freuen.', array['Ich','würde','mich','über','eine','Rückmeldung','sehr','freuen.']::text[], array['werde','auf','freut']::text[], array['bitte','formell','konjunktiv']::text[], 3, '[{"de":"Ich würde mich über eine Rückmeldung sehr freuen, am besten noch in dieser Woche.","en":"I would be very pleased about a reply, ideally still this week."},{"de":"Über meinen Vorschlag würde ich mich über eine Rückmeldung sehr freuen.","en":"I would be very pleased about a reply regarding my suggestion."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('8fbb558aaece', 'Ich danke Ihnen im Voraus für Ihre Bemühungen.', 'ich danke Ihnen im Voraus für Ihre Bemühungen', 'I thank you in advance for your efforts.', 'C1', 'schreiben', 'schreiben_a3', 'schluss_fazit', 'closing', 'Kombinierte Schlussformel mit Dank.', 'Ich {{danke}} Ihnen im {{Voraus}} für Ihre Bemühungen.', array['Ich','danke','Ihnen','im','Voraus','für','Ihre','Bemühungen.']::text[], array['ihnen','ihre','Bemühung']::text[], array['schluss','formell']::text[], 3, '[{"de":"Ich danke Ihnen im Voraus für Ihre Bemühungen und freue mich auf Ihre Antwort.","en":"I thank you in advance for your efforts and look forward to your reply."},{"de":"Ich danke Ihnen im Voraus für Ihre Bemühungen in dieser Angelegenheit.","en":"I thank you in advance for your efforts in this matter."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('a91963611747', 'Mit großem Interesse habe ich Ihre Anzeige gelesen.', 'mit großem Interesse habe ich Ihre Anzeige gelesen', 'I read your advertisement with great interest.', 'B2', 'schreiben', 'schreiben_a3', 'anliegen', 'opening', 'Inversion mit vorangestellter Adverbiale.', 'Mit {{großem}} Interesse habe ich Ihre Anzeige {{gelesen.}}', array['Mit','großem','Interesse','habe','ich','Ihre','Anzeige','gelesen.']::text[], array['großen','ihre','lesen']::text[], array['anliegen','formell']::text[], 3, '[{"de":"Mit großem Interesse habe ich Ihre Anzeige gelesen und möchte mehr erfahren.","en":"I read your advertisement with great interest and would like to learn more."},{"de":"Mit großem Interesse habe ich Ihre Anzeige für die Stelle gelesen.","en":"I read your advertisement for the position with great interest."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('c3051e36b111', 'Ich wende mich heute mit einem dringenden Anliegen an Sie.', 'ich wende mich heute mit einem dringenden Anliegen an Sie', 'I am contacting you today with an urgent concern.', 'C1', 'schreiben', 'schreiben_a3', 'anliegen', 'opening', 'Gehobene Einleitung; Adjektivdeklination dringenden.', 'Ich {{wende}} mich heute mit einem {{dringenden}} Anliegen an Sie.', array['Ich','wende','mich','heute','mit','einem','dringenden','Anliegen','an','Sie.']::text[], array['wenden','dringendem','sie.']::text[], array['anliegen','formell']::text[], 3, '[{"de":"Ich wende mich heute mit einem dringenden Anliegen an Sie und bitte um schnelle Hilfe.","en":"I am contacting you today with an urgent concern and ask for swift assistance."},{"de":"Ich wende mich heute mit einem dringenden Anliegen an Sie, das keinen Aufschub duldet.","en":"I am contacting you today with an urgent concern that allows no delay."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('d0b37db750b1', 'Ich wäre froh, von Ihnen zu hören.', 'ich wäre froh von Ihnen zu hören', 'I would be glad to hear from you.', 'C1', 'schreiben', 'schreiben_a3', 'schluss_fazit', 'closing', 'Konjunktiv; höfliche Schlussformel.', 'Ich {{wäre}} froh, von {{Ihnen}} zu hören.', array['Ich','wäre','froh,','von','Ihnen','zu','hören.']::text[], array['wären','ihnen','hörte.']::text[], array['schluss','formell','konjunktiv']::text[], 3, '[{"de":"Ich wäre froh, von Ihnen zu hören, sobald eine Entscheidung gefallen ist.","en":"I would be glad to hear from you as soon as a decision has been made."},{"de":"Ich wäre froh, von Ihnen zu hören, ob der Termin noch passt.","en":"I would be glad to hear from you whether the appointment still suits."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('d0be3a011af3', 'Hiermit möchte ich mich für die Stelle bewerben.', 'hiermit möchte ich mich für die Stelle bewerben', 'I would hereby like to apply for the position.', 'B2', 'schreiben', 'schreiben_a3', 'anliegen', 'opening', 'sich bewerben für/um; hiermit als formeller Marker.', '{{Hiermit}} möchte ich mich für die {{Stelle}} bewerben.', array['Hiermit','möchte','ich','mich','für','die','Stelle','bewerben.']::text[], array['Hier','um','bewirbt']::text[], array['anliegen','formell']::text[], 3, '[{"de":"Hiermit möchte ich mich für die Stelle als Verkäufer bewerben.","en":"I would hereby like to apply for the position as a salesperson."},{"de":"Hiermit möchte ich mich für die ausgeschriebene Stelle bewerben.","en":"I would hereby like to apply for the advertised position."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('d0d5354f03a6', 'Dürfte ich Sie um Ihre Einschätzung bitten?', 'dürfte ich Sie um Ihre Einschätzung bitten', 'Might I ask you for your assessment?', 'C1', 'schreiben', 'schreiben_a3', 'vorschlag_bitte', 'request', 'Dürfte ich als sehr höfliche Bitte.', '{{Dürfte}} ich Sie {{um}} Ihre Einschätzung bitten?', array['Dürfte','ich','Sie','um','Ihre','Einschätzung','bitten?']::text[], array['Darf','sie','Einschätzungen']::text[], array['bitte','formell','konjunktiv']::text[], 3, '[{"de":"Dürfte ich Sie um Ihre Einschätzung bitten, ob dieser Plan realistisch ist?","en":"Might I ask you for your assessment of whether this plan is realistic?"},{"de":"Bevor ich entscheide, dürfte ich Sie um Ihre Einschätzung bitten?","en":"Before I decide, might I ask you for your assessment?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('e9af3c98aa98', 'Ich entschuldige mich für mein spätes Antworten.', 'ich entschuldige mich für mein spätes Antworten', 'I apologize for my late reply.', 'B2', 'schreiben', 'schreiben_a3', 'absagen_entschuldigen', 'apology', 'sich entschuldigen für; substantivierter Infinitiv Antworten.', 'Ich {{entschuldige}} mich für mein {{spätes}} Antworten.', array['Ich','entschuldige','mich','für','mein','spätes','Antworten.']::text[], array['entschuldigt','meinem','späten']::text[], array['entschuldigen','formell']::text[], 3, '[{"de":"Ich entschuldige mich für mein spätes Antworten; ich war im Urlaub.","en":"I apologize for my late reply; I was on holiday."},{"de":"Ich entschuldige mich für mein spätes Antworten und komme gleich zur Sache.","en":"I apologize for my late reply and will get straight to the point."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('f43d8a576604', 'Ich wäre Ihnen für eine baldige Antwort dankbar.', 'ich wäre Ihnen für eine baldige Antwort dankbar', 'I would be grateful to you for a prompt reply.', 'C1', 'schreiben', 'schreiben_a3', 'vorschlag_bitte', 'request', 'jdm. dankbar sein; Adjektivdeklination baldige.', 'Ich {{wäre}} Ihnen für eine {{baldige}} Antwort dankbar.', array['Ich','wäre','Ihnen','für','eine','baldige','Antwort','dankbar.']::text[], array['wären','ihnen','baldigen']::text[], array['bitte','formell','konjunktiv']::text[], 3, '[{"de":"Ich wäre Ihnen für eine baldige Antwort dankbar, da die Anmeldefrist bald endet.","en":"I would be grateful to you for a prompt reply, as the registration deadline ends soon."},{"de":"Für eine baldige Antwort wäre ich Ihnen sehr dankbar.","en":"I would be very grateful to you for a prompt reply."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('178824a8e467', 'Ich wäre Ihnen sehr verbunden, wenn Sie mir antworten könnten.', 'ich wäre Ihnen sehr verbunden wenn Sie mir antworten könnten', 'I would be much obliged if you could reply to me.', 'C2', 'schreiben', 'schreiben_a3', 'vorschlag_bitte', 'request', 'jdm. verbunden sein; sehr gehobene Höflichkeit.', 'Ich {{wäre}} Ihnen sehr {{verbunden,}} wenn Sie mir antworten könnten.', array['Ich','wäre','Ihnen','sehr','verbunden,','wenn','Sie','mir','antworten','könnten.']::text[], array['wären','sie','gekonnt.']::text[], array['bitte','formell','idiomatisch']::text[], 4, '[{"de":"Ich wäre Ihnen sehr verbunden, wenn Sie mir bis Ende der Woche antworten könnten.","en":"I would be much obliged if you could reply to me by the end of the week."},{"de":"Ich wäre Ihnen sehr verbunden, wenn Sie mir die nötigen Informationen zukommen lassen könnten.","en":"I would be much obliged if you could let me have the necessary information."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('209de10403ce', 'Es ist uns ein großes Anliegen, uns bei Ihnen zu bedanken.', 'es ist uns ein großes Anliegen uns bei Ihnen zu bedanken', 'It is very important to us to thank you.', 'C2', 'schreiben', 'schreiben_a3', 'danken_bedauern', 'thanks', 'jdm. ein Anliegen sein; sich bedanken bei.', 'Es ist uns ein {{großes}} Anliegen, uns bei Ihnen zu {{bedanken.}}', array['Es','ist','uns','ein','großes','Anliegen,','uns','bei','Ihnen','zu','bedanken.']::text[], array['ihnen','großem','bedankt']::text[], array['danken','formell','idiomatisch']::text[], 4, '[{"de":"Es ist uns ein großes Anliegen, uns bei Ihnen zu bedanken, denn ohne Ihre Unterstützung wäre das Projekt nicht möglich gewesen.","en":"It is very important to us to thank you, because without your support the project would not have been possible."},{"de":"Bevor wir zum eigentlichen Punkt kommen, ist es uns ein großes Anliegen, uns bei Ihnen zu bedanken.","en":"Before we get to the actual point, it is very important to us to thank you."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('a99dd67e081b', 'Ich sehe der Veranstaltung mit Freude entgegen.', 'ich sehe der Veranstaltung mit Freude entgegen', 'I look forward to the event with pleasure.', 'C2', 'schreiben', 'schreiben_a3', 'schluss_fazit', 'closing', 'einer Sache entgegensehen + Dativ; sehr gehoben.', 'Ich {{sehe}} der {{Veranstaltung}} mit Freude entgegen.', array['Ich','sehe','der','Veranstaltung','mit','Freude','entgegen.']::text[], array['sehen','die','entgegensehe']::text[], array['schluss','formell','idiomatisch']::text[], 4, '[{"de":"Ich sehe der Veranstaltung mit Freude entgegen und habe mich bereits angemeldet.","en":"I look forward to the event with pleasure and have already registered."},{"de":"Ich sehe der Veranstaltung mit großer Freude entgegen.","en":"I look forward to the event with great pleasure."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('b8317fc186bc', 'Ich möchte Ihnen meinen aufrichtigen Dank aussprechen.', 'ich möchte Ihnen meinen aufrichtigen Dank aussprechen', 'I would like to express my sincere thanks to you.', 'C2', 'schreiben', 'schreiben_a3', 'danken_bedauern', 'thanks', 'Dank aussprechen; sehr formell.', 'Ich {{möchte}} Ihnen meinen {{aufrichtigen}} Dank aussprechen.', array['Ich','möchte','Ihnen','meinen','aufrichtigen','Dank','aussprechen.']::text[], array['ihnen','aufrichtigem','ausspricht']::text[], array['danken','formell','idiomatisch']::text[], 4, '[{"de":"Ich möchte Ihnen meinen aufrichtigen Dank aussprechen für die hervorragende Betreuung während des Praktikums.","en":"I would like to express my sincere thanks to you for the excellent supervision during the internship."},{"de":"Im Namen des gesamten Teams möchte ich Ihnen meinen aufrichtigen Dank aussprechen.","en":"On behalf of the entire team, I would like to express my sincere thanks to you."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('c5955a4b334f', 'Leider sehe ich mich außerstande, Ihrer Bitte nachzukommen.', 'leider sehe ich mich außerstande Ihrer Bitte nachzukommen', 'Unfortunately, I am unable to comply with your request.', 'C2', 'schreiben', 'schreiben_a3', 'absagen_entschuldigen', 'declining', 'sich außerstande sehen; nachkommen + Dativ. Sehr formell.', 'Leider {{sehe}} ich mich {{außerstande,}} Ihrer Bitte nachzukommen.', array['Leider','sehe','ich','mich','außerstande,','Ihrer','Bitte','nachzukommen.']::text[], array['sehen','ihrer','nachkommen']::text[], array['absagen','formell','idiomatisch']::text[], 4, '[{"de":"Leider sehe ich mich außerstande, Ihrer Bitte nachzukommen, da uns die Mittel fehlen.","en":"Unfortunately, I am unable to comply with your request, as we lack the resources."},{"de":"Aus rechtlichen Gründen sehe ich mich leider außerstande, Ihrer Bitte nachzukommen.","en":"For legal reasons, I am unfortunately unable to comply with your request."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('c68fc6acf34c', 'Für Ihr Entgegenkommen wäre ich Ihnen sehr verbunden.', 'für Ihr Entgegenkommen wäre ich Ihnen sehr verbunden', 'I would be much obliged for your cooperation.', 'C2', 'schreiben', 'schreiben_a3', 'schluss_fazit', 'closing', 'Entgegenkommen; jdm. verbunden sein. Sehr gehoben.', 'Für Ihr {{Entgegenkommen}} {{wäre}} ich Ihnen sehr verbunden.', array['Für','Ihr','Entgegenkommen','wäre','ich','Ihnen','sehr','verbunden.']::text[], array['ihr','ihnen','verbunden,']::text[], array['schluss','formell','idiomatisch']::text[], 4, '[{"de":"Für Ihr Entgegenkommen wäre ich Ihnen sehr verbunden, falls Sie die Frist verlängern könnten.","en":"I would be much obliged for your accommodation if you could extend the deadline."},{"de":"Für Ihr Entgegenkommen in dieser Sache wäre ich Ihnen sehr verbunden.","en":"I would be much obliged for your accommodation in this matter."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('f809b84ad485', 'Bezugnehmend auf Ihr Schreiben möchte ich Folgendes mitteilen.', 'bezugnehmend auf Ihr Schreiben möchte ich Folgendes mitteilen', 'With reference to your letter, I would like to state the following.', 'C1', 'schreiben', 'schreiben_a3', 'anliegen', 'opening', 'Sehr formelle Bezugnahme; Folgendes großgeschrieben.', '{{Bezugnehmend}} auf Ihr Schreiben möchte ich {{Folgendes}} mitteilen.', array['Bezugnehmend','auf','Ihr','Schreiben','möchte','ich','Folgendes','mitteilen.']::text[], array['Bezug','ihr','folgendes']::text[], array['anliegen','formell','idiomatisch']::text[], 4, '[{"de":"Bezugnehmend auf Ihr Schreiben möchte ich Folgendes mitteilen: Der Termin passt mir.","en":"With reference to your letter, I would like to state the following: the appointment suits me."},{"de":"Bezugnehmend auf Ihr Schreiben vom 3. Mai möchte ich Folgendes mitteilen.","en":"With reference to your letter of 3 May, I would like to state the following."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('fd29761b9760', 'Ich erlaube mir, mich mit einer Bitte an Sie zu wenden.', 'ich erlaube mir mich mit einer Bitte an Sie zu wenden', 'I take the liberty of approaching you with a request.', 'C2', 'schreiben', 'schreiben_a3', 'anliegen', 'opening', 'Sehr gehobene Höflichkeitsfloskel.', 'Ich {{erlaube}} mir, mich mit einer {{Bitte}} an Sie zu wenden.', array['Ich','erlaube','mir,','mich','mit','einer','Bitte','an','Sie','zu','wenden.']::text[], array['erlauben','sie','wendet']::text[], array['anliegen','formell','idiomatisch']::text[], 4, '[{"de":"Sehr geehrte Frau Berger, ich erlaube mir, mich mit einer Bitte an Sie zu wenden: Ich suche einen freien Termin für ein Beratungsgespräch.","en":"Dear Ms. Berger, I take the liberty of approaching you with a request: I am looking for an available appointment for a consultation."},{"de":"Ich erlaube mir, mich mit einer Bitte an Sie zu wenden, da Sie auf diesem Gebiet als Expertin gelten.","en":"I take the liberty of approaching you with a request, as you are regarded as an expert in this field."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('4129a33526d4', 'Treffen wir uns also um drei.', 'treffen wir uns um …', 'So let''s meet at three.', 'B1', 'sprechen', 'sprechen_t1', 'sich_einigen', 'agreement', 'Konkrete Uhrzeit als Einigung.', 'Treffen wir {{uns}} also um drei.', array['Treffen','wir','uns','also','um','drei.']::text[], array['trefft','uns,','drei,']::text[], array['einigung']::text[], 1, '[{"de":"Gut, treffen wir uns also um drei vor dem Eingang.","en":"Okay, so let''s meet at three in front of the entrance."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('5a386cdfd227', 'Gut, dann machen wir es so.', 'dann machen wir es so', 'Okay, then let''s do it that way.', 'B1', 'sprechen', 'sprechen_t1', 'sich_einigen', 'agreement', 'Einfacher Abschluss einer Einigung.', 'Gut, dann {{machen}} wir es so.', array['Gut,','dann','machen','wir','es','so.']::text[], array['macht','wird','das']::text[], array['einigung']::text[], 1, '[{"de":"Alles klar, dann machen wir es so und melden uns morgen.","en":"All right, then let''s do it that way and get in touch tomorrow."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('5a9ab156f689', 'Genau, so sehe ich das auch.', 'so sehe ich das auch', 'Exactly, that''s how I see it too.', 'B1', 'sprechen', 'sprechen_t1', 'zustimmen', 'agreement', 'Kurze, lebendige Zustimmung im Gespräch.', 'Genau, so {{sehe}} ich das auch.', array['Genau,','so','sehe','ich','das','auch.']::text[], array['sehen','dass','nicht']::text[], array['zustimmung']::text[], 1, '[{"de":"Genau, so sehe ich das auch, das passt für mich.","en":"Exactly, that''s how I see it too, that works for me."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('69d7f07b70fb', 'Okay, das passt mir gut.', 'das passt mir gut', 'Okay, that works well for me.', 'B1', 'sprechen', 'sprechen_t1', 'zustimmen', 'agreement', 'passen + Dativ: Zustimmung zum Termin.', 'Okay, das {{passt}} mir gut.', array['Okay,','das','passt','mir','gut.']::text[], array['passen','mich','gut,']::text[], array['zustimmung']::text[], 1, '[{"de":"Drei Uhr? Okay, das passt mir gut.","en":"Three o''clock? Okay, that works well for me."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('a42973e19bdd', 'Ja, das finde ich auch eine gute Idee.', 'das finde ich auch …', 'Yes, I think that''s a good idea too.', 'B1', 'sprechen', 'sprechen_t1', 'zustimmen', 'agreement', 'Einfache, freundliche Zustimmung.', 'Ja, das {{finde}} ich auch eine gute Idee.', array['Ja,','das','finde','ich','auch','eine','gute','Idee.']::text[], array['denke','sehr','schlecht']::text[], array['zustimmung']::text[], 1, '[{"de":"Ja, das finde ich auch eine gute Idee, lass uns das machen.","en":"Yes, I think that''s a good idea too, let''s do that."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('a601a2ad84ea', 'Sollen wir uns morgen treffen?', 'sollen wir uns … treffen?', 'Should we meet tomorrow?', 'B1', 'sprechen', 'sprechen_t1', 'vorschlag_bitte', 'suggestion', 'Einfacher Vorschlag mit sollen.', 'Sollen wir uns morgen {{treffen}}?', array['Sollen','wir','uns','morgen','treffen?']::text[], array['wollen','uns,','getroffen']::text[], array['vorschlag']::text[], 1, '[{"de":"Sollen wir uns morgen treffen und alles in Ruhe besprechen?","en":"Should we meet tomorrow and discuss everything calmly?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('d974270bd8bd', 'Das stimmt, aber wir haben wenig Zeit.', 'das stimmt, aber …', 'That''s true, but we have little time.', 'B1', 'sprechen', 'sprechen_t1', 'abwaegen', 'concern', 'Höfliches Einräumen mit anschließendem Einwand.', 'Das {{stimmt}}, aber wir haben wenig Zeit.', array['Das','stimmt,','aber','wir','haben','wenig','Zeit.']::text[], array['stimmen','oder','viel']::text[], array['einwand','abwaegen']::text[], 1, '[{"de":"Das stimmt, aber wir haben wenig Zeit, oder?","en":"That''s true, but we don''t have much time, do we?"},{"de":"Das stimmt, aber dann müssen wir das morgen früh machen.","en":"That''s true, but then we''ll have to do it tomorrow morning."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('e1b3119d2464', 'Wir könnten zuerst die Kosten besprechen.', 'wir könnten zuerst …', 'We could discuss the costs first.', 'B1', 'sprechen', 'sprechen_t1', 'vorschlag_bitte', 'suggestion', 'könnten signalisiert einen unverbindlichen Vorschlag.', 'Wir {{könnten}} zuerst die Kosten besprechen.', array['Wir','könnten','zuerst','die','Kosten','besprechen.']::text[], array['müssen','besprochen','kann']::text[], array['vorschlag','konjunktiv']::text[], 1, '[{"de":"Wir könnten zuerst die Kosten besprechen und danach die Termine.","en":"We could discuss the costs first and the dates afterwards."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('020d2acf08f7', 'Einerseits ist das günstig, andererseits dauert es lange.', 'einerseits …, andererseits …', 'On the one hand it''s cheap, on the other it takes a long time.', 'B2', 'sprechen', 'sprechen_t1', 'abwaegen', 'concern', 'Klassische Abwägung mit einerseits/andererseits.', 'Einerseits ist das günstig, {{andererseits}} dauert es lange.', array['Einerseits','ist','das','günstig,','andererseits','dauert','es','lange.']::text[], array['einseits','aber','kurz']::text[], array['abwaegen']::text[], 2, '[{"de":"Einerseits ist das Angebot günstig, andererseits dauert die Lieferung sehr lange.","en":"On the one hand the offer is cheap, on the other the delivery takes a very long time."},{"de":"Einerseits könnten wir das Café nehmen, andererseits ist es dort oft sehr laut.","en":"On the one hand we could take the café, on the other it''s often very loud there."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('0b63681667ae', 'Dann sind wir uns ja einig.', 'dann sind wir uns einig', 'Then we''re in agreement.', 'B1', 'sprechen', 'sprechen_t1', 'sich_einigen', 'agreement', 'sich einig sein: feste Wendung.', 'Dann sind wir uns ja {{einig}}.', array['Dann','sind','wir','uns','ja','einig.']::text[], array['seid','uns,','einigen']::text[], array['einigung','idiom']::text[], 2, '[{"de":"Super, dann sind wir uns ja einig und können loslegen.","en":"Great, then we''re in agreement and can get started."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('17161d4695a6', 'Ich schlage vor, dass wir uns das Programm teilen.', 'ich schlage vor, dass …', 'I suggest that we split up the program.', 'B1', 'sprechen', 'sprechen_t1', 'vorschlag_bitte', 'suggestion', 'Trennbares Verb: vorschlagen.', 'Ich schlage {{vor}}, dass wir uns das Programm teilen.', array['Ich','schlage','vor,','dass','wir','uns','das','Programm','teilen.']::text[], array['vorschlagen','ob','wird']::text[], array['vorschlag']::text[], 2, '[{"de":"Ich schlage vor, dass wir erst die Aufgaben und dann die Zeiten besprechen.","en":"I suggest that we first discuss the tasks and then the times."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('17b35ee579a9', 'Ich würde vorschlagen, dass wir uns am Freitag treffen.', 'ich würde vorschlagen, dass …', 'I would suggest that we meet on Friday.', 'B2', 'sprechen', 'sprechen_t1', 'vorschlag_bitte', 'suggestion', 'Besonders höflicher Vorschlag mit würde + Konjunktiv II.', 'Ich würde {{vorschlagen}}, dass wir uns am Freitag treffen.', array['Ich','würde','vorschlagen,','dass','wir','uns','am','Freitag','treffen.']::text[], array['das','wird','vorgeschlagen']::text[], array['vorschlag','konjunktiv']::text[], 2, '[{"de":"Ich würde vorschlagen, dass wir das vorher kurz testen.","en":"I would suggest that we test it briefly beforehand."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('3b652ec58b53', 'Lass uns das gemeinsam aufteilen.', 'lass uns das aufteilen', 'Let''s split this up together.', 'B2', 'sprechen', 'sprechen_t1', 'sich_einigen', 'agreement', 'lass uns + Infinitiv: kooperativer Vorschlag zur Einigung.', 'Lass uns das gemeinsam {{aufteilen}}.', array['Lass','uns','das','gemeinsam','aufteilen.']::text[], array['lassen','uns,','aufgeteilt']::text[], array['einigung']::text[], 2, '[{"de":"Es ist viel Arbeit, lass uns das gemeinsam aufteilen.","en":"It''s a lot of work, let''s split it up together."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
