insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('9ddd217a7935', 'Was hältst du davon, am Abend zu üben?', 'was hältst du davon, … zu …?', 'What do you think about practicing in the evening?', 'B1', 'sprechen', 'sprechen_t1', 'vorschlag_bitte', 'suggestion', 'Idiomatische Wendung: etwas von etwas halten.', 'Was {{hältst}} du davon, am Abend zu üben?', array['Was','hältst','du','davon,','am','Abend','zu','üben?']::text[], array['denkst','über','macht']::text[], array['vorschlag','meinung']::text[], 2, '[{"de":"Was hältst du davon, wenn wir uns die Arbeit teilen?","en":"What do you think about us sharing the work?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('a1a301e8330c', 'Ich frage mich, ob das wirklich nötig ist.', 'ich frage mich, ob …', 'I wonder whether that''s really necessary.', 'B2', 'sprechen', 'sprechen_t1', 'abwaegen', 'concern', 'sich fragen, ob …: Zweifel höflich äußern.', 'Ich {{frage}} mich, ob das wirklich nötig ist.', array['Ich','frage','mich,','ob','das','wirklich','nötig','ist.']::text[], array['fragen','dass','nötig,']::text[], array['abwaegen']::text[], 2, '[{"de":"Ich frage mich, ob das wirklich nötig ist – vielleicht reicht ja eine einfachere Lösung.","en":"I wonder whether that''s really necessary – maybe a simpler solution is enough."},{"de":"Ich frage mich, ob wir dafür überhaupt genug Zeit haben.","en":"I wonder whether we even have enough time for that."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('aed2076afe28', 'Ich bin nicht ganz sicher, ob das reicht.', 'ich bin nicht sicher, ob …', 'I''m not entirely sure whether that''s enough.', 'B1', 'sprechen', 'sprechen_t1', 'abwaegen', 'concern', 'Vorsichtiger Zweifel mit ob-Satz.', 'Ich bin nicht ganz {{sicher}}, ob das reicht.', array['Ich','bin','nicht','ganz','sicher,','ob','das','reicht.']::text[], array['sind','dass','gereicht']::text[], array['abwaegen']::text[], 2, '[{"de":"Ich bin nicht ganz sicher, ob das Budget dafür reicht.","en":"I''m not entirely sure whether the budget is enough for that."},{"de":"Ich bin nicht ganz sicher, ob wir das bis Freitag schaffen.","en":"I''m not entirely sure whether we''ll manage that by Friday."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('dcdab684ad02', 'Dem kann ich nur zustimmen.', 'dem kann ich nur zustimmen', 'I can only agree with that.', 'B2', 'sprechen', 'sprechen_t1', 'zustimmen', 'agreement', 'zustimmen + Dativ (dem). Betonte Zustimmung.', 'Dem kann ich nur {{zustimmen}}.', array['Dem','kann','ich','nur','zustimmen.']::text[], array['das','zugestimmt','muss']::text[], array['zustimmung']::text[], 2, '[{"de":"Du hast völlig recht, dem kann ich nur zustimmen.","en":"You''re absolutely right, I can only agree with that."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('e1a810c825c3', 'Ich sehe da allerdings ein kleines Problem.', 'ich sehe da ein Problem', 'I do see a small problem there, though.', 'B2', 'sprechen', 'sprechen_t1', 'abwaegen', 'concern', 'allerdings schwächt höflich ab und leitet einen Einwand ein.', 'Ich sehe da {{allerdings}} ein kleines Problem.', array['Ich','sehe','da','allerdings','ein','kleines','Problem.']::text[], array['sehen','den','großes']::text[], array['einwand','abwaegen']::text[], 2, '[{"de":"Ich sehe da allerdings ein kleines Problem: Am Freitag kann ich nicht.","en":"I do see a small problem there, though: I can''t make it on Friday."},{"de":"Klingt gut, ich sehe da allerdings ein kleines Problem mit den Kosten.","en":"Sounds good, though I do see a small problem with the costs."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('e51944f7486f', 'Vielleicht sollten wir die Aufgaben gleich verteilen.', 'vielleicht sollten wir …', 'Maybe we should divide up the tasks right away.', 'B2', 'sprechen', 'sprechen_t1', 'vorschlag_bitte', 'suggestion', 'sollten + vielleicht klingt vorsichtig und kooperativ.', 'Vielleicht {{sollten}} wir die Aufgaben gleich verteilen.', array['Vielleicht','sollten','wir','die','Aufgaben','gleich','verteilen.']::text[], array['wollen','verteilt','kann']::text[], array['vorschlag','konjunktiv']::text[], 2, '[{"de":"Vielleicht sollten wir die Aufgaben gleich verteilen, sonst vergessen wir es.","en":"Maybe we should divide up the tasks right away, otherwise we''ll forget."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('ed3a5896264e', 'Wir sollten aber bedenken, dass das Geld kostet.', 'wir sollten bedenken, dass …', 'But we should keep in mind that this costs money.', 'B2', 'sprechen', 'sprechen_t1', 'abwaegen', 'concern', 'bedenken, dass … zur Einleitung von Bedenken.', 'Wir sollten aber {{bedenken}}, dass das Geld kostet.', array['Wir','sollten','aber','bedenken,','dass','das','Geld','kostet.']::text[], array['bedacht','ob','wird']::text[], array['abwaegen','bedenken']::text[], 2, '[{"de":"Die Idee ist toll, wir sollten aber bedenken, dass nicht alle Zeit haben.","en":"The idea is great, but we should keep in mind that not everyone has time."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('f54468b01ded', 'Da bin ich ganz deiner Meinung.', 'da bin ich deiner Meinung', 'I completely agree with you there.', 'B1', 'sprechen', 'sprechen_t1', 'zustimmen', 'agreement', 'Feste Wendung zur Zustimmung.', 'Da bin ich ganz deiner {{Meinung}}.', array['Da','bin','ich','ganz','deiner','Meinung.']::text[], array['meiner','Meinungen','hast']::text[], array['zustimmung','idiom']::text[], 2, '[{"de":"Da bin ich ganz deiner Meinung, das machen wir genau so.","en":"I completely agree with you there, we''ll do it exactly like that."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('0715bcc9e40f', 'Damit hätten wir einen tragfähigen Kompromiss gefunden.', 'damit hätten wir einen Kompromiss gefunden', 'With that we''d have found a workable compromise.', 'C1', 'sprechen', 'sprechen_t1', 'sich_einigen', 'agreement', 'tragfähig: gehoben für ''belastbar, dauerhaft''.', 'Damit {{hätten}} wir einen tragfähigen Kompromiss gefunden.', array['Damit','hätten','wir','einen','tragfähigen','Kompromiss','gefunden.']::text[], array['haben','einem','finden']::text[], array['einigung','kompromiss']::text[], 3, '[{"de":"Gut, damit hätten wir einen tragfähigen Kompromiss gefunden, mit dem alle leben können.","en":"Good, with that we''d have found a workable compromise that everyone can live with."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('212ae8d7f461', 'Das hat allerdings den Nachteil, dass es teurer wird.', 'das hat den Nachteil, dass …', 'That does have the disadvantage of becoming more expensive.', 'C1', 'sprechen', 'sprechen_t1', 'abwaegen', 'concern', 'Vor- und Nachteile sachlich gegenüberstellen.', 'Das hat allerdings den {{Nachteil}}, dass es teurer wird.', array['Das','hat','allerdings','den','Nachteil,','dass','es','teurer','wird.']::text[], array['Vorteil','ob','teuer']::text[], array['abwaegen']::text[], 3, '[{"de":"Das hat allerdings den Nachteil, dass es deutlich teurer wird.","en":"That does have the disadvantage, however, of becoming considerably more expensive."},{"de":"Wir könnten am Samstag fahren – das hat allerdings den Nachteil, dass die Züge voll sind.","en":"We could travel on Saturday – that does have the disadvantage, though, that the trains are crowded."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('364cde2a7509', 'Dieser Einschätzung schließe ich mich an.', 'dieser Einschätzung schließe ich mich an', 'I align myself with that assessment.', 'C1', 'sprechen', 'sprechen_t1', 'zustimmen', 'agreement', 'sich einer Sache anschließen (Dativ).', 'Dieser Einschätzung schließe ich mich {{an}}.', array['Dieser','Einschätzung','schließe','ich','mich','an.']::text[], array['diese','mir','ein']::text[], array['zustimmung','formell']::text[], 3, '[{"de":"Dieser Einschätzung schließe ich mich an, das sehe ich genauso.","en":"I align myself with that assessment, I see it exactly the same way."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('42615db0bab2', 'An dieser Stelle würde ich folgendes Vorgehen vorschlagen.', 'ich würde folgendes Vorgehen vorschlagen', 'At this point I would propose the following approach.', 'C1', 'sprechen', 'sprechen_t1', 'vorschlag_bitte', 'suggestion', 'Gehobene Formulierung für strukturierte Planung.', 'An dieser Stelle {{würde}} ich folgendes Vorgehen vorschlagen.', array['An','dieser','Stelle','würde','ich','folgendes','Vorgehen','vorschlagen.']::text[], array['dieses','vorgeschlagen','wird']::text[], array['vorschlag','formell']::text[], 3, '[{"de":"An dieser Stelle würde ich folgendes Vorgehen vorschlagen: erst sammeln, dann auswählen.","en":"At this point I would propose the following approach: first collect, then select."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('4de5143c1a4f', 'Ich hätte da einen Vorschlag zur Verteilung der Aufgaben.', 'ich hätte da einen Vorschlag zu …', 'I have a suggestion regarding the distribution of tasks.', 'B2', 'sprechen', 'sprechen_t1', 'vorschlag_bitte', 'suggestion', 'hätte da einen Vorschlag wirkt zugleich höflich und konkret.', 'Ich {{hätte}} da einen Vorschlag zur Verteilung der Aufgaben.', array['Ich','hätte','da','einen','Vorschlag','zur','Verteilung','der','Aufgaben.']::text[], array['habe','mit','Vorschläge']::text[], array['vorschlag','konjunktiv']::text[], 3, '[{"de":"Ich hätte da einen Vorschlag zur Verteilung der Kosten, wenn ich darf.","en":"I have a suggestion regarding the distribution of costs, if I may."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('7c87659fd653', 'Da gehe ich völlig mit dir konform.', 'da gehe ich mit dir konform', 'I''m completely in agreement with you there.', 'C1', 'sprechen', 'sprechen_t1', 'zustimmen', 'agreement', 'mit jemandem konform gehen: gehobene Zustimmung.', 'Da gehe ich völlig mit dir {{konform}}.', array['Da','gehe','ich','völlig','mit','dir','konform.']::text[], array['gehst','dich','konkret']::text[], array['zustimmung','formell']::text[], 3, '[{"de":"Was die Kosten angeht, da gehe ich völlig mit dir konform.","en":"As far as the costs go, I''m completely in agreement with you there."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('8f014feb3bf9', 'Dann halten wir als Kompromiss die Mitte fest.', 'dann halten wir … fest', 'Then let''s put down the middle ground as a compromise.', 'C1', 'sprechen', 'sprechen_t1', 'sich_einigen', 'agreement', 'etwas festhalten (trennbar): ein Ergebnis festschreiben.', 'Dann halten wir als Kompromiss die Mitte {{fest}}.', array['Dann','halten','wir','als','Kompromiss','die','Mitte','fest.']::text[], array['festhalten','Kompromisse','auf']::text[], array['einigung','kompromiss']::text[], 3, '[{"de":"Gut, dann halten wir als Kompromiss die Mitte fest und gehen weiter.","en":"Good, then let''s settle on the middle ground as a compromise and move on."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('9d9b2906bc3f', 'Das leuchtet mir ein, machen wir es so.', 'das leuchtet mir ein', 'That makes sense to me, let''s do it that way.', 'B2', 'sprechen', 'sprechen_t1', 'zustimmen', 'agreement', 'jemandem leuchtet etwas ein: idiomatisch für überzeugen.', 'Das {{leuchtet}} mir ein, machen wir es so.', array['Das','leuchtet','mir','ein,','machen','wir','es','so.']::text[], array['leuchten','mich','ein,']::text[], array['zustimmung','idiom']::text[], 3, '[{"de":"Das leuchtet mir ein, dann sparen wir wirklich Zeit.","en":"That makes sense to me, then we really do save time."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('b98fe8c5d200', 'Man müsste abwägen, ob sich der Aufwand wirklich lohnt.', 'man müsste abwägen, ob …', 'One would have to weigh up whether the effort is really worth it.', 'C1', 'sprechen', 'sprechen_t1', 'abwaegen', 'concern', 'müsste + abwägen, ob …: distanziert-reflektierend.', 'Man müsste {{abwägen}}, ob sich der Aufwand wirklich lohnt.', array['Man','müsste','abwägen,','ob','sich','der','Aufwand','wirklich','lohnt.']::text[], array['muss','dass','abgewogen']::text[], array['abwaegen','konjunktiv']::text[], 3, '[{"de":"Bevor wir das buchen, müsste man abwägen, ob sich der Aufwand wirklich lohnt.","en":"Before we book that, one would have to weigh up whether the effort is really worth it."},{"de":"Man müsste abwägen, ob wir das Geld nicht besser woanders einsetzen.","en":"One would have to weigh up whether we couldn''t use the money better elsewhere."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('d651f07837b6', 'Dürfte ich einen alternativen Vorschlag einbringen?', 'dürfte ich … einbringen?', 'Might I put forward an alternative suggestion?', 'C1', 'sprechen', 'sprechen_t1', 'vorschlag_bitte', 'suggestion', 'dürfte ich … signalisiert besonders höfliche Distanz.', '{{Dürfte}} ich einen alternativen Vorschlag einbringen?', array['Dürfte','ich','einen','alternativen','Vorschlag','einbringen?']::text[], array['darf','einbringt','bringen']::text[], array['vorschlag','konjunktiv','formell']::text[], 3, '[{"de":"Bevor wir entscheiden, dürfte ich einen alternativen Vorschlag einbringen?","en":"Before we decide, might I put forward an alternative suggestion?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('da7306fa2fb0', 'Im Prinzip stimme ich zu, hätte aber eine Anmerkung.', 'im Prinzip stimme ich zu, hätte aber …', 'In principle I agree, but I''d have one remark.', 'C1', 'sprechen', 'sprechen_t1', 'zustimmen', 'agreement', 'Teilzustimmung mit höflichem Vorbehalt.', 'Im Prinzip {{stimme}} ich zu, hätte aber eine Anmerkung.', array['Im','Prinzip','stimme','ich','zu,','hätte','aber','eine','Anmerkung.']::text[], array['stimmt','habe','Anmerkungen']::text[], array['zustimmung','abwaegen']::text[], 3, '[{"de":"Im Prinzip stimme ich zu, hätte aber eine Anmerkung zum Zeitplan.","en":"In principle I agree, but I''d have one remark about the schedule."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('260fa132daa0', 'Letztlich liefe es auf einen Kompromiss hinaus.', 'letztlich liefe es auf … hinaus', 'Ultimately it would come down to a compromise.', 'C2', 'sprechen', 'sprechen_t1', 'sich_einigen', 'agreement', 'auf etwas hinauslaufen, hier im Konjunktiv II (liefe).', 'Letztlich {{liefe}} es auf einen Kompromiss hinaus.', array['Letztlich','liefe','es','auf','einen','Kompromiss','hinaus.']::text[], array['läuft','einem','hinausgelaufen']::text[], array['einigung','konjunktiv']::text[], 4, '[{"de":"Wenn wir beide nicht nachgeben, liefe es letztlich auf einen Kompromiss hinaus.","en":"If neither of us gives in, it would ultimately come down to a compromise."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('3ba7838fa52f', 'So verlockend das klingt, praktikabel ist es kaum.', 'so … das klingt, … ist es kaum', 'As tempting as that sounds, it''s hardly practical.', 'C2', 'sprechen', 'sprechen_t1', 'abwaegen', 'concern', 'Konzessive ''so … das auch …''-Konstruktion, hier verkürzt.', 'So {{verlockend}} das klingt, praktikabel ist es kaum.', array['So','verlockend','das','klingt,','praktikabel','ist','es','kaum.']::text[], array['wie','sehr','klingen']::text[], array['abwaegen','konzessiv']::text[], 4, '[{"de":"So verlockend das klingt, praktikabel ist es kaum – wir hätten kaum Zeit dafür.","en":"As tempting as that sounds, it''s hardly practical – we''d barely have time for it."},{"de":"So verlockend der Plan auch klingt, bezahlbar ist er für uns kaum.","en":"As tempting as the plan sounds, it''s hardly affordable for us."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('4ef373021ec3', 'Bei aller Begeisterung sollten wir die Risiken nicht unterschätzen.', 'bei aller Begeisterung sollten wir …', 'For all our enthusiasm, we shouldn''t underestimate the risks.', 'C2', 'sprechen', 'sprechen_t1', 'abwaegen', 'concern', 'Gehobene Wendung ''bei aller …'' relativiert höflich.', 'Bei aller Begeisterung sollten wir die Risiken nicht {{unterschätzen}}.', array['Bei','aller','Begeisterung','sollten','wir','die','Risiken','nicht','unterschätzen.']::text[], array['allen','wird','überschätzen']::text[], array['abwaegen','formell']::text[], 4, '[{"de":"Bei aller Begeisterung sollten wir die Risiken nicht unterschätzen und einen Plan B haben.","en":"For all our enthusiasm, we shouldn''t underestimate the risks and should have a plan B."},{"de":"Bei aller Begeisterung für die Idee sollten wir die Kosten nicht unterschätzen.","en":"For all our enthusiasm for the idea, we shouldn''t underestimate the costs."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('5e02b7e66dd3', 'Dem ist im Grunde nichts hinzuzufügen.', 'dem ist nichts hinzuzufügen', 'There''s essentially nothing to add to that.', 'C2', 'sprechen', 'sprechen_t1', 'zustimmen', 'agreement', 'Gehobene, nachdrückliche Zustimmung mit zu-Infinitiv.', 'Dem ist im Grunde nichts {{hinzuzufügen}}.', array['Dem','ist','im','Grunde','nichts','hinzuzufügen.']::text[], array['das','etwas','hinzufügen']::text[], array['zustimmung','formell']::text[], 4, '[{"de":"Du hast alles gesagt, dem ist im Grunde nichts hinzuzufügen.","en":"You''ve said it all, there''s essentially nothing to add to that."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('8185d28449a2', 'Lassen Sie uns das so festhalten und morgen fortfahren.', 'lassen Sie uns … festhalten', 'Let''s record it that way and continue tomorrow.', 'C2', 'sprechen', 'sprechen_t1', 'sich_einigen', 'agreement', '''Lassen Sie uns …'' höflicher Appell im formellen Register.', 'Lassen Sie uns das so {{festhalten}} und morgen fortfahren.', array['Lassen','Sie','uns','das','so','festhalten','und','morgen','fortfahren.']::text[], array['Sie,','uns,','fortsetzen']::text[], array['einigung','formell']::text[], 4, '[{"de":"Wir sind uns einig. Lassen Sie uns das so festhalten und morgen fortfahren.","en":"We''re in agreement. Let''s record it that way and continue tomorrow."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('bc5416cbeab3', 'Mir schwebt vor, das Projekt in zwei Phasen zu gliedern.', 'mir schwebt vor, … zu …', 'I have in mind to organize the project into two phases.', 'C2', 'sprechen', 'sprechen_t1', 'vorschlag_bitte', 'suggestion', 'jemandem schwebt etwas vor: gehoben für eine vage Vorstellung.', 'Mir {{schwebt}} vor, das Projekt in zwei Phasen zu gliedern.', array['Mir','schwebt','vor,','das','Projekt','in','zwei','Phasen','zu','gliedern.']::text[], array['schwebt,','gliedert','über']::text[], array['vorschlag','idiom']::text[], 4, '[{"de":"Mir schwebt vor, zuerst die Ideen zu sammeln und dann zu entscheiden.","en":"I have in mind to first collect the ideas and then decide."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('05e557ea04c4', 'Das war mein Vortrag, danke fürs Zuhören.', 'das war mein Vortrag, danke …', 'That was my talk, thanks for listening.', 'B1', 'sprechen', 'sprechen_t2', 'abschluss_praesentation', 'closing', 'Lockerer, freundlicher Abschluss.', 'Das war mein {{Vortrag}}, danke fürs Zuhören.', array['Das','war','mein','Vortrag,','danke','fürs','Zuhören.']::text[], array['waren','meinen','Zuhören,']::text[], array['abschluss']::text[], 1, '[{"de":"Das war mein Vortrag, danke fürs Zuhören, jetzt freue ich mich auf eure Fragen.","en":"That was my talk, thanks for listening, now I look forward to your questions."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('067b59b37ebf', 'Ich glaube, das ist eine gute Lösung.', 'ich glaube, das ist …', 'I think that''s a good solution.', 'B1', 'sprechen', 'sprechen_t2', 'bewerten', 'evaluation', 'glauben für vorsichtige Bewertung.', 'Ich {{glaube}}, das ist eine gute Lösung.', array['Ich','glaube,','das','ist','eine','gute','Lösung.']::text[], array['glauben','der','Lösungen']::text[], array['bewertung']::text[], 1, '[{"de":"Ich glaube, das ist eine gute Lösung für unser Problem.","en":"I think that''s a good solution for our problem."},{"de":"Ich glaube, das ist eine gute Lösung, aber sie kostet viel Zeit.","en":"I think that''s a good solution, but it costs a lot of time."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('06829a68469c', 'Zuerst gebe ich einen kurzen Überblick.', 'zuerst gebe ich einen Überblick', 'First I''ll give a brief overview.', 'B2', 'sprechen', 'sprechen_t2', 'gliedern', 'structuring', 'Reihenfolge mit zuerst, danach, zum Schluss.', '{{Zuerst}} gebe ich einen kurzen Überblick.', array['Zuerst','gebe','ich','einen','kurzen','Überblick.']::text[], array['geben','einem','Überblicke']::text[], array['gliederung']::text[], 1, '[{"de":"Zuerst gebe ich einen kurzen Überblick über das Thema.","en":"First I''ll give a brief overview of the topic."},{"de":"Zuerst gebe ich einen kurzen Überblick, danach zeige ich Beispiele.","en":"First I''ll give a brief overview, then I''ll show examples."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('2b2f490debf0', 'Kommen wir nun zum nächsten Punkt.', 'kommen wir nun zum … Punkt', 'Let''s now move on to the next point.', 'B1', 'sprechen', 'sprechen_t2', 'uebergaenge', 'transition', 'Standardübergang in Präsentationen.', 'Kommen wir {{nun}} zum nächsten Punkt.', array['Kommen','wir','nun','zum','nächsten','Punkt.']::text[], array['kommt','zur','Punkte']::text[], array['uebergang']::text[], 1, '[{"de":"So weit zur Theorie. Kommen wir nun zum nächsten Punkt, den Beispielen.","en":"So much for the theory. Let''s now move on to the next point, the examples."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('4746bcc78203', 'Vielen Dank für eure Aufmerksamkeit.', 'vielen Dank für eure Aufmerksamkeit', 'Thank you very much for your attention.', 'B1', 'sprechen', 'sprechen_t2', 'abschluss_praesentation', 'closing', 'Höfliche Standardformel am Ende.', 'Vielen Dank für eure {{Aufmerksamkeit}}.', array['Vielen','Dank','für','eure','Aufmerksamkeit.']::text[], array['Danke,','euer','Aufmerksamkeiten']::text[], array['abschluss','dank']::text[], 1, '[{"de":"Vielen Dank für eure Aufmerksamkeit. Habt ihr noch Fragen?","en":"Thank you very much for your attention. Do you have any questions?"},{"de":"Das war mein Vortrag über das Reisen – vielen Dank für eure Aufmerksamkeit.","en":"That was my talk about traveling – thank you very much for your attention."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('760c01703ba2', 'In meinem Heimatland ist das ganz anders.', 'in meinem Heimatland ist … anders', 'In my home country it''s completely different.', 'B1', 'sprechen', 'sprechen_t2', 'erfahrung', 'experience', 'Persönlicher Bezug zur Heimat.', 'In meinem {{Heimatland}} ist das ganz anders.', array['In','meinem','Heimatland','ist','das','ganz','anders.']::text[], array['meinen','Heimatländer','gleich']::text[], array['erfahrung','heimat']::text[], 1, '[{"de":"In meinem Heimatland ist das ganz anders als hier.","en":"In my home country it''s completely different from here."},{"de":"In meinem Heimatland ist das ganz anders, da isst man später zu Abend.","en":"In my home country it''s completely different; people eat dinner later there."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('a14320182258', 'In meiner Präsentation geht es um das Reisen.', 'in meiner Präsentation geht es um …', 'My presentation is about traveling.', 'B1', 'sprechen', 'sprechen_t2', 'gliedern', 'structuring', 'es geht um + Akkusativ: Thema nennen.', 'In meiner Präsentation geht es {{um}} das Reisen.', array['In','meiner','Präsentation','geht','es','um','das','Reisen.']::text[], array['geht,','über','der']::text[], array['einleitung']::text[], 1, '[{"de":"In meiner Präsentation geht es um das Reisen und seine Vorteile.","en":"My presentation is about traveling and its advantages."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('a45bfc2f5dd7', 'Ich finde, dass die Vorteile überwiegen.', 'ich finde, dass …', 'I think the advantages outweigh.', 'B1', 'sprechen', 'sprechen_t2', 'bewerten', 'evaluation', 'finden, dass …: persönliche Bewertung.', 'Ich {{finde}}, dass die Vorteile überwiegen.', array['Ich','finde,','dass','die','Vorteile','überwiegen.']::text[], array['finden','ob','Vorteil']::text[], array['bewertung']::text[], 1, '[{"de":"Ich finde, dass die Vorteile überwiegen, deshalb bin ich dafür.","en":"I think that the advantages outweigh the disadvantages, so I''m in favor."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('b5adfe46cacf', 'Danach spreche ich über die Vorteile.', 'danach spreche ich über …', 'After that I''ll talk about the advantages.', 'B1', 'sprechen', 'sprechen_t2', 'uebergaenge', 'transition', 'über etwas sprechen + Akkusativ.', '{{Danach}} spreche ich über die Vorteile.', array['Danach','spreche','ich','über','die','Vorteile.']::text[], array['sprechen','auf','Vorteil']::text[], array['uebergang']::text[], 1, '[{"de":"Zuerst zeige ich die Zahlen, danach spreche ich über die Vorteile.","en":"First I''ll show the figures, then I''ll talk about the advantages."},{"de":"Danach spreche ich über die Nachteile dieser Lösung.","en":"After that I''ll talk about the disadvantages of this solution."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('bdf9d884d281', 'Heute spreche ich über das Lernen von Sprachen.', 'heute spreche ich über …', 'Today I''m talking about learning languages.', 'B1', 'sprechen', 'sprechen_t2', 'gliedern', 'structuring', 'über etwas sprechen: Thema einführen.', 'Heute {{spreche}} ich über das Lernen von Sprachen.', array['Heute','spreche','ich','über','das','Lernen','von','Sprachen.']::text[], array['sprechen','auf','Sprache']::text[], array['einleitung']::text[], 1, '[{"de":"Heute spreche ich über das Lernen von Sprachen und gebe euch ein paar Tipps.","en":"Today I''m talking about learning languages and will give you a few tips."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('bf611ff505e9', 'Bei uns zu Hause macht man das oft so.', 'bei uns zu Hause macht man …', 'Back home we often do it this way.', 'B1', 'sprechen', 'sprechen_t2', 'erfahrung', 'experience', '''bei uns zu Hause'' für kulturellen Vergleich.', 'Bei uns zu Hause macht {{man}} das oft so.', array['Bei','uns','zu','Hause','macht','man','das','oft','so.']::text[], array['man,','Hause,','selten']::text[], array['erfahrung','heimat']::text[], 1, '[{"de":"Bei uns zu Hause macht man das oft so: Am Sonntag isst die ganze Familie zusammen.","en":"Back home we often do it this way: on Sundays the whole family eats together."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('e0a76026b4ee', 'Meiner Meinung nach ist das sehr wichtig.', 'meiner Meinung nach ist …', 'In my opinion this is very important.', 'B1', 'sprechen', 'sprechen_t2', 'bewerten', 'evaluation', 'Meiner Meinung nach: Standardeinleitung einer Bewertung.', 'Meiner {{Meinung}} nach ist das sehr wichtig.', array['Meiner','Meinung','nach','ist','das','sehr','wichtig.']::text[], array['Meinung,','an','unwichtig']::text[], array['bewertung','meinung']::text[], 1, '[{"de":"Meiner Meinung nach ist das sehr wichtig für die Zukunft.","en":"In my opinion this is very important for the future."},{"de":"Meiner Meinung nach ist das sehr wichtig, denn alle profitieren davon.","en":"In my opinion this is very important, because everyone benefits from it."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('edd61cc2cd9d', 'Jetzt komme ich zum zweiten Punkt.', 'jetzt komme ich zum … Punkt', 'Now I''ll move on to the second point.', 'B1', 'sprechen', 'sprechen_t2', 'uebergaenge', 'transition', 'Einfacher Übergang.', 'Jetzt {{komme}} ich zum zweiten Punkt.', array['Jetzt','komme','ich','zum','zweiten','Punkt.']::text[], array['kommen','zur','Punkte']::text[], array['uebergang']::text[], 1, '[{"de":"Jetzt komme ich zum zweiten Punkt: den Kosten.","en":"Now I come to the second point: the costs."},{"de":"Jetzt komme ich zum dritten Punkt meiner Präsentation.","en":"Now I come to the third point of my presentation."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('f170ac2ee9ae', 'Zum Schluss möchte ich kurz zusammenfassen.', 'zum Schluss möchte ich zusammenfassen', 'To conclude, I''d like to briefly summarize.', 'B1', 'sprechen', 'sprechen_t2', 'abschluss_praesentation', 'closing', 'Klassische Abschlussformel.', 'Zum {{Schluss}} möchte ich kurz zusammenfassen.', array['Zum','Schluss','möchte','ich','kurz','zusammenfassen.']::text[], array['Schlüsse','will','zusammengefasst']::text[], array['abschluss']::text[], 1, '[{"de":"Zum Schluss möchte ich kurz zusammenfassen, was wir gehört haben.","en":"To conclude, I''d like to briefly summarize what we''ve heard."},{"de":"Zum Schluss möchte ich kurz zusammenfassen und ein Fazit ziehen.","en":"To conclude, I''d like to briefly summarize and draw a conclusion."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('fd59ad5fded6', 'Bei uns feiert man dieses Fest im Sommer.', 'bei uns feiert man … im Sommer', 'Where I''m from, we celebrate this festival in summer.', 'B1', 'sprechen', 'sprechen_t2', 'erfahrung', 'experience', 'Kultureller Bezug mit man.', 'Bei uns {{feiert}} man dieses Fest im Sommer.', array['Bei','uns','feiert','man','dieses','Fest','im','Sommer.']::text[], array['feiern','den','Winter']::text[], array['erfahrung','heimat']::text[], 1, '[{"de":"Bei uns feiert man dieses Fest im Sommer, meistens draußen im Park.","en":"Where I''m from, this festival is celebrated in summer, usually outside in the park."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('283051b44b73', 'Ich möchte euch heute das Thema Umweltschutz vorstellen.', 'ich möchte euch heute … vorstellen', 'Today I''d like to present the topic of environmental protection to you.', 'B1', 'sprechen', 'sprechen_t2', 'gliedern', 'structuring', 'jemandem etwas vorstellen.', 'Ich möchte euch heute das Thema Umweltschutz {{vorstellen}}.', array['Ich','möchte','euch','heute','das','Thema','Umweltschutz','vorstellen.']::text[], array['will','der','vorgestellt']::text[], array['einleitung']::text[], 2, '[{"de":"Ich möchte euch heute das Thema gesunde Ernährung vorstellen.","en":"Today I''d like to present the topic of healthy eating to you."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('33875095a27d', 'Damit bin ich am Ende meiner Präsentation.', 'damit bin ich am Ende meiner Präsentation', 'That brings me to the end of my presentation.', 'B2', 'sprechen', 'sprechen_t2', 'abschluss_praesentation', 'closing', 'Signalisiert das Ende klar und höflich.', 'Damit bin ich am {{Ende}} meiner Präsentation.', array['Damit','bin','ich','am','Ende','meiner','Präsentation.']::text[], array['beim','Ende,','Präsentationen']::text[], array['abschluss']::text[], 2, '[{"de":"Damit bin ich am Ende meiner Präsentation und danke euch für die Aufmerksamkeit.","en":"That brings me to the end of my presentation and I thank you for your attention."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('3fddc6f19731', 'Ein klarer Vorteil ist, dass es viel Zeit spart.', 'ein Vorteil ist, dass …', 'A clear advantage is that it saves a lot of time.', 'B2', 'sprechen', 'sprechen_t2', 'bewerten', 'evaluation', 'Vorteile/Nachteile sachlich benennen.', 'Ein klarer {{Vorteil}} ist, dass es viel Zeit spart.', array['Ein','klarer','Vorteil','ist,','dass','es','viel','Zeit','spart.']::text[], array['Vorteile','ob','gespart']::text[], array['bewertung']::text[], 2, '[{"de":"Ein klarer Vorteil ist, dass man von zu Hause aus arbeiten kann.","en":"A clear advantage is that you can work from home."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('6dcae7ab0a14', 'Besonders positiv finde ich, dass es flexibel ist.', 'besonders positiv finde ich, dass …', 'I find it particularly positive that it''s flexible.', 'B2', 'sprechen', 'sprechen_t2', 'bewerten', 'evaluation', 'Bewertung mit besonders + Adjektiv.', 'Besonders {{positiv}} finde ich, dass es flexibel ist.', array['Besonders','positiv','finde','ich,','dass','es','flexibel','ist.']::text[], array['positive','finden','negativ']::text[], array['bewertung']::text[], 2, '[{"de":"Besonders positiv finde ich, dass man jederzeit kündigen kann.","en":"I find it particularly positive that you can cancel at any time."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('73170b503144', 'Das bringt mich auch schon zum nächsten Aspekt.', 'das bringt mich zum nächsten Aspekt', 'That brings me right to the next aspect.', 'B2', 'sprechen', 'sprechen_t2', 'uebergaenge', 'transition', 'Flüssiger Übergang, der Inhalte verknüpft.', 'Das {{bringt}} mich auch schon zum nächsten Aspekt.', array['Das','bringt','mich','auch','schon','zum','nächsten','Aspekt.']::text[], array['bringen','mir','Aspekte']::text[], array['uebergang']::text[], 2, '[{"de":"Das bringt mich auch schon zum nächsten Aspekt: den Kosten.","en":"That brings me right to the next aspect: the costs."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('853bc580290f', 'Soweit zum ersten Teil, jetzt zum zweiten.', 'soweit zu …, jetzt zu …', 'So much for the first part, now on to the second.', 'B2', 'sprechen', 'sprechen_t2', 'uebergaenge', 'transition', '''Soweit zu …'' schließt einen Abschnitt ab.', '{{Soweit}} zum ersten Teil, jetzt zum zweiten.', array['Soweit','zum','ersten','Teil,','jetzt','zum','zweiten.']::text[], array['zum,','zur','Teile']::text[], array['uebergang']::text[], 2, '[{"de":"Soweit zum ersten Teil meines Vortrags, jetzt komme ich zum zweiten.","en":"So much for the first part of my talk, now I come to the second."},{"de":"Soweit zur Theorie, jetzt zu den praktischen Beispielen.","en":"So much for the theory, now on to the practical examples."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('9c44c6c232aa', 'Mein Vortrag besteht aus drei Teilen.', 'mein Vortrag besteht aus … Teilen', 'My talk consists of three parts.', 'B1', 'sprechen', 'sprechen_t2', 'gliedern', 'structuring', 'bestehen aus + Dativ: Struktur ankündigen.', 'Mein Vortrag {{besteht}} aus drei Teilen.', array['Mein','Vortrag','besteht','aus','drei','Teilen.']::text[], array['bestehen','aus,','Teile']::text[], array['gliederung']::text[], 2, '[{"de":"Mein Vortrag besteht aus drei Teilen: Einleitung, Hauptteil und Schluss.","en":"My talk consists of three parts: introduction, main part, and conclusion."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('b335f23c1dc6', 'Aus eigener Erfahrung kann ich das nur bestätigen.', 'aus eigener Erfahrung kann ich …', 'From my own experience I can only confirm this.', 'B2', 'sprechen', 'sprechen_t2', 'erfahrung', 'experience', 'aus eigener Erfahrung: persönliche Glaubwürdigkeit.', 'Aus eigener {{Erfahrung}} kann ich das nur bestätigen.', array['Aus','eigener','Erfahrung','kann','ich','das','nur','bestätigen.']::text[], array['eigene','Erfahrungen','bestätigt']::text[], array['erfahrung']::text[], 2, '[{"de":"Aus eigener Erfahrung kann ich das nur bestätigen: Üben hilft wirklich.","en":"From my own experience I can only confirm this: practicing really helps."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('bb9a3320d4a7', 'Im Folgenden gehe ich auf drei Punkte ein.', 'im Folgenden gehe ich auf … ein', 'In what follows, I''ll address three points.', 'B2', 'sprechen', 'sprechen_t2', 'gliedern', 'structuring', 'auf etwas eingehen (trennbar).', 'Im Folgenden gehe ich auf drei Punkte {{ein}}.', array['Im','Folgenden','gehe','ich','auf','drei','Punkte','ein.']::text[], array['folgenden','über','eingehen']::text[], array['gliederung']::text[], 2, '[{"de":"Im Folgenden gehe ich auf drei Punkte ein: Kosten, Zeit und Umwelt.","en":"In what follows, I''ll address three points: cost, time, and the environment."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('ce31c7ca7fca', 'Ich habe meinen Vortrag in drei Abschnitte gegliedert.', 'ich habe … in … gegliedert', 'I have structured my talk into three sections.', 'B2', 'sprechen', 'sprechen_t2', 'gliedern', 'structuring', 'etwas in Abschnitte gliedern.', 'Ich habe meinen Vortrag in drei Abschnitte {{gegliedert}}.', array['Ich','habe','meinen','Vortrag','in','drei','Abschnitte','gegliedert.']::text[], array['meinem','gliedern','Abschnitt']::text[], array['gliederung']::text[], 2, '[{"de":"Ich habe meinen Vortrag in drei Abschnitte gegliedert, damit alles klar ist.","en":"I have structured my talk into three sections so that everything is clear."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('cf331c470e39', 'Ich habe selbst die Erfahrung gemacht, dass das hilft.', 'ich habe die Erfahrung gemacht, dass …', 'I myself have had the experience that this helps.', 'B2', 'sprechen', 'sprechen_t2', 'erfahrung', 'experience', 'eine Erfahrung machen: feste Wendung.', 'Ich habe selbst die {{Erfahrung}} gemacht, dass das hilft.', array['Ich','habe','selbst','die','Erfahrung','gemacht,','dass','das','hilft.']::text[], array['machen','Erfahrungen','ob']::text[], array['erfahrung']::text[], 2, '[{"de":"Ich habe selbst die Erfahrung gemacht, dass Reden gegen die Angst hilft.","en":"I myself have had the experience that talking helps against fear."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('ef35e00b203c', 'Gerne beantworte ich jetzt eure Fragen.', 'gerne beantworte ich eure Fragen', 'I''ll be happy to answer your questions now.', 'B2', 'sprechen', 'sprechen_t2', 'abschluss_praesentation', 'closing', 'Überleitung zur Fragerunde.', 'Gerne {{beantworte}} ich jetzt eure Fragen.', array['Gerne','beantworte','ich','jetzt','eure','Fragen.']::text[], array['beantwortet','euer','Frage']::text[], array['abschluss','fragen']::text[], 2, '[{"de":"Das war es von meiner Seite. Gerne beantworte ich jetzt eure Fragen.","en":"That''s it from my side. I''ll be happy to answer your questions now."},{"de":"Gerne beantworte ich jetzt eure Fragen zum Thema Umweltschutz.","en":"I''ll be happy to answer your questions about environmental protection now."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('12c030ebfb5c', 'Alles in allem überwiegen für mich die Vorteile.', 'alles in allem überwiegen die Vorteile', 'All in all, for me the advantages outweigh.', 'C1', 'sprechen', 'sprechen_t2', 'bewerten', 'evaluation', '''Alles in allem'' fasst eine Bewertung zusammen.', 'Alles in allem {{überwiegen}} für mich die Vorteile.', array['Alles','in','allem','überwiegen','für','mich','die','Vorteile.']::text[], array['allem,','überwiegt','Vorteil']::text[], array['bewertung']::text[], 3, '[{"de":"Es gibt ein paar Nachteile, aber alles in allem überwiegen für mich die Vorteile.","en":"There are a few disadvantages, but all in all the advantages outweigh them for me."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('16c891f377e3', 'In dieser Hinsicht unterscheidet sich meine Heimat deutlich.', 'in dieser Hinsicht unterscheidet sich …', 'In this respect my home country differs noticeably.', 'C1', 'sprechen', 'sprechen_t2', 'erfahrung', 'experience', 'sich unterscheiden: gehobener Vergleich.', 'In dieser Hinsicht {{unterscheidet}} sich meine Heimat deutlich.', array['In','dieser','Hinsicht','unterscheidet','sich','meine','Heimat','deutlich.']::text[], array['Hinsichten','unterscheidet,','sie']::text[], array['erfahrung','formell']::text[], 3, '[{"de":"In dieser Hinsicht unterscheidet sich meine Heimat deutlich von Deutschland.","en":"In this respect my home country differs noticeably from Germany."},{"de":"In dieser Hinsicht unterscheidet sich meine Heimat deutlich, vor allem beim Essen.","en":"In this respect my home country differs noticeably, especially when it comes to food."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('5400b350a60c', 'Im nächsten Schritt beleuchte ich die ökonomische Seite.', 'im nächsten Schritt beleuchte ich …', 'In the next step I''ll examine the economic side.', 'C1', 'sprechen', 'sprechen_t2', 'uebergaenge', 'transition', 'etwas beleuchten: gehoben für ''genauer betrachten''.', 'Im nächsten Schritt {{beleuchte}} ich die ökonomische Seite.', array['Im','nächsten','Schritt','beleuchte','ich','die','ökonomische','Seite.']::text[], array['Schritte','beleuchtet','Seiten']::text[], array['uebergang','formell']::text[], 3, '[{"de":"Im nächsten Schritt beleuchte ich die ökonomische Seite des Problems genauer.","en":"In the next step I''ll examine the economic side of the problem more closely."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('61ff2251b6e6', 'Kritisch anzumerken ist allerdings der hohe Aufwand.', 'kritisch anzumerken ist …', 'What must be noted critically, however, is the high effort involved.', 'C1', 'sprechen', 'sprechen_t2', 'bewerten', 'evaluation', 'anzumerken ist: gehobene, sachliche Kritik.', 'Kritisch {{anzumerken}} ist allerdings der hohe Aufwand.', array['Kritisch','anzumerken','ist','allerdings','der','hohe','Aufwand.']::text[], array['anmerken','der,','niedrige']::text[], array['bewertung','formell']::text[], 3, '[{"de":"Die Idee ist gut. Kritisch anzumerken ist allerdings der hohe Aufwand.","en":"The idea is good. What must be noted critically, however, is the high effort involved."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('6c7e1b84ca7b', 'Bevor ich fortfahre, möchte ich das kurz zusammenfassen.', 'bevor ich fortfahre, …', 'Before I continue, I''d like to briefly summarize this.', 'C1', 'sprechen', 'sprechen_t2', 'uebergaenge', 'transition', 'fortfahren: gehoben für weitermachen.', 'Bevor ich {{fortfahre}}, möchte ich das kurz zusammenfassen.', array['Bevor','ich','fortfahre,','möchte','ich','das','kurz','zusammenfassen.']::text[], array['fortfahren','will','zusammengefasst']::text[], array['uebergang','formell']::text[], 3, '[{"de":"Bevor ich fortfahre, möchte ich das kurz zusammenfassen, damit wir den Faden behalten.","en":"Before I continue, I''d like to briefly summarize this so we keep track."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('7a960643d4d8', 'Als ich noch in meiner Heimat lebte, war alles langsamer.', 'als ich in meiner Heimat lebte, …', 'When I still lived in my home country, everything was slower.', 'C1', 'sprechen', 'sprechen_t2', 'erfahrung', 'experience', 'als + Präteritum für einmalige Vergangenheit.', 'Als ich noch in meiner Heimat {{lebte}}, war alles langsamer.', array['Als','ich','noch','in','meiner','Heimat','lebte,','war','alles','langsamer.']::text[], array['wenn','Heimaten','lebt']::text[], array['erfahrung','heimat']::text[], 3, '[{"de":"Als ich noch in meiner Heimat lebte, kannte ich alle Nachbarn.","en":"When I still lived in my home country, I knew all the neighbors."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('7c458551b595', 'Damit komme ich zu einem zentralen Aspekt meines Themas.', 'damit komme ich zu einem Aspekt', 'This brings me to a central aspect of my topic.', 'C1', 'sprechen', 'sprechen_t2', 'uebergaenge', 'transition', 'Verbindet Abschnitte und betont die Relevanz.', 'Damit {{komme}} ich zu einem zentralen Aspekt meines Themas.', array['Damit','komme','ich','zu','einem','zentralen','Aspekt','meines','Themas.']::text[], array['kommen','einen','zentrale']::text[], array['uebergang','formell']::text[], 3, '[{"de":"Damit komme ich zu einem zentralen Aspekt meines Themas, nämlich der Umwelt.","en":"This brings me to a central aspect of my topic, namely the environment."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('8dc0f6fdc2cd', 'Abschließend lässt sich festhalten, dass sich der Aufwand lohnt.', 'abschließend lässt sich festhalten, dass …', 'In conclusion, it can be said that the effort pays off.', 'C1', 'sprechen', 'sprechen_t2', 'abschluss_praesentation', 'closing', '''es lässt sich festhalten'' gehoben für ein Fazit.', 'Abschließend lässt sich {{festhalten}}, dass sich der Aufwand lohnt.', array['Abschließend','lässt','sich','festhalten,','dass','sich','der','Aufwand','lohnt.']::text[], array['abschließen','sich,','festgehalten']::text[], array['abschluss','formell']::text[], 3, '[{"de":"Abschließend lässt sich festhalten, dass beide Seiten davon profitieren.","en":"In conclusion, it can be said that both sides benefit from it."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('93f7300d9a8f', 'Lassen Sie mich kurz den Aufbau meines Vortrags skizzieren.', 'lassen Sie mich den Aufbau skizzieren', 'Let me briefly outline the structure of my talk.', 'C1', 'sprechen', 'sprechen_t2', 'gliedern', 'structuring', 'den Aufbau skizzieren: gehobene Ankündigung.', 'Lassen Sie mich kurz den Aufbau meines Vortrags {{skizzieren}}.', array['Lassen','Sie','mich','kurz','den','Aufbau','meines','Vortrags','skizzieren.']::text[], array['mir','Aufbauten','skizziert']::text[], array['gliederung','formell']::text[], 3, '[{"de":"Lassen Sie mich kurz den Aufbau meines Vortrags skizzieren: drei Teile, ein Fazit.","en":"Let me briefly outline the structure of my talk: three parts and a conclusion."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('eb194a169b93', 'Zunächst möchte ich auf den Hintergrund des Themas eingehen.', 'zunächst möchte ich auf … eingehen', 'First I''d like to go into the background of the topic.', 'C1', 'sprechen', 'sprechen_t2', 'gliedern', 'structuring', 'auf etwas eingehen: ein Thema vertieft behandeln.', 'Zunächst möchte ich auf den Hintergrund des Themas {{eingehen}}.', array['Zunächst','möchte','ich','auf','den','Hintergrund','des','Themas','eingehen.']::text[], array['zuerst,','über','eingegangen']::text[], array['gliederung','formell']::text[], 3, '[{"de":"Zunächst möchte ich auf den Hintergrund des Themas eingehen, dann auf die Zahlen.","en":"First I''d like to go into the background of the topic, then into the figures."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('ff6f4ae8c506', 'Lassen Sie mich mit einem kurzen Fazit schließen.', 'lassen Sie mich mit einem Fazit schließen', 'Let me close with a brief conclusion.', 'C1', 'sprechen', 'sprechen_t2', 'abschluss_praesentation', 'closing', 'Formeller Abschluss mit Höflichkeitsform.', 'Lassen Sie mich mit einem kurzen Fazit {{schließen}}.', array['Lassen','Sie','mich','mit','einem','kurzen','Fazit','schließen.']::text[], array['mir','einen','geschlossen']::text[], array['abschluss','formell']::text[], 3, '[{"de":"Lassen Sie mich mit einem kurzen Fazit schließen: Es lohnt sich.","en":"Let me close with a brief conclusion: it''s worth it."},{"de":"Lassen Sie mich mit einem kurzen Fazit schließen und danke für Ihre Geduld.","en":"Let me close with a brief conclusion, and thank you for your patience."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('4b8da0986a9c', 'Unterm Strich fällt meine Bilanz eindeutig positiv aus.', 'unterm Strich fällt meine Bilanz … aus', 'On balance, my verdict comes out clearly positive.', 'C2', 'sprechen', 'sprechen_t2', 'bewerten', 'evaluation', '''unterm Strich'' idiomatisch für ''letztlich''.', 'Unterm {{Strich}} fällt meine Bilanz eindeutig positiv aus.', array['Unterm','Strich','fällt','meine','Bilanz','eindeutig','positiv','aus.']::text[], array['Striche','fällt,','aus,']::text[], array['bewertung','idiom']::text[], 4, '[{"de":"Es war anstrengend, aber unterm Strich fällt meine Bilanz eindeutig positiv aus.","en":"It was exhausting, but on balance my verdict comes out clearly positive."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('6e68bed28a44', 'Nahtlos daran anknüpfen lässt sich die Frage der Kosten.', 'daran anknüpfen lässt sich …', 'The question of costs follows on seamlessly from this.', 'C2', 'sprechen', 'sprechen_t2', 'uebergaenge', 'transition', 'an etwas anknüpfen: gehobener, eleganter Übergang.', 'Nahtlos daran {{anknüpfen}} lässt sich die Frage der Kosten.', array['Nahtlos','daran','anknüpfen','lässt','sich','die','Frage','der','Kosten.']::text[], array['anknüpft','sich,','Kosten,']::text[], array['uebergang','formell']::text[], 4, '[{"de":"Nahtlos daran anknüpfen lässt sich die Frage, wer das bezahlt.","en":"The question of who pays for it follows on seamlessly from this."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('7845971c5fbc', 'Ich danke Ihnen für Ihre Aufmerksamkeit und freue mich auf die Diskussion.', 'ich danke Ihnen … und freue mich auf …', 'Thank you for your attention, and I look forward to the discussion.', 'C2', 'sprechen', 'sprechen_t2', 'abschluss_praesentation', 'closing', 'Eleganter, formeller Doppelabschluss.', 'Ich danke Ihnen für Ihre {{Aufmerksamkeit}} und freue mich auf die Diskussion.', array['Ich','danke','Ihnen','für','Ihre','Aufmerksamkeit','und','freue','mich','auf','die','Diskussion.']::text[], array['danken','euch','Diskussionen']::text[], array['abschluss','formell']::text[], 4, '[{"de":"Damit bin ich am Ende. Ich danke Ihnen für Ihre Aufmerksamkeit und freue mich auf die Diskussion.","en":"That brings me to the end. Thank you for your attention, and I look forward to the discussion."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('b9806f0da0d1', 'Aus meiner ganz persönlichen Warte betrachtet, überwiegen die Vorteile.', 'aus meiner Warte betrachtet, …', 'Viewed from my own personal perspective, the advantages prevail.', 'C2', 'sprechen', 'sprechen_t2', 'erfahrung', 'experience', '''aus jemandes Warte'' gehoben für ''aus jemandes Sicht''.', 'Aus meiner ganz persönlichen {{Warte}} betrachtet, überwiegen die Vorteile.', array['Aus','meiner','ganz','persönlichen','Warte','betrachtet,','überwiegen','die','Vorteile.']::text[], array['Warten','betrachtet,','Vorteil']::text[], array['erfahrung','formell']::text[], 4, '[{"de":"Aus meiner ganz persönlichen Warte betrachtet, war die Entscheidung richtig.","en":"Viewed from my own personal perspective, the decision was the right one."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('ee1d0eb3a893', 'Erlauben Sie mir, einleitend einige Vorbemerkungen zu machen.', 'erlauben Sie mir, … zu machen', 'Allow me to make a few introductory remarks.', 'C2', 'sprechen', 'sprechen_t2', 'gliedern', 'structuring', 'Sehr formelle, gehobene Einleitung.', 'Erlauben Sie mir, einleitend einige {{Vorbemerkungen}} zu machen.', array['Erlauben','Sie','mir,','einleitend','einige','Vorbemerkungen','zu','machen.']::text[], array['Sie,','mich','gemacht']::text[], array['einleitung','formell']::text[], 4, '[{"de":"Erlauben Sie mir, einleitend einige Vorbemerkungen zum Thema zu machen.","en":"Allow me to make a few introductory remarks on the topic."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('044dedac4ed5', 'Dein Vortrag hat mir sehr gut gefallen.', 'dein Vortrag hat mir gut gefallen', 'I really liked your talk.', 'B1', 'sprechen', 'sprechen_t3', 'rueckmeldung_lob', 'feedback', 'gefallen + Dativ: einfaches Lob.', 'Dein Vortrag hat mir sehr gut {{gefallen}}.', array['Dein','Vortrag','hat','mir','sehr','gut','gefallen.']::text[], array['deinen','mich','gefallen,']::text[], array['lob']::text[], 1, '[{"de":"Dein Vortrag hat mir sehr gut gefallen, besonders der Schluss.","en":"I really liked your talk, especially the ending."},{"de":"Dein Vortrag hat mir gut gefallen, weil alles so klar war.","en":"I liked your talk because everything was so clear."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('39aa979765b3', 'Das hast du super gemacht.', 'das hast du super gemacht', 'You did that really well.', 'B1', 'sprechen', 'sprechen_t3', 'rueckmeldung_lob', 'feedback', 'Spontanes, umgangssprachliches Lob.', 'Das hast du {{super}} gemacht.', array['Das','hast','du','super','gemacht.']::text[], array['hat','dir','machen']::text[], array['lob']::text[], 1, '[{"de":"Das hast du super gemacht, wirklich klasse!","en":"You did that really well, really great!"},{"de":"Mensch, das hast du super gemacht!","en":"Wow, you did that really well!"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('4ba1c3b45e09', 'Ja, das sehe ich auch so.', 'das sehe ich auch so', 'Yes, I see it that way too.', 'B1', 'sprechen', 'sprechen_t3', 'souveraen_antworten', 'answering', 'Bestätigt eine Rückmeldung freundlich.', 'Ja, das {{sehe}} ich auch so.', array['Ja,','das','sehe','ich','auch','so.']::text[], array['sehen','mir','auch,']::text[], array['antwort']::text[], 1, '[{"de":"Ja, das sehe ich auch so – da bin ich ganz deiner Meinung.","en":"Yes, I see it that way too – I completely agree with you."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('4e9c4c10610b', 'Moment, lass mich kurz nachsehen.', 'lass mich kurz nachsehen', 'One moment, let me quickly check.', 'B1', 'sprechen', 'sprechen_t3', 'zeit_gewinnen', 'stalling', 'nachsehen: kurz prüfen, Zeit gewinnen.', 'Moment, lass mich kurz {{nachsehen}}.', array['Moment,','lass','mich','kurz','nachsehen.']::text[], array['lassen','mir','nachgesehen']::text[], array['zeit']::text[], 1, '[{"de":"Moment, lass mich kurz nachsehen, ob das stimmt.","en":"One moment, let me quickly check whether that''s right."},{"de":"Moment, lass mich kurz nachsehen, wann der Termin ist.","en":"One moment, let me quickly check when the appointment is."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('8421ee7fa92c', 'Kannst du das bitte noch einmal erklären?', 'kannst du das noch einmal erklären?', 'Can you please explain that again?', 'B1', 'sprechen', 'sprechen_t3', 'nachfragen', 'clarify', 'Einfache Bitte um Erklärung.', 'Kannst du das bitte noch einmal {{erklären}}?', array['Kannst','du','das','bitte','noch','einmal','erklären?']::text[], array['kann','dir','erklärt']::text[], array['nachfrage']::text[], 1, '[{"de":"Entschuldigung, kannst du das bitte noch einmal erklären?","en":"Sorry, can you please explain that again?"},{"de":"Das habe ich nicht ganz verstanden. Kannst du das noch einmal erklären?","en":"I didn''t quite understand that. Can you explain it again?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('8bd4c7f75cd4', 'Das ist eine interessante Frage.', 'das ist eine interessante Frage', 'That''s an interesting question.', 'B1', 'sprechen', 'sprechen_t3', 'zeit_gewinnen', 'stalling', 'Gibt Zeit, bevor man antwortet.', 'Das ist eine {{interessante}} Frage.', array['Das','ist','eine','interessante','Frage.']::text[], array['eine,','interessant','Fragen']::text[], array['zeit']::text[], 1, '[{"de":"Das ist eine interessante Frage. Lass mich kurz überlegen.","en":"That''s an interesting question. Let me think for a moment."},{"de":"Das ist eine interessante Frage, darüber spricht man selten.","en":"That''s an interesting question, people rarely talk about it."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('9ce569fe4f42', 'Da haben Sie völlig recht.', 'da haben Sie recht', 'You''re completely right about that.', 'B1', 'sprechen', 'sprechen_t3', 'souveraen_antworten', 'answering', 'recht haben: souveränes Einräumen.', 'Da haben Sie völlig {{recht}}.', array['Da','haben','Sie','völlig','recht.']::text[], array['hat','sie','Recht,']::text[], array['antwort']::text[], 1, '[{"de":"Da haben Sie völlig recht, das hatte ich übersehen.","en":"You''re completely right about that, I had overlooked it."},{"de":"Da haben Sie völlig recht – darüber sollten wir noch sprechen.","en":"You''re completely right – we should still talk about that."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('c3e4e49fecde', 'Das ist eine gute Frage.', 'das ist eine gute Frage', 'That''s a good question.', 'B1', 'sprechen', 'sprechen_t3', 'souveraen_antworten', 'answering', 'Wertschätzt die Frage und gewinnt kurz Zeit.', 'Das ist eine gute {{Frage}}.', array['Das','ist','eine','gute','Frage.']::text[], array['eine,','guter','Fragen']::text[], array['antwort']::text[], 1, '[{"de":"Das ist eine gute Frage. Lassen Sie mich kurz überlegen.","en":"That''s a good question. Let me think for a moment."},{"de":"Das ist eine gute Frage, darauf gehe ich gern ein.","en":"That''s a good question, I''m happy to address it."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('c5921a3331a4', 'Lass mich kurz überlegen.', 'lass mich kurz überlegen', 'Let me think for a moment.', 'B1', 'sprechen', 'sprechen_t3', 'zeit_gewinnen', 'stalling', 'Einfache Formel, um Bedenkzeit zu gewinnen.', 'Lass mich kurz {{überlegen}}.', array['Lass','mich','kurz','überlegen.']::text[], array['lassen','mir','überlegt']::text[], array['zeit']::text[], 1, '[{"de":"Lass mich kurz überlegen, dann sage ich dir Bescheid.","en":"Let me think for a moment, then I''ll let you know."},{"de":"Lass mich kurz überlegen – das ist nicht so einfach.","en":"Let me think for a moment – that''s not so easy."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('dc4caa06b60a', 'Was meinst du mit diesem Begriff?', 'was meinst du mit …?', 'What do you mean by this term?', 'B1', 'sprechen', 'sprechen_t3', 'nachfragen', 'clarify', 'Nach einem Begriff fragen.', 'Was {{meinst}} du mit diesem Begriff?', array['Was','meinst','du','mit','diesem','Begriff?']::text[], array['meinen','dir','Begriffe']::text[], array['nachfrage']::text[], 1, '[{"de":"Was meinst du mit diesem Begriff? Den kenne ich nicht.","en":"What do you mean by this term? I don''t know it."},{"de":"Was meinst du genau mit dem Begriff ''Nachhaltigkeit''?","en":"What exactly do you mean by the term ''sustainability''?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('e3a797b5ed48', 'Wie meinst du das genau?', 'wie meinst du das genau?', 'What exactly do you mean by that?', 'B1', 'sprechen', 'sprechen_t3', 'nachfragen', 'clarify', 'Kurze Verständnisfrage.', 'Wie {{meinst}} du das genau?', array['Wie','meinst','du','das','genau?']::text[], array['meinen','dir','genaue']::text[], array['nachfrage']::text[], 1, '[{"de":"Wie meinst du das genau? Kannst du es kurz erklären?","en":"What exactly do you mean by that? Can you explain it briefly?"},{"de":"Das verstehe ich nicht ganz – wie meinst du das genau?","en":"I don''t quite get that – what exactly do you mean?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('1389e98ca7c2', 'Könntest du dazu ein Beispiel nennen?', 'könntest du dazu ein Beispiel nennen?', 'Could you give an example of that?', 'B2', 'sprechen', 'sprechen_t3', 'nachfragen', 'clarify', 'könntest: höfliche Bitte mit Konjunktiv II.', '{{Könntest}} du dazu ein Beispiel nennen?', array['Könntest','du','dazu','ein','Beispiel','nennen?']::text[], array['kannst','das','Beispiele']::text[], array['nachfrage','konjunktiv']::text[], 2, '[{"de":"Könntest du dazu ein Beispiel nennen? Das würde mir helfen.","en":"Could you give an example of that? That would help me."},{"de":"Könntest du dazu ein konkretes Beispiel aus deinem Alltag nennen?","en":"Could you give a concrete example of that from your everyday life?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('2aa81c2b5189', 'Wie bist du eigentlich zu diesem Ergebnis gekommen?', 'wie bist du zu … gekommen?', 'How did you actually arrive at this result?', 'B2', 'sprechen', 'sprechen_t3', 'nachfragen', 'clarify', 'zu einem Ergebnis kommen: nach Begründung fragen.', 'Wie bist du eigentlich zu diesem Ergebnis {{gekommen}}?', array['Wie','bist','du','eigentlich','zu','diesem','Ergebnis','gekommen?']::text[], array['bin','diesen','kommen']::text[], array['nachfrage']::text[], 2, '[{"de":"Mich interessiert, wie du zu dieser Einschätzung gekommen bist.","en":"I''m interested in how you arrived at this assessment."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('6d8d4a17a993', 'Da muss ich kurz nachdenken.', 'da muss ich kurz nachdenken', 'I have to think about that for a second.', 'B2', 'sprechen', 'sprechen_t3', 'zeit_gewinnen', 'stalling', 'Ehrlich und souverän: Bedenkzeit erbitten.', 'Da muss ich kurz {{nachdenken}}.', array['Da','muss','ich','kurz','nachdenken.']::text[], array['müssen','mir','nachgedacht']::text[], array['zeit']::text[], 2, '[{"de":"Da muss ich kurz nachdenken, bevor ich antworte.","en":"I have to think about that for a second before I answer."},{"de":"Hm, da muss ich kurz nachdenken.","en":"Hmm, I have to think about that for a second."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('78681c3876cc', 'Ich fand deine Beispiele besonders anschaulich.', 'ich fand deine Beispiele anschaulich', 'I found your examples especially vivid.', 'B1', 'sprechen', 'sprechen_t3', 'rueckmeldung_lob', 'feedback', 'anschaulich: lebt von konkreten Beispielen.', 'Ich fand deine Beispiele besonders {{anschaulich}}.', array['Ich','fand','deine','Beispiele','besonders','anschaulich.']::text[], array['finde','deinen','Beispiel']::text[], array['lob']::text[], 2, '[{"de":"Ich fand deine Beispiele anschaulich, weil sie aus dem Alltag kamen.","en":"I found your examples vivid because they came from everyday life."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('cd34e6dd8963', 'Das kann ich gut nachvollziehen.', 'das kann ich nachvollziehen', 'I can well understand that.', 'B2', 'sprechen', 'sprechen_t3', 'souveraen_antworten', 'answering', 'nachvollziehen: zeigt Verständnis ohne nachzugeben.', 'Das kann ich gut {{nachvollziehen}}.', array['Das','kann','ich','gut','nachvollziehen.']::text[], array['kann,','dir','nachvollzogen']::text[], array['antwort']::text[], 2, '[{"de":"Das kann ich gut nachvollziehen, aber ich sehe es etwas anders.","en":"I can well understand that, but I see it a little differently."},{"de":"Deine Bedenken kann ich gut nachvollziehen.","en":"I can well understand your concerns."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('cd6c1c52e341', 'Mir hat besonders gut der Einstieg gefallen.', 'mir hat besonders … gefallen', 'I particularly liked the introduction.', 'B2', 'sprechen', 'sprechen_t3', 'rueckmeldung_lob', 'feedback', 'Konkretes Lob für einen bestimmten Teil.', 'Mir hat besonders gut der {{Einstieg}} gefallen.', array['Mir','hat','besonders','gut','der','Einstieg','gefallen.']::text[], array['mich','Einstiege','gefallen,']::text[], array['lob']::text[], 2, '[{"de":"Mir hat besonders gut dein Einstieg mit der Frage gefallen.","en":"I particularly liked your introduction with the question."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('cfce5a4c0b16', 'Wenn ich das richtig verstehe, geht es dir um die Kosten.', 'wenn ich das richtig verstehe, …', 'If I understand you correctly, you mean the costs.', 'B2', 'sprechen', 'sprechen_t3', 'zeit_gewinnen', 'stalling', 'Paraphrasieren gewinnt Zeit und sichert Verständnis.', 'Wenn ich das richtig {{verstehe}}, geht es dir um die Kosten.', array['Wenn','ich','das','richtig','verstehe,','geht','es','dir','um','die','Kosten.']::text[], array['verstanden','dich','Kosten,']::text[], array['zeit']::text[], 2, '[{"de":"Wenn ich das richtig verstehe, möchtest du mehr Zeit.","en":"If I understand you correctly, you''d like more time."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('e811b36d4a7e', 'Das war wirklich klar und gut strukturiert.', 'das war klar und gut strukturiert', 'That was really clear and well structured.', 'B2', 'sprechen', 'sprechen_t3', 'rueckmeldung_lob', 'feedback', 'Lob für Aufbau und Verständlichkeit.', 'Das war wirklich klar und gut {{strukturiert}}.', array['Das','war','wirklich','klar','und','gut','strukturiert.']::text[], array['waren','oder','strukturiert,']::text[], array['lob']::text[], 2, '[{"de":"Dein Vortrag war klar und gut strukturiert, das hat geholfen.","en":"Your talk was clear and well structured, that helped."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('fac11559278e', 'Genau darauf wollte ich noch zu sprechen kommen.', 'darauf wollte ich noch zu sprechen kommen', 'That''s exactly what I was going to come to.', 'B2', 'sprechen', 'sprechen_t3', 'souveraen_antworten', 'answering', '''zu sprechen kommen auf'': souverän überleiten.', 'Genau {{darauf}} wollte ich noch zu sprechen kommen.', array['Genau','darauf','wollte','ich','noch','zu','sprechen','kommen.']::text[], array['dorthin','will','gesprochen']::text[], array['antwort']::text[], 2, '[{"de":"Auf die Kosten wollte ich gleich noch zu sprechen kommen.","en":"I was going to come to the costs in a moment."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('1aec92f7a365', 'Lassen Sie mich das gern etwas genauer ausführen.', 'lassen Sie mich das genauer ausführen', 'Let me gladly elaborate on that a bit further.', 'C1', 'sprechen', 'sprechen_t3', 'souveraen_antworten', 'answering', 'etwas ausführen: ausführlich darlegen.', 'Lassen Sie mich das gern etwas genauer {{ausführen}}.', array['Lassen','Sie','mich','das','gern','etwas','genauer','ausführen.']::text[], array['mir','der','ausgeführt']::text[], array['antwort','formell']::text[], 3, '[{"de":"Gute Frage – lassen Sie mich das etwas genauer ausführen.","en":"Good question – let me elaborate on that a bit more."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('2955c2c666cc', 'Lassen Sie mich kurz die Frage sortieren, bevor ich antworte.', 'lassen Sie mich die Frage sortieren', 'Let me sort out the question briefly before I answer.', 'C1', 'sprechen', 'sprechen_t3', 'zeit_gewinnen', 'stalling', 'Strukturierter Zeitgewinn im formellen Register.', 'Lassen Sie mich kurz die Frage {{sortieren}}, bevor ich antworte.', array['Lassen','Sie','mich','kurz','die','Frage','sortieren,','bevor','ich','antworte.']::text[], array['mir','der','sortiert']::text[], array['zeit','formell']::text[], 3, '[{"de":"Lassen Sie mich die Frage kurz sortieren – sie hat mehrere Teile.","en":"Let me sort out the question briefly – it has several parts."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('3f5df766ec78', 'Besonders überzeugend fand ich deine Argumentation.', 'besonders überzeugend fand ich …', 'I found your line of argument particularly convincing.', 'C1', 'sprechen', 'sprechen_t3', 'rueckmeldung_lob', 'feedback', 'Gehobenes, präzises Lob.', 'Besonders {{überzeugend}} fand ich deine Argumentation.', array['Besonders','überzeugend','fand','ich','deine','Argumentation.']::text[], array['überzeugen','finde','Argumentationen']::text[], array['lob','formell']::text[], 3, '[{"de":"Besonders überzeugend fand ich deine Argumentation am Schluss.","en":"I found your line of argument at the end particularly convincing."},{"de":"Besonders überzeugend fand ich, wie du die Zahlen erklärt hast.","en":"I found it particularly convincing how you explained the figures."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('884951df9dd3', 'Darüber habe ich so noch gar nicht nachgedacht.', 'darüber habe ich noch nicht nachgedacht', 'I hadn''t really thought about it that way yet.', 'C1', 'sprechen', 'sprechen_t3', 'zeit_gewinnen', 'stalling', 'Ehrlicher Zeitgewinn, der souverän wirkt.', 'Darüber habe ich so noch gar nicht {{nachgedacht}}.', array['Darüber','habe','ich','so','noch','gar','nicht','nachgedacht.']::text[], array['darauf','hatte','nachdenken']::text[], array['zeit']::text[], 3, '[{"de":"Interessant – darüber habe ich so noch gar nicht nachgedacht.","en":"Interesting – I hadn''t thought about it that way yet."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('9e3a5e66030f', 'Dürfte ich an dieser Stelle kurz nachhaken?', 'dürfte ich kurz nachhaken?', 'Might I follow up briefly at this point?', 'C1', 'sprechen', 'sprechen_t3', 'nachfragen', 'clarify', 'nachhaken: vertiefend nachfragen, höflich mit dürfte.', 'Dürfte ich an dieser Stelle kurz {{nachhaken}}?', array['Dürfte','ich','an','dieser','Stelle','kurz','nachhaken?']::text[], array['darf','der','nachgehakt']::text[], array['nachfrage','formell']::text[], 3, '[{"de":"Verzeihung, dürfte ich an dieser Stelle kurz nachhaken?","en":"Excuse me, might I follow up briefly at this point?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('a1e54dbc66b5', 'Mich würde interessieren, worauf du dich dabei stützt.', 'mich würde interessieren, worauf …', 'I''d be interested to know what you base this on.', 'C1', 'sprechen', 'sprechen_t3', 'nachfragen', 'clarify', 'sich auf etwas stützen: nach der Quelle fragen.', 'Mich würde {{interessieren}}, worauf du dich dabei stützt.', array['Mich','würde','interessieren,','worauf','du','dich','dabei','stützt.']::text[], array['mir','worauf,','stützen']::text[], array['nachfrage','formell']::text[], 3, '[{"de":"Mich würde interessieren, worauf du deine Prognose stützt.","en":"I''d be interested to know what you base your forecast on."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('dc6e5932d59c', 'Das ist ein berechtigter Einwand, dem ich gern begegne.', 'das ist ein berechtigter Einwand', 'That''s a valid objection, which I''m happy to address.', 'C1', 'sprechen', 'sprechen_t3', 'souveraen_antworten', 'answering', 'einem Einwand begegnen: souverän kontern.', 'Das ist ein berechtigter {{Einwand}}, dem ich gern begegne.', array['Das','ist','ein','berechtigter','Einwand,','dem','ich','gern','begegne.']::text[], array['berechtigt','den','Einwände']::text[], array['antwort','formell']::text[], 3, '[{"de":"Das ist ein berechtigter Einwand – lassen Sie mich dazu etwas sagen.","en":"That''s a valid objection – let me say something about it."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('f766f4352a8a', 'Du hast das Thema wirklich auf den Punkt gebracht.', 'du hast das auf den Punkt gebracht', 'You really got to the heart of the topic.', 'C1', 'sprechen', 'sprechen_t3', 'rueckmeldung_lob', 'feedback', '''auf den Punkt bringen'': idiomatisches Lob.', 'Du hast das Thema wirklich auf den {{Punkt}} gebracht.', array['Du','hast','das','Thema','wirklich','auf','den','Punkt','gebracht.']::text[], array['bringst','dem','Punkte']::text[], array['lob','idiom']::text[], 3, '[{"de":"Mit deinem letzten Satz hast du alles auf den Punkt gebracht.","en":"With your last sentence you summed it all up perfectly."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('0e5b97de67da', 'Hut ab, das war eine rundum gelungene Präsentation.', 'das war eine gelungene Präsentation', 'Hats off, that was a thoroughly successful presentation.', 'C2', 'sprechen', 'sprechen_t3', 'rueckmeldung_lob', 'feedback', '''Hut ab'' umgangssprachlich-anerkennend, gehoben im Lob.', 'Hut ab, das war eine rundum {{gelungene}} Präsentation.', array['Hut','ab,','das','war','eine','rundum','gelungene','Präsentation.']::text[], array['ab,','einen','Präsentationen']::text[], array['lob','idiom']::text[], 4, '[{"de":"Hut ab, das war eine rundum gelungene Präsentation!","en":"Hats off, that was an all-around successful presentation!"},{"de":"Hut ab, so eine gelungene Präsentation sieht man selten.","en":"Hats off, you rarely see such a successful presentation."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('2de5d3ea4ecf', 'Diesen Punkt möchte ich entschieden, aber sachlich entkräften.', 'diesen Punkt möchte ich entkräften', 'I''d like to refute this point firmly but objectively.', 'C2', 'sprechen', 'sprechen_t3', 'souveraen_antworten', 'answering', 'ein Argument entkräften: gehoben für widerlegen.', 'Diesen Punkt möchte ich entschieden, aber sachlich {{entkräften}}.', array['Diesen','Punkt','möchte','ich','entschieden,','aber','sachlich','entkräften.']::text[], array['diesem','will','entkräftet']::text[], array['antwort','formell']::text[], 4, '[{"de":"Diesen Einwand möchte ich kurz entkräften.","en":"I''d like to briefly refute this objection."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('4c1750642d3a', 'Erlauben Sie mir, einen Moment zu sammeln, bevor ich darauf eingehe.', 'erlauben Sie mir, einen Moment zu sammeln', 'Allow me a moment to gather my thoughts before I address this.', 'C2', 'sprechen', 'sprechen_t3', 'zeit_gewinnen', 'stalling', 'Sehr gehobene, souveräne Bitte um Bedenkzeit.', 'Erlauben Sie mir, einen Moment zu {{sammeln}}, bevor ich darauf eingehe.', array['Erlauben','Sie','mir,','einen','Moment','zu','sammeln,','bevor','ich','darauf','eingehe.']::text[], array['mich','der','gesammelt']::text[], array['zeit','formell']::text[], 4, '[{"de":"Erlauben Sie mir, kurz die Gedanken zu sammeln, bevor ich antworte.","en":"Allow me to gather my thoughts briefly before I answer."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('5f6fba46fd02', 'Inwiefern lässt sich dieser Befund verallgemeinern?', 'inwiefern lässt sich … verallgemeinern?', 'To what extent can this finding be generalized?', 'C2', 'sprechen', 'sprechen_t3', 'nachfragen', 'clarify', 'Anspruchsvolle, präzise Rückfrage.', '{{Inwiefern}} lässt sich dieser Befund verallgemeinern?', array['Inwiefern','lässt','sich','dieser','Befund','verallgemeinern?']::text[], array['inwieweit,','sich,','verallgemeinert']::text[], array['nachfrage','formell']::text[], 4, '[{"de":"Inwiefern lässt sich Ihr Ergebnis auf andere Länder übertragen?","en":"To what extent can your result be applied to other countries?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('7044740f90ac', 'Erlauben Sie, dass ich diesen Aspekt etwas differenzierter beleuchte.', 'erlauben Sie, dass ich … beleuchte', 'Allow me to examine this aspect in a more nuanced way.', 'C2', 'sprechen', 'sprechen_t3', 'souveraen_antworten', 'answering', 'Souveräne, gehobene Antwort mit Höflichkeitsform.', 'Erlauben Sie, dass ich diesen Aspekt etwas differenzierter {{beleuchte}}.', array['Erlauben','Sie,','dass','ich','diesen','Aspekt','etwas','differenzierter','beleuchte.']::text[], array['erlaubt','den','beleuchtet']::text[], array['antwort','formell']::text[], 4, '[{"de":"Erlauben Sie, dass ich diesen Punkt noch genauer beleuchte.","en":"Allow me to examine this point more closely."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('0a7572c0133e', 'Wir kommen, falls das Wetter passt.', '…, falls …', 'We''ll come if the weather is right.', 'B1', 'shared', 'shared_konnektoren', 'konnektor_bedingung', 'connector_condition', '‘falls’ ist subordinierend: Verb am Nebensatzende.', 'Wir kommen, {{falls}} das Wetter passt.', array['Wir','kommen,','falls','das','Wetter','passt.']::text[], array['wenn','sofern','passen']::text[], array['konnektor','bedingung']::text[], 1, '[{"de":"Falls du Hilfe brauchst, melde dich bei mir.","en":"If you need help, get in touch with me."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('3b8a9a8f2546', 'Was das angeht, bin ich anderer Meinung.', 'Was das angeht, …', 'As for that, I am of a different opinion.', 'B1', 'shared', 'shared_konnektoren', 'konnektor_bezug', 'connector_reference', '‘was das angeht’ leitet einen Bezug ein; danach Inversion.', 'Was das {{angeht,}} bin ich anderer Meinung.', array['Was','das','angeht,','bin','ich','anderer','Meinung.']::text[], array['Diesbezüglich','Dazu','bist']::text[], array['konnektor','bezug']::text[], 1, '[{"de":"Was das angeht, müssen wir noch einmal reden.","en":"As for that, we still need to talk again."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('4a91274cd3fb', 'Außerdem ist das Hotel sehr zentral.', 'Außerdem …', 'Besides, the hotel is very central.', 'B1', 'shared', 'shared_konnektoren', 'konnektor_aufzaehlung', 'connector_enumeration', '‘außerdem’ löst Inversion aus.', '{{Außerdem}} ist das Hotel sehr zentral.', array['Außerdem','ist','das','Hotel','sehr','zentral.']::text[], array['Zudem','Ferner','sind']::text[], array['konnektor','aufzaehlung']::text[], 1, '[{"de":"Das Zimmer ist sauber. Außerdem ist das Hotel sehr zentral.","en":"The room is clean. Besides, the hotel is very central."},{"de":"Das Essen war lecker, außerdem war der Service freundlich.","en":"The food was delicious; besides, the service was friendly."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('4e48b6e8d2a4', 'Erstens fehlt Zeit, zweitens fehlt Geld.', 'Erstens …, zweitens …', 'Firstly time is lacking, secondly money is lacking.', 'B1', 'shared', 'shared_konnektoren', 'konnektor_aufzaehlung', 'connector_enumeration', '‘erstens’ löst Inversion aus; gliedert eine Aufzählung.', '{{Erstens}} fehlt Zeit, zweitens fehlt Geld.', array['Erstens','fehlt','Zeit,','zweitens','fehlt','Geld.']::text[], array['Außerdem','Zudem','fehlen']::text[], array['konnektor','aufzaehlung']::text[], 1, '[{"de":"Ich kann nicht mitkommen: Erstens fehlt Zeit, zweitens fehlt Geld.","en":"I can''t come along: firstly time is lacking, secondly money is lacking."},{"de":"Erstens ist es zu teuer, zweitens ist es zu weit weg.","en":"Firstly it''s too expensive, secondly it''s too far away."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('89efd1921d01', 'Trotzdem gab er nicht auf.', 'Trotzdem …', 'Nevertheless, he didn''t give up.', 'B1', 'shared', 'shared_konnektoren', 'konnektor_einraeumung', 'connector_concession', '‘trotzdem’ am Satzanfang löst Inversion aus.', '{{Trotzdem}} gab er nicht auf.', array['Trotzdem','gab','er','nicht','auf.']::text[], array['Obwohl','Dennoch','gaben']::text[], array['konnektor','einraeumung']::text[], 1, '[{"de":"Es regnete stark. Trotzdem gab er nicht auf.","en":"It was raining heavily. Nevertheless, he didn''t give up."},{"de":"Sie war krank, trotzdem ging sie zur Arbeit.","en":"She was sick; nevertheless, she went to work."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('94f2e798bbbf', 'Weil er fleißig lernte, bestand er die Prüfung.', 'Weil …, …', 'Because he studied hard, he passed the exam.', 'B1', 'shared', 'shared_konnektoren', 'konnektor_grund', 'connector_reason', '‘weil’ ist subordinierend; Verb am Nebensatzende.', '{{Weil}} er fleißig lernte, bestand er die Prüfung.', array['Weil','er','fleißig','lernte,','bestand','er','die','Prüfung.']::text[], array['Da','Denn','lernt']::text[], array['konnektor','grund']::text[], 1, '[{"de":"Weil der Zug Verspätung hatte, verpasste ich den Anschluss.","en":"Because the train was delayed, I missed the connection."},{"de":"Weil sie krank war, blieb sie zu Hause.","en":"Because she was ill, she stayed at home."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('9825edd6a25b', 'Die Idee ist reizvoll, nur fehlt das Budget.', '…, nur …', 'The idea is appealing, only there''s no budget.', 'B1', 'shared', 'shared_konnektoren', 'konnektor_einschraenkung', 'connector_limitation', '‘nur’ am Satzanfang des zweiten Teils löst Inversion aus.', 'Die Idee ist reizvoll, {{nur}} fehlt das Budget.', array['Die','Idee','ist','reizvoll,','nur','fehlt','das','Budget.']::text[], array['allerdings','jedoch','fehlt,']::text[], array['konnektor','einschraenkung']::text[], 1, '[{"de":"Das Hotel sieht schön aus, nur ist es uns zu teuer.","en":"The hotel looks nice, only it''s too expensive for us."},{"de":"Ich würde gern mitkommen, nur habe ich heute keine Zeit.","en":"I''d like to come along, only I have no time today."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('b512bd4b3ad6', 'Er schwieg, denn er war verlegen.', '…, denn …', 'He kept silent, for he was embarrassed.', 'B1', 'shared', 'shared_konnektoren', 'konnektor_grund', 'connector_reason', '‘denn’ ist nebenordnend: normale Wortstellung, keine Inversion.', 'Er schwieg, {{denn}} er war verlegen.', array['Er','schwieg,','denn','er','war','verlegen.']::text[], array['weil','da','war,']::text[], array['konnektor','grund']::text[], 1, '[{"de":"Ich nahm einen Regenschirm mit, denn es sollte regnen.","en":"I took an umbrella with me, for it was supposed to rain."},{"de":"Wir mussten uns beeilen, denn der Laden schloss bald.","en":"We had to hurry, for the shop was closing soon."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('cf762573df41', 'Sie war qualifiziert; daher bekam sie die Stelle.', '…; daher …', 'She was qualified; therefore she got the position.', 'B1', 'shared', 'shared_konnektoren', 'konnektor_folge', 'connector_consequence', '‘daher’ löst Inversion aus.', 'Sie war qualifiziert; {{daher}} bekam sie die Stelle.', array['Sie','war','qualifiziert;','daher','bekam','sie','die','Stelle.']::text[], array['darum','weil','bekommt']::text[], array['konnektor','folge']::text[], 1, '[{"de":"Es war schon spät; daher gingen wir nach Hause.","en":"It was already late; therefore we went home."},{"de":"Sie hatte gut geplant; daher lief alles reibungslos.","en":"She had planned well; therefore everything went smoothly."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('d56b3a3519e9', 'Wenn du übst, wirst du besser.', 'Wenn …, …', 'If you practice, you''ll get better.', 'B1', 'shared', 'shared_konnektoren', 'konnektor_bedingung', 'connector_condition', '‘wenn’ ist subordinierend: Verb am Nebensatzende, dann Inversion.', '{{Wenn}} du übst, wirst du besser.', array['Wenn','du','übst,','wirst','du','besser.']::text[], array['Falls','Sofern','wird']::text[], array['konnektor','bedingung']::text[], 1, '[{"de":"Wenn das Wetter schön ist, fahren wir ans Meer.","en":"If the weather is nice, we''ll drive to the sea."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('e46cdd677792', 'Obwohl es kalt war, schwammen sie im See.', 'Obwohl …, …', 'Although it was cold, they swam in the lake.', 'B1', 'shared', 'shared_konnektoren', 'konnektor_einraeumung', 'connector_concession', '‘obwohl’ ist subordinierend: Verb am Nebensatzende.', '{{Obwohl}} es kalt war, schwammen sie im See.', array['Obwohl','es','kalt','war,','schwammen','sie','im','See.']::text[], array['Trotzdem','Dennoch','schwamm']::text[], array['konnektor','einraeumung']::text[], 1, '[{"de":"Obwohl ich wenig Zeit hatte, half ich ihm.","en":"Although I had little time, I helped him."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('0696a04151b0', 'Er ist reich, dennoch ist er unglücklich.', '…, dennoch …', 'He is rich, yet he is unhappy.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_gegensatz', 'connector_contrast', '‘dennoch’ löst Inversion aus (Verb vor Subjekt).', 'Er ist reich, {{dennoch}} ist er unglücklich.', array['Er','ist','reich,','dennoch','ist','er','unglücklich.']::text[], array['trotzdem','obwohl','ist,']::text[], array['konnektor','gegensatz']::text[], 2, '[{"de":"Es war kalt, dennoch gingen wir schwimmen.","en":"It was cold, yet we went swimming."},{"de":"Sie war müde, dennoch arbeitete sie weiter.","en":"She was tired, yet she kept working."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('12f5e957d977', 'Sofern es nicht regnet, gehen wir spazieren.', 'Sofern …, …', 'Provided it doesn''t rain, we''ll go for a walk.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_bedingung', 'connector_condition', '‘sofern’ ist subordinierend: Verb am Nebensatzende, dann Inversion.', '{{Sofern}} es nicht regnet, gehen wir spazieren.', array['Sofern','es','nicht','regnet,','gehen','wir','spazieren.']::text[], array['Wenn','Falls','gehst']::text[], array['konnektor','bedingung']::text[], 2, '[{"de":"Wir liefern morgen, sofern die Ware da ist.","en":"We''ll deliver tomorrow, provided the goods are here."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('36d81322f32d', 'Wir kaufen es, vorausgesetzt, der Preis stimmt.', '…, vorausgesetzt, …', 'We''ll buy it, provided the price is right.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_bedingung', 'connector_condition', '‘vorausgesetzt(, dass)’ leitet eine Bedingung ein.', 'Wir kaufen es, {{vorausgesetzt,}} der Preis stimmt.', array['Wir','kaufen','es,','vorausgesetzt,','der','Preis','stimmt.']::text[], array['sofern','falls','stimmen']::text[], array['konnektor','bedingung']::text[], 2, '[{"de":"Ich komme mit, vorausgesetzt, ich bin rechtzeitig fertig.","en":"I''ll come along, provided I''m finished in time."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('36ea5b4cbd0d', 'Beeil dich, andernfalls verpassen wir den Bus.', '…, andernfalls …', 'Hurry up, otherwise we''ll miss the bus.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_bedingung', 'connector_condition', '‘andernfalls’ löst Inversion aus.', 'Beeil dich, {{andernfalls}} verpassen wir den Bus.', array['Beeil','dich,','andernfalls','verpassen','wir','den','Bus.']::text[], array['sonst','ansonsten','verpasst']::text[], array['konnektor','bedingung']::text[], 2, '[{"de":"Zahlen Sie bis Freitag, andernfalls entstehen Gebühren.","en":"Pay by Friday, otherwise fees will be incurred."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('36f5abe8b225', 'Darüber hinaus sind die Kosten gestiegen.', 'Darüber hinaus …', 'Furthermore, the costs have risen.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_aufzaehlung', 'connector_enumeration', '‘darüber hinaus’ löst Inversion aus.', 'Darüber {{hinaus}} sind die Kosten gestiegen.', array['Darüber','hinaus','sind','die','Kosten','gestiegen.']::text[], array['Außerdem','Zudem','steigen']::text[], array['konnektor','aufzaehlung']::text[], 2, '[{"de":"Die Mieten sind hoch. Darüber hinaus sind die Kosten für Strom gestiegen.","en":"Rents are high. Furthermore, the costs for electricity have risen."},{"de":"Das Projekt dauert länger; darüber hinaus brauchen wir mehr Geld.","en":"The project is taking longer; furthermore, we need more money."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('48d5e76c4ced', 'Zudem bietet die Stadt viel Kultur.', 'Zudem …', 'In addition, the city offers a lot of culture.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_aufzaehlung', 'connector_enumeration', '‘zudem’ löst Inversion aus.', '{{Zudem}} bietet die Stadt viel Kultur.', array['Zudem','bietet','die','Stadt','viel','Kultur.']::text[], array['Außerdem','Ferner','bieten']::text[], array['konnektor','aufzaehlung']::text[], 2, '[{"de":"Die Wohnung ist günstig; zudem bietet die Stadt viel Kultur.","en":"The apartment is cheap; in addition, the city offers a lot of culture."},{"de":"Das Angebot ist groß, zudem sind die Preise fair.","en":"The selection is large; in addition, the prices are fair."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('503bc085fddc', 'Vielen gefällt der Film, mir hingegen nicht.', '…, … hingegen …', 'Many like the film, I however do not.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_gegensatz', 'connector_contrast', '‘hingegen’ im Mittelfeld kontrastiert die Subjekte.', 'Vielen gefällt der Film, mir {{hingegen}} nicht.', array['Vielen','gefällt','der','Film,','mir','hingegen','nicht.']::text[], array['dennoch','trotzdem','gefallen']::text[], array['konnektor','gegensatz']::text[], 2, '[{"de":"Den Kindern schmeckt die Suppe, mir hingegen nicht.","en":"The children like the soup, I however do not."},{"de":"Er mag laute Musik, seine Frau hingegen mag es leise.","en":"He likes loud music, his wife by contrast likes it quiet."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('5194b679a266', 'Das Buch ist gut, allerdings zu lang.', '…, allerdings …', 'The book is good, though too long.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_einschraenkung', 'connector_limitation', '‘allerdings’ schränkt ein; am Satzanfang löst es Inversion aus.', 'Das Buch ist gut, {{allerdings}} zu lang.', array['Das','Buch','ist','gut,','allerdings','zu','lang.']::text[], array['jedoch','trotzdem','lange']::text[], array['konnektor','einschraenkung']::text[], 2, '[{"de":"Ich komme gern, allerdings erst nach der Arbeit.","en":"I''d be happy to come, though only after work."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('552befc8495f', 'Er sprach leise, sodass niemand ihn verstand.', '…, sodass …', 'He spoke quietly, so that no one understood him.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_folge', 'connector_consequence', '‘sodass’ ist subordinierend: Verb am Nebensatzende.', 'Er sprach leise, {{sodass}} niemand ihn verstand.', array['Er','sprach','leise,','sodass','niemand','ihn','verstand.']::text[], array['damit','folglich','versteht']::text[], array['konnektor','folge']::text[], 2, '[{"de":"Er stellte sein Auto falsch ab, sodass es abgeschleppt wurde.","en":"He parked his car wrongly, so that it was towed away."},{"de":"Sie erklärte alles genau, sodass wir es sofort verstanden.","en":"She explained everything precisely, so that we understood it immediately."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('581ef7fea23c', 'Es regnete; folglich blieben wir zu Hause.', '…; folglich …', 'It was raining; consequently we stayed home.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_folge', 'connector_consequence', '‘folglich’ löst Inversion aus (Verb vor Subjekt).', 'Es regnete; {{folglich}} blieben wir zu Hause.', array['Es','regnete;','folglich','blieben','wir','zu','Hause.']::text[], array['folgend','deshalb','blieb']::text[], array['konnektor','folge']::text[], 2, '[{"de":"Der Zug fiel aus; folglich nahmen wir den Bus.","en":"The train was cancelled; consequently we took the bus."},{"de":"Sie hatte alles vorbereitet; folglich verlief die Feier reibungslos.","en":"She had prepared everything; consequently the party went smoothly."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('583a1e3d24e3', 'Das stimmt, jedenfalls im Großen und Ganzen.', '…, jedenfalls …', 'That''s true, at least by and large.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_einschraenkung', 'connector_limitation', '‘jedenfalls’ schränkt die Geltung ein.', 'Das stimmt, {{jedenfalls}} im Großen und Ganzen.', array['Das','stimmt,','jedenfalls','im','Großen','und','Ganzen.']::text[], array['allerdings','freilich','stimmen']::text[], array['konnektor','einschraenkung']::text[], 2, '[{"de":"Ich weiß es nicht genau, jedenfalls war er gestern nicht da.","en":"I don''t know exactly; at any rate, he wasn''t there yesterday."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('69e0fc8a6f36', 'Er versprach viel, jedoch hielt er wenig.', '…, jedoch …', 'He promised much, but kept little.', 'B1', 'shared', 'shared_konnektoren', 'konnektor_gegensatz', 'connector_contrast', '‘jedoch’ am Satzanfang löst Inversion aus.', 'Er versprach viel, {{jedoch}} hielt er wenig.', array['Er','versprach','viel,','jedoch','hielt','er','wenig.']::text[], array['aber','sondern','hielt,']::text[], array['konnektor','gegensatz']::text[], 2, '[{"de":"Er kündigte sein Kommen an, jedoch erschien er nicht.","en":"He announced he would come, but he didn''t show up."},{"de":"Das Zimmer war günstig, jedoch lag es weit vom Zentrum.","en":"The room was cheap, but it was far from the centre."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('78cfbf9f2e01', 'Da niemand kam, schlossen wir früher.', 'Da …, …', 'Since no one came, we closed earlier.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_grund', 'connector_reason', '‘da’ ist subordinierend: Verb am Nebensatzende, danach Inversion.', '{{Da}} niemand kam, schlossen wir früher.', array['Da','niemand','kam,','schlossen','wir','früher.']::text[], array['Weil','Denn','schloss']::text[], array['konnektor','grund']::text[], 2, '[{"de":"Da der Laden schon geschlossen hatte, gingen wir woanders einkaufen.","en":"Since the shop had already closed, we went shopping elsewhere."},{"de":"Da es stark regnete, nahmen wir ein Taxi.","en":"Since it was raining heavily, we took a taxi."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('7a052e1cc4e6', 'Da es spät war, gingen wir nach Hause.', 'Da …, …', 'Since it was late, we went home.', 'B1', 'shared', 'shared_konnektoren', 'konnektor_grund', 'connector_reason', '‘da’ ist subordinierend: Verb am Nebensatzende, danach Inversion im Hauptsatz.', '{{Da}} es spät war, gingen wir nach Hause.', array['Da','es','spät','war,','gingen','wir','nach','Hause.']::text[], array['Weil','Denn','ginge']::text[], array['konnektor','grund']::text[], 2, '[{"de":"Da es schon dunkel war, machten wir uns auf den Heimweg.","en":"Since it was already dark, we set off home."},{"de":"Da der Bus nicht kam, gingen wir zu Fuß.","en":"Since the bus didn''t come, we walked."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('7c9529ca3bfc', 'Aufgrund des Sturms fiel der Zug aus.', 'Aufgrund … …', 'Due to the storm, the train was cancelled.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_grund', 'connector_reason', '‘aufgrund’ + Genitiv; danach Inversion (Verb vor Subjekt).', '{{Aufgrund}} des Sturms fiel der Zug aus.', array['Aufgrund','des','Sturms','fiel','der','Zug','aus.']::text[], array['Wegen','Trotz','fielen']::text[], array['konnektor','grund']::text[], 2, '[{"de":"Aufgrund eines Unfalls stand der Verkehr lange still.","en":"Due to an accident, the traffic was at a standstill for a long time."},{"de":"Aufgrund der hohen Nachfrage war das Konzert schnell ausverkauft.","en":"Due to the high demand, the concert was quickly sold out."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('7e099049bf7e', 'In Bezug auf den Vertrag haben wir Fragen.', 'In Bezug auf … …', 'With regard to the contract, we have questions.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_bezug', 'connector_reference', '‘in Bezug auf’ + Akkusativ; danach Inversion.', 'In {{Bezug}} auf den Vertrag haben wir Fragen.', array['In','Bezug','auf','den','Vertrag','haben','wir','Fragen.']::text[], array['Bezüglich','Hinsichtlich','hat']::text[], array['konnektor','bezug']::text[], 2, '[{"de":"In Bezug auf die Kosten müssen wir noch verhandeln.","en":"With regard to the costs, we still have to negotiate."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('7ef8bc451812', 'Zwar war es spät, doch wir blieben noch.', 'Zwar …, doch …', 'It was late, to be sure, but we stayed on.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_einraeumung', 'connector_concession', '‘zwar … doch …’ räumt ein und schränkt ein; ‘zwar’ löst Inversion aus.', '{{Zwar}} war es spät, doch wir blieben noch.', array['Zwar','war','es','spät,','doch','wir','blieben','noch.']::text[], array['Obwohl','Trotzdem','blieb']::text[], array['konnektor','einraeumung']::text[], 2, '[{"de":"Zwar ist die Wohnung klein, doch sie ist sehr gemütlich.","en":"The apartment is small, true, but it''s very cozy."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('9e232452ae9a', 'Sie wollte bleiben; im Gegensatz dazu wollte er gehen.', '…; im Gegensatz dazu …', 'She wanted to stay; in contrast, he wanted to leave.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_gegensatz', 'connector_contrast', '‘im Gegensatz dazu’ löst Inversion aus.', 'Sie wollte bleiben; im Gegensatz {{dazu}} wollte er gehen.', array['Sie','wollte','bleiben;','im','Gegensatz','dazu','wollte','er','gehen.']::text[], array['dagegen','hingegen','wollten']::text[], array['konnektor','gegensatz']::text[], 2, '[{"de":"Ich trinke gern Kaffee; im Gegensatz dazu mag meine Schwester nur Tee.","en":"I like drinking coffee; in contrast, my sister only likes tea."},{"de":"Im Süden war es warm; im Gegensatz dazu schneite es im Norden.","en":"In the south it was warm; in contrast, it was snowing in the north."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('c4ed9c13ecde', 'Er hat gespart; somit kann er reisen.', '…; somit …', 'He has saved; thus he can travel.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_folge', 'connector_consequence', '‘somit’ löst Inversion aus.', 'Er hat gespart; {{somit}} kann er reisen.', array['Er','hat','gespart;','somit','kann','er','reisen.']::text[], array['damit','also','kannst']::text[], array['konnektor','folge']::text[], 2, '[{"de":"Ich habe das Formular ausgefüllt; somit ist die Anmeldung erledigt.","en":"I have filled out the form; thus the registration is done."},{"de":"Wir haben alle Belege gesammelt; somit können wir die Steuer abgeben.","en":"We have collected all the receipts; thus we can file the taxes."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('ca1b454dc067', 'Sie hat recht, wobei einige Fragen offen bleiben.', '…, wobei …', 'She is right, though some questions remain open.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_einschraenkung', 'connector_limitation', '‘wobei’ ist subordinierend: Verb am Nebensatzende.', 'Sie hat recht, {{wobei}} einige Fragen offen bleiben.', array['Sie','hat','recht,','wobei','einige','Fragen','offen','bleiben.']::text[], array['allerdings','jedoch','bleibt']::text[], array['konnektor','einschraenkung']::text[], 2, '[{"de":"Der Vortrag war gut, wobei das Ende etwas zu lang war.","en":"The talk was good, though the ending was a bit too long."},{"de":"Wir haben alles geschafft, wobei uns ein paar Details noch fehlen.","en":"We managed everything, though a few details are still missing."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('daad630bf3d4', 'Der Sommer war heiß, der Winter hingegen mild.', '…, … hingegen …', 'The summer was hot, the winter by contrast mild.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_gegensatz', 'connector_contrast', '‘hingegen’ kann im Mittelfeld stehen und kontrastiert zwei Aussagen.', 'Der Sommer war heiß, der Winter {{hingegen}} mild.', array['Der','Sommer','war','heiß,','der','Winter','hingegen','mild.']::text[], array['dennoch','trotzdem','waren']::text[], array['konnektor','gegensatz']::text[], 2, '[{"de":"Mein Bruder ist sportlich, ich hingegen sitze lieber am Schreibtisch.","en":"My brother is athletic, I by contrast prefer sitting at my desk."},{"de":"Die Hinfahrt war stressig, die Rückfahrt hingegen entspannt.","en":"The outward journey was stressful, the return trip by contrast relaxed."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('dee68db1a1a0', 'Was die Termine betrifft, sind wir flexibel.', 'Was … betrifft, …', 'As far as the dates are concerned, we are flexible.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_bezug', 'connector_reference', '‘was … betrifft’ leitet einen Bezug ein; danach Inversion.', 'Was die Termine {{betrifft,}} sind wir flexibel.', array['Was','die','Termine','betrifft,','sind','wir','flexibel.']::text[], array['Bezüglich','Hinsichtlich','ist']::text[], array['konnektor','bezug']::text[], 2, '[{"de":"Was den Preis betrifft, müssen wir noch reden.","en":"As far as the price is concerned, we still need to talk."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('e0ab213faada', 'Bezüglich des Projekts gibt es Neuigkeiten.', 'Bezüglich … …', 'Regarding the project, there is news.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_bezug', 'connector_reference', '‘bezüglich’ + Genitiv; danach Inversion.', '{{Bezüglich}} des Projekts gibt es Neuigkeiten.', array['Bezüglich','des','Projekts','gibt','es','Neuigkeiten.']::text[], array['Hinsichtlich','Betreffend','geben']::text[], array['konnektor','bezug']::text[], 2, '[{"de":"Bezüglich der Lieferung melde ich mich morgen.","en":"Regarding the delivery, I''ll be in touch tomorrow."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('e1d0637439ae', 'Bezüglich Ihrer Anfrage melden wir uns bald.', 'Bezüglich … …', 'Regarding your inquiry, we''ll be in touch soon.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_bezug', 'connector_reference', '‘bezüglich’ + Genitiv; danach Inversion.', '{{Bezüglich}} Ihrer Anfrage melden wir uns bald.', array['Bezüglich','Ihrer','Anfrage','melden','wir','uns','bald.']::text[], array['Hinsichtlich','Betreffend','meldet']::text[], array['konnektor','bezug']::text[], 2, '[{"de":"Bezüglich Ihrer Bestellung gibt es eine kleine Verzögerung.","en":"Regarding your order, there is a small delay."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('ef3029679d1f', 'Sie kannte den Weg, sodass wir uns nicht verirrten.', '…, sodass …', 'She knew the way, so that we didn''t get lost.', 'B2', 'shared', 'shared_konnektoren', 'konnektor_folge', 'connector_consequence', '‘sodass’ ist subordinierend: Verb am Nebensatzende.', 'Sie kannte den Weg, {{sodass}} wir uns nicht verirrten.', array['Sie','kannte','den','Weg,','sodass','wir','uns','nicht','verirrten.']::text[], array['damit','deshalb','verirren']::text[], array['konnektor','folge']::text[], 2, '[{"de":"Sie hatte die App, sodass wir uns nicht verfuhren.","en":"She had the app, so that we didn''t take a wrong turn."},{"de":"Er sprach laut, sodass ihn alle gut hören konnten.","en":"He spoke loudly, so that everyone could hear him well."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('0c716e0e42b3', 'Sie verlor den Job; infolgedessen musste sie sparen.', '…; infolgedessen …', 'She lost her job; as a result she had to economize.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_grund', 'connector_reason', '‘infolgedessen’ löst Inversion aus.', 'Sie verlor den Job; {{infolgedessen}} musste sie sparen.', array['Sie','verlor','den','Job;','infolgedessen','musste','sie','sparen.']::text[], array['folglich','deswegen','muss']::text[], array['konnektor','grund']::text[], 3, '[{"de":"Er wurde krank; infolgedessen musste er den Urlaub absagen.","en":"He fell ill; as a result he had to cancel the holiday."},{"de":"Die Brücke war gesperrt; infolgedessen brauchten wir einen Umweg.","en":"The bridge was closed; as a result we needed a detour."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('0e8603cb557f', 'Die Eltern arbeiten, die Kinder spielen indes.', '…, … … indes', 'The parents work, the children by contrast play.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_gegensatz', 'connector_contrast', '‘indes’ steht hier im Mittelfeld und drückt einen Gegensatz aus.', 'Die Eltern arbeiten, die Kinder spielen {{indes}}.', array['Die','Eltern','arbeiten,','die','Kinder','spielen','indes.']::text[], array['jedoch','hingegen','spielt']::text[], array['konnektor','gegensatz']::text[], 3, '[{"de":"Die Mutter kocht, der Vater indes deckt den Tisch.","en":"The mother cooks, the father meanwhile sets the table."},{"de":"Die einen feierten, die anderen indes räumten schon auf.","en":"Some were celebrating, the others meanwhile were already tidying up."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('16f37a0cf42c', 'Wenngleich teuer, lohnt sich die Reise.', 'Wenngleich …, …', 'Although expensive, the trip is worth it.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_einraeumung', 'connector_concession', '‘wenngleich’ leitet eine Einräumung ein (gehoben).', '{{Wenngleich}} teuer, lohnt sich die Reise.', array['Wenngleich','teuer,','lohnt','sich','die','Reise.']::text[], array['Obwohl','Trotzdem','lohnen']::text[], array['konnektor','einraeumung']::text[], 3, '[{"de":"Wenngleich anstrengend, war der Tag schön.","en":"Although exhausting, the day was lovely."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('1a85de8c743a', 'Obgleich er müde war, arbeitete er weiter.', 'Obgleich …, …', 'Although he was tired, he kept working.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_einraeumung', 'connector_concession', '‘obgleich’ ist subordinierend: Verb am Nebensatzende, dann Inversion.', '{{Obgleich}} er müde war, arbeitete er weiter.', array['Obgleich','er','müde','war,','arbeitete','er','weiter.']::text[], array['Obwohl','Trotzdem','arbeitet']::text[], array['konnektor','einraeumung']::text[], 3, '[{"de":"Obgleich es regnete, gingen wir spazieren.","en":"Although it was raining, we went for a walk."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('299123c636bb', 'Er kam nicht, zumal er krank war.', '…, zumal …', 'He didn''t come, especially since he was ill.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_grund', 'connector_reason', '‘zumal’ leitet einen zusätzlichen, verstärkenden Grund ein (Nebensatz).', 'Er kam nicht, {{zumal}} er krank war.', array['Er','kam','nicht,','zumal','er','krank','war.']::text[], array['obwohl','trotzdem','war,']::text[], array['konnektor','grund']::text[], 3, '[{"de":"Wir sollten heute losfahren, zumal das Wetter morgen schlechter wird.","en":"We should set off today, especially since the weather will be worse tomorrow."},{"de":"Sie freute sich über das Geschenk, zumal sie es nicht erwartet hatte.","en":"She was happy about the gift, especially since she hadn''t expected it."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('2c1c09bc887d', 'Der Kurs war voll; infolge dessen kam ich nicht hinein.', '…; infolge dessen …', 'The course was full; as a result I couldn''t get in.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_folge', 'connector_consequence', '‘infolge dessen’ löst Inversion aus.', 'Der Kurs war voll; infolge {{dessen}} kam ich nicht hinein.', array['Der','Kurs','war','voll;','infolge','dessen','kam','ich','nicht','hinein.']::text[], array['folglich','deswegen','kommt']::text[], array['konnektor','folge']::text[], 3, '[{"de":"Der Bus war ausgebucht; infolgedessen kam ich zu spät zum Termin.","en":"The bus was sold out; as a result I arrived late for the appointment."},{"de":"Es gab einen Stromausfall; infolgedessen blieb der Aufzug stehen.","en":"There was a power cut; as a result the lift stopped."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('30d853ac3a17', 'Der Plan scheiterte, nicht zuletzt wegen fehlender Mittel.', '…, nicht zuletzt wegen …', 'The plan failed, not least because of a lack of funds.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_grund', 'connector_reason', '‘wegen’ + Genitiv; ‘nicht zuletzt’ verstärkt den Grund.', 'Der Plan scheiterte, nicht zuletzt {{wegen}} fehlender Mittel.', array['Der','Plan','scheiterte,','nicht','zuletzt','wegen','fehlender','Mittel.']::text[], array['trotz','aufgrund','scheitert']::text[], array['konnektor','grund']::text[], 3, '[{"de":"Das Projekt verzögerte sich, nicht zuletzt wegen des schlechten Wetters.","en":"The project was delayed, not least because of the bad weather."},{"de":"Sie zog in die Stadt, nicht zuletzt wegen der besseren Jobchancen.","en":"She moved to the city, not least because of the better job prospects."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('43060d7ab1ec', 'Angenommen, es klappt, feiern wir groß.', 'Angenommen, …, …', 'Assuming it works out, we''ll celebrate big.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_bedingung', 'connector_condition', '‘angenommen(, dass)’ leitet eine hypothetische Bedingung ein.', '{{Angenommen,}} es klappt, feiern wir groß.', array['Angenommen,','es','klappt,','feiern','wir','groß.']::text[], array['Vorausgesetzt','Falls','feiert']::text[], array['konnektor','bedingung']::text[], 3, '[{"de":"Angenommen, du gewinnst, was machst du mit dem Geld?","en":"Assuming you win, what will you do with the money?"}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('45c6b797a64c', 'Ferner wurde der Termin verschoben.', 'Ferner …', 'Furthermore, the appointment was postponed.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_aufzaehlung', 'connector_enumeration', '‘ferner’ (gehoben) löst Inversion aus.', '{{Ferner}} wurde der Termin verschoben.', array['Ferner','wurde','der','Termin','verschoben.']::text[], array['Außerdem','Zudem','wird']::text[], array['konnektor','aufzaehlung']::text[], 3, '[{"de":"Das Budget wurde gekürzt. Ferner wurde der Termin verschoben.","en":"The budget was cut. Furthermore, the appointment was postponed."},{"de":"Wir haben zu wenig Personal; ferner fehlt uns das nötige Material.","en":"We have too little staff; furthermore, we lack the necessary material."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('539193f08c9c', 'Die Beweise fehlten; demzufolge wurde er freigesprochen.', '…; demzufolge …', 'The evidence was lacking; accordingly he was acquitted.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_folge', 'connector_consequence', '‘demzufolge’ löst Inversion aus.', 'Die Beweise fehlten; {{demzufolge}} wurde er freigesprochen.', array['Die','Beweise','fehlten;','demzufolge','wurde','er','freigesprochen.']::text[], array['dementsprechend','deshalb','wird']::text[], array['konnektor','folge']::text[], 3, '[{"de":"Die Daten waren unvollständig; demzufolge mussten wir die Studie wiederholen.","en":"The data were incomplete; accordingly we had to repeat the study."},{"de":"Der Antrag kam zu spät; demzufolge wurde er abgelehnt.","en":"The application arrived too late; accordingly it was rejected."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('5ebe61644961', 'Vorausgesetzt, du hilfst mir, schaffen wir es.', 'Vorausgesetzt, …, …', 'Provided you help me, we''ll manage it.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_bedingung', 'connector_condition', '‘vorausgesetzt(, dass)’ leitet eine Bedingung ein.', '{{Vorausgesetzt,}} du hilfst mir, schaffen wir es.', array['Vorausgesetzt,','du','hilfst','mir,','schaffen','wir','es.']::text[], array['Sofern','Falls','schafft']::text[], array['konnektor','bedingung']::text[], 3, '[{"de":"Vorausgesetzt, das Wetter bleibt schön, machen wir ein Picknick.","en":"Provided the weather stays nice, we''ll have a picnic."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('68544687db49', 'Er ist freilich nicht der Einzige.', '… freilich …', 'He is admittedly not the only one.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_einschraenkung', 'connector_limitation', '‘freilich’ (gehoben) räumt einschränkend ein.', 'Er ist {{freilich}} nicht der Einzige.', array['Er','ist','freilich','nicht','der','Einzige.']::text[], array['allerdings','jedoch','sind']::text[], array['konnektor','einschraenkung']::text[], 3, '[{"de":"Sie hat den Fehler gemacht, sie ist freilich nicht die Einzige.","en":"She made the mistake, but she is admittedly not the only one."},{"de":"Der Vorschlag klingt gut, freilich müssen wir noch über die Kosten reden.","en":"The proposal sounds good, though we admittedly still have to talk about the costs."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('689a45e139d5', 'Er log mehrfach; demnach ist ihm nicht zu trauen.', '…; demnach …', 'He lied repeatedly; accordingly he is not to be trusted.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_folge', 'connector_consequence', '‘demnach’ löst Inversion aus.', 'Er log mehrfach; {{demnach}} ist ihm nicht zu trauen.', array['Er','log','mehrfach;','demnach','ist','ihm','nicht','zu','trauen.']::text[], array['demzufolge','deshalb','sind']::text[], array['konnektor','folge']::text[], 3, '[{"de":"Die Zahlen stimmen nicht überein; demnach muss ein Fehler vorliegen.","en":"The figures don''t match; accordingly there must be a mistake."},{"de":"Er hat alle Bedingungen erfüllt; demnach bekommt er den Zuschlag.","en":"He has met all the conditions; accordingly he gets the contract."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('68e6a567b4e6', 'Überdies wurde das Budget gekürzt.', 'Überdies …', 'Moreover, the budget was cut.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_aufzaehlung', 'connector_enumeration', '‘überdies’ löst Inversion aus.', '{{Überdies}} wurde das Budget gekürzt.', array['Überdies','wurde','das','Budget','gekürzt.']::text[], array['Außerdem','Ferner','wird']::text[], array['konnektor','aufzaehlung']::text[], 3, '[{"de":"Die Stellen wurden gestrichen; überdies wurde das Budget gekürzt.","en":"The positions were cut; moreover, the budget was reduced."},{"de":"Der Plan ist riskant, überdies wurde das Budget gekürzt.","en":"The plan is risky; moreover, the budget was cut."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('84973ec7b07c', 'Überdies fehlt das nötige Geld.', 'Überdies …', 'Moreover, the necessary money is lacking.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_aufzaehlung', 'connector_enumeration', '‘überdies’ löst Inversion aus.', '{{Überdies}} fehlt das nötige Geld.', array['Überdies','fehlt','das','nötige','Geld.']::text[], array['Außerdem','Zudem','fehlen']::text[], array['konnektor','aufzaehlung']::text[], 3, '[{"de":"Die Zeit ist knapp; überdies fehlt das nötige Geld.","en":"Time is short; moreover, the necessary money is lacking."},{"de":"Personal fehlt, überdies fehlt das nötige Geld.","en":"Staff is lacking; moreover, the necessary money is missing."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('9a370b5cb309', 'Wenngleich er zögerte, stimmte er schließlich zu.', 'Wenngleich …, …', 'Although he hesitated, he finally agreed.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_einraeumung', 'connector_concession', '‘wenngleich’ ist subordinierend: Verb am Nebensatzende, dann Inversion.', '{{Wenngleich}} er zögerte, stimmte er schließlich zu.', array['Wenngleich','er','zögerte,','stimmte','er','schließlich','zu.']::text[], array['Obwohl','Trotzdem','stimmt']::text[], array['konnektor','einraeumung']::text[], 3, '[{"de":"Wenngleich sie müde war, half sie uns noch.","en":"Although she was tired, she still helped us."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('9d92b7507927', 'Die Stadt ist schön, gleichwohl ist sie teuer.', '…, gleichwohl …', 'The city is beautiful, nonetheless it is expensive.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_einschraenkung', 'connector_limitation', '‘gleichwohl’ (gehoben) löst Inversion aus.', 'Die Stadt ist schön, {{gleichwohl}} ist sie teuer.', array['Die','Stadt','ist','schön,','gleichwohl','ist','sie','teuer.']::text[], array['dennoch','obwohl','sind']::text[], array['konnektor','einschraenkung']::text[], 3, '[{"de":"Das Restaurant ist beliebt, gleichwohl bekommt man oft einen Tisch.","en":"The restaurant is popular, nonetheless you often get a table."},{"de":"Er hatte wenig Zeit, gleichwohl half er mir geduldig.","en":"He had little time, nonetheless he helped me patiently."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('9f7ae4754e0c', 'Nicht zuletzt zählt die Erfahrung.', 'Nicht zuletzt …', 'Not least, experience counts.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_aufzaehlung', 'connector_enumeration', '‘nicht zuletzt’ löst Inversion aus.', 'Nicht {{zuletzt}} zählt die Erfahrung.', array['Nicht','zuletzt','zählt','die','Erfahrung.']::text[], array['Außerdem','Zudem','zählen']::text[], array['konnektor','aufzaehlung']::text[], 3, '[{"de":"Das Diplom ist wichtig; nicht zuletzt zählt die Erfahrung.","en":"The degree matters; not least, experience counts."},{"de":"Wir achten auf Noten, nicht zuletzt zählt die Erfahrung.","en":"We look at grades; not least, experience counts."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('a74783209851', 'Im Hinblick auf die Zukunft planen wir vorsichtig.', 'Im Hinblick auf … …', 'With a view to the future, we plan cautiously.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_bezug', 'connector_reference', '‘im Hinblick auf’ + Akkusativ; danach Inversion.', 'Im {{Hinblick}} auf die Zukunft planen wir vorsichtig.', array['Im','Hinblick','auf','die','Zukunft','planen','wir','vorsichtig.']::text[], array['Hinsichtlich','Bezüglich','plant']::text[], array['konnektor','bezug']::text[], 3, '[{"de":"Im Hinblick auf die Prüfung lernt sie jeden Tag.","en":"With a view to the exam, she studies every day."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('a9f3625edd98', 'Ferner empfehlen wir eine zweite Meinung.', 'Ferner …', 'Furthermore, we recommend a second opinion.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_aufzaehlung', 'connector_enumeration', '‘ferner’ (gehoben) löst Inversion aus.', '{{Ferner}} empfehlen wir eine zweite Meinung.', array['Ferner','empfehlen','wir','eine','zweite','Meinung.']::text[], array['Außerdem','Zudem','empfiehlt']::text[], array['konnektor','aufzaehlung']::text[], 3, '[{"de":"Nehmen Sie diese Tabletten; ferner empfehlen wir eine zweite Meinung.","en":"Take these tablets; furthermore, we recommend a second opinion."},{"de":"Wir prüfen die Unterlagen, ferner empfehlen wir eine zweite Meinung.","en":"We are checking the documents; furthermore, we recommend a second opinion."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('b7dcf867bdb3', 'Hinsichtlich der Kosten gibt es Bedenken.', 'Hinsichtlich … …', 'Regarding the costs, there are concerns.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_bezug', 'connector_reference', '‘hinsichtlich’ + Genitiv; danach Inversion.', '{{Hinsichtlich}} der Kosten gibt es Bedenken.', array['Hinsichtlich','der','Kosten','gibt','es','Bedenken.']::text[], array['Bezüglich','Betreffend','geben']::text[], array['konnektor','bezug']::text[], 3, '[{"de":"Hinsichtlich des Termins sind wir uns noch nicht einig.","en":"Regarding the date, we don''t yet agree."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('baa7290a744f', 'So müde er auch war, er hielt durch.', 'So … auch …, …', 'Tired as he was, he held on.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_einraeumung', 'connector_concession', 'Konzessives ‘so … auch …’ mit Hauptsatzstellung danach.', 'So müde er {{auch}} war, er hielt durch.', array['So','müde','er','auch','war,','er','hielt','durch.']::text[], array['obwohl','trotzdem','hielten']::text[], array['konnektor','einraeumung']::text[], 3, '[{"de":"So schwer die Aufgabe auch war, sie gab nicht auf.","en":"However hard the task was, she didn''t give up."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('d5633cb10d9c', 'Im Falle eines Defekts erstatten wir das Geld.', 'Im Falle … …', 'In the event of a defect, we will refund the money.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_bedingung', 'connector_condition', '‘im Falle’ + Genitiv; danach Inversion.', 'Im {{Falle}} eines Defekts erstatten wir das Geld.', array['Im','Falle','eines','Defekts','erstatten','wir','das','Geld.']::text[], array['Sofern','Falls','erstatten,']::text[], array['konnektor','bedingung']::text[], 3, '[{"de":"Im Falle einer Verspätung informieren wir Sie sofort.","en":"In the event of a delay, we will inform you immediately."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('f048b4c7b0b7', 'Des Weiteren benötigen wir Ihre Unterschrift.', 'Des Weiteren …', 'Furthermore, we require your signature.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_aufzaehlung', 'connector_enumeration', '‘des Weiteren’ löst Inversion aus.', 'Des {{Weiteren}} benötigen wir Ihre Unterschrift.', array['Des','Weiteren','benötigen','wir','Ihre','Unterschrift.']::text[], array['Außerdem','Zudem','benötigt']::text[], array['konnektor','aufzaehlung']::text[], 3, '[{"de":"Bitte senden Sie den Vertrag zurück. Des Weiteren benötigen wir Ihre Unterschrift.","en":"Please return the contract. Furthermore, we require your signature."},{"de":"Wir prüfen Ihren Antrag, des Weiteren benötigen wir Ihre Unterschrift.","en":"We are reviewing your application; furthermore, we require your signature."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('f26511a4f634', 'Der Plan ist gut, insofern er finanzierbar ist.', '…, insofern …', 'The plan is good, insofar as it is affordable.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_einschraenkung', 'connector_limitation', '‘insofern (als)’ ist subordinierend: Verb am Nebensatzende.', 'Der Plan ist gut, {{insofern}} er finanzierbar ist.', array['Der','Plan','ist','gut,','insofern','er','finanzierbar','ist.']::text[], array['sofern','obwohl','sei']::text[], array['konnektor','einschraenkung']::text[], 3, '[{"de":"Das Angebot ist interessant, insofern es zu unserem Budget passt.","en":"The offer is interesting, insofar as it fits our budget."},{"de":"Der Vertrag gilt, insofern beide Seiten ihn unterschreiben.","en":"The contract is valid, insofar as both sides sign it."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('f8eed9855c43', 'Diesbezüglich liegen noch keine Daten vor.', 'Diesbezüglich …', 'In this regard, no data are available yet.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_bezug', 'connector_reference', '‘diesbezüglich’ löst Inversion aus.', '{{Diesbezüglich}} liegen noch keine Daten vor.', array['Diesbezüglich','liegen','noch','keine','Daten','vor.']::text[], array['Dazu','Hierzu','liegt']::text[], array['konnektor','bezug']::text[], 3, '[{"de":"Diesbezüglich werden wir Sie rechtzeitig informieren.","en":"In this regard, we will inform you in good time."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('fdec1361cef8', 'Ich mag Tee, wohingegen er Kaffee bevorzugt.', '…, wohingegen …', 'I like tea, whereas he prefers coffee.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_gegensatz', 'connector_contrast', '‘wohingegen’ ist subordinierend: Verb am Nebensatzende.', 'Ich mag Tee, {{wohingegen}} er Kaffee bevorzugt.', array['Ich','mag','Tee,','wohingegen','er','Kaffee','bevorzugt.']::text[], array['während','obwohl','bevorzugen']::text[], array['konnektor','gegensatz']::text[], 3, '[{"de":"Ich gehe gern wandern, wohingegen mein Mann lieber zu Hause bleibt.","en":"I like going hiking, whereas my husband prefers to stay home."},{"de":"Sie spart jeden Monat, wohingegen er sein Geld sofort ausgibt.","en":"She saves every month, whereas he spends his money right away."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('feb1c898db2c', 'Das Wetter war schlecht, demzufolge fiel das Spiel aus.', '…, demzufolge …', 'The weather was bad, accordingly the match was cancelled.', 'C1', 'shared', 'shared_konnektoren', 'konnektor_folge', 'connector_consequence', '‘demzufolge’ löst Inversion aus.', 'Das Wetter war schlecht, {{demzufolge}} fiel das Spiel aus.', array['Das','Wetter','war','schlecht,','demzufolge','fiel','das','Spiel','aus.']::text[], array['deshalb','folglich','fielen']::text[], array['konnektor','folge']::text[], 3, '[{"de":"Das Wetter war schlecht, demzufolge fiel der Ausflug aus.","en":"The weather was bad, accordingly the outing was cancelled."},{"de":"Die Nachfrage stieg, demzufolge erhöhte die Firma die Produktion.","en":"Demand rose, accordingly the company increased production."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('0a6eabd08c1a', 'Solltest du Zeit haben, ruf mich an.', 'Solltest …, …', 'Should you have time, give me a call.', 'C2', 'shared', 'shared_konnektoren', 'konnektor_bedingung', 'connector_condition', 'Konditionale Inversion mit ‘sollte’ ersetzt ‘wenn’ (gehoben).', '{{Solltest}} du Zeit haben, ruf mich an.', array['Solltest','du','Zeit','haben,','ruf','mich','an.']::text[], array['Falls','Wenn','rufst']::text[], array['konnektor','bedingung']::text[], 4, '[{"de":"Solltest du Fragen haben, schreib mir einfach eine Nachricht.","en":"Should you have questions, just write me a message."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('3d055c8cf696', 'Betreffend die Reform äußerte er Zweifel.', 'Betreffend … …', 'Concerning the reform, he expressed doubts.', 'C2', 'shared', 'shared_konnektoren', 'konnektor_bezug', 'connector_reference', '‘betreffend’ (gehoben, oft mit Akkusativ); danach Inversion.', '{{Betreffend}} die Reform äußerte er Zweifel.', array['Betreffend','die','Reform','äußerte','er','Zweifel.']::text[], array['Hinsichtlich','Bezüglich','äußern']::text[], array['konnektor','bezug']::text[], 4, '[{"de":"Betreffend Ihre Anfrage liegt uns noch keine Antwort vor.","en":"Concerning your inquiry, we do not yet have an answer."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('40d40569d91e', 'Obschon er zögerte, unterschrieb er schließlich.', 'Obschon …, …', 'Although he hesitated, he finally signed.', 'C2', 'shared', 'shared_konnektoren', 'konnektor_einraeumung', 'connector_concession', '‘obschon’ (gehoben) ist subordinierend.', '{{Obschon}} er zögerte, unterschrieb er schließlich.', array['Obschon','er','zögerte,','unterschrieb','er','schließlich.']::text[], array['Obwohl','Trotzdem','unterschreibt']::text[], array['konnektor','einraeumung']::text[], 4, '[{"de":"Obschon das Wetter schlecht war, kamen viele Gäste.","en":"Although the weather was bad, many guests came."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('787e69428102', 'Sie blieb hart, dessen ungeachtet liebte er sie.', '…, dessen ungeachtet …', 'She stayed firm; regardless of that, he loved her.', 'C2', 'shared', 'shared_konnektoren', 'konnektor_einraeumung', 'connector_concession', '‘dessen ungeachtet’ löst Inversion aus (gehoben).', 'Sie blieb hart, dessen {{ungeachtet}} liebte er sie.', array['Sie','blieb','hart,','dessen','ungeachtet','liebte','er','sie.']::text[], array['trotzdem','dennoch','liebten']::text[], array['konnektor','einraeumung']::text[], 4, '[{"de":"Die Kritik war hart, dessen ungeachtet machte sie weiter.","en":"The criticism was harsh; regardless of that, she carried on."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('7b7d4a1ae72b', 'Ungeachtet dessen blieb sie freundlich.', 'Ungeachtet dessen …', 'Notwithstanding that, she remained friendly.', 'C2', 'shared', 'shared_konnektoren', 'konnektor_einraeumung', 'connector_concession', '‘ungeachtet dessen’ löst Inversion aus.', '{{Ungeachtet}} dessen blieb sie freundlich.', array['Ungeachtet','dessen','blieb','sie','freundlich.']::text[], array['Trotzdem','Dennoch','blieben']::text[], array['konnektor','einraeumung']::text[], 4, '[{"de":"Die Lage war schwierig. Ungeachtet dessen blieb sie freundlich.","en":"The situation was difficult. Notwithstanding that, she remained friendly."},{"de":"Er bekam viel Kritik; ungeachtet dessen blieb er ruhig.","en":"He received a lot of criticism; notwithstanding that, he stayed calm."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('844cbd4630a1', 'Angesichts der Lage handelten sie sofort.', 'Angesichts … …', 'In view of the situation, they acted at once.', 'C2', 'shared', 'shared_konnektoren', 'konnektor_grund', 'connector_reason', '‘angesichts’ + Genitiv; danach Inversion.', '{{Angesichts}} der Lage handelten sie sofort.', array['Angesichts','der','Lage','handelten','sie','sofort.']::text[], array['Trotz','Wegen','handelte']::text[], array['konnektor','grund']::text[], 4, '[{"de":"Angesichts der Kosten verschoben wir den Umzug.","en":"In view of the costs, we postponed the move."},{"de":"Angesichts des schlechten Wetters blieben die meisten zu Hause.","en":"In view of the bad weather, most people stayed at home."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('b2c52a554e85', 'Die Prämisse ist falsch; mithin ist der Schluss ungültig.', '…; mithin …', 'The premise is false; hence the conclusion is invalid.', 'C2', 'shared', 'shared_konnektoren', 'konnektor_folge', 'connector_consequence', '‘mithin’ (sehr gehoben) löst Inversion aus.', 'Die Prämisse ist falsch; {{mithin}} ist der Schluss ungültig.', array['Die','Prämisse','ist','falsch;','mithin','ist','der','Schluss','ungültig.']::text[], array['also','folglich','sind']::text[], array['konnektor','folge']::text[], 4, '[{"de":"Die Annahme war falsch; mithin ist das Ergebnis nicht haltbar.","en":"The assumption was wrong; hence the result is untenable."},{"de":"Er hat die Frist versäumt; mithin verfällt sein Anspruch.","en":"He missed the deadline; hence his claim lapses."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('d28649e6520b', 'Er hat geübt, gleichwohl bleibt er nervös.', '…, gleichwohl …', 'He has practiced, nonetheless he remains nervous.', 'C2', 'shared', 'shared_konnektoren', 'konnektor_einschraenkung', 'connector_limitation', '‘gleichwohl’ (gehoben) löst Inversion aus.', 'Er hat geübt, {{gleichwohl}} bleibt er nervös.', array['Er','hat','geübt,','gleichwohl','bleibt','er','nervös.']::text[], array['dennoch','obwohl','bleiben']::text[], array['konnektor','einschraenkung']::text[], 4, '[{"de":"Sie hat viel trainiert, gleichwohl ist sie vor dem Wettkampf aufgeregt.","en":"She trained a lot, nonetheless she is nervous before the competition."},{"de":"Wir kannten die Strecke, gleichwohl verfuhren wir uns einmal.","en":"We knew the route, nonetheless we took a wrong turn once."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('d313d0f755be', 'Die Theorie überzeugt, die Praxis enttäuscht indessen.', '…, … … indessen', 'The theory convinces, the practice however disappoints.', 'C2', 'shared', 'shared_konnektoren', 'konnektor_gegensatz', 'connector_contrast', '‘indessen’ (gehoben) drückt hier einen Gegensatz aus.', 'Die Theorie überzeugt, die Praxis enttäuscht {{indessen}}.', array['Die','Theorie','überzeugt,','die','Praxis','enttäuscht','indessen.']::text[], array['jedoch','hingegen','enttäuschen']::text[], array['konnektor','gegensatz']::text[], 4, '[{"de":"Der Anfang gefiel mir, das Ende indessen langweilte mich.","en":"I liked the beginning, the ending however bored me."},{"de":"Die Pläne klangen gut, die Umsetzung indessen scheiterte.","en":"The plans sounded good, the implementation however failed."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
insert into redemittel (id, phrase_de, frame_de, translation_en, level, skill_code, task_code, function_code, register_group, notes, cloze_template, tokens, distractors, tags, difficulty, examples) values ('ee46d4ff6b2b', 'Es war kalt; gleichwohl genossen wir den Tag.', '…; gleichwohl …', 'It was cold; nonetheless we enjoyed the day.', 'C2', 'shared', 'shared_konnektoren', 'konnektor_einschraenkung', 'connector_limitation', '‘gleichwohl’ (gehoben) löst Inversion aus.', 'Es war kalt; {{gleichwohl}} genossen wir den Tag.', array['Es','war','kalt;','gleichwohl','genossen','wir','den','Tag.']::text[], array['dennoch','trotzdem','genoss']::text[], array['konnektor','einschraenkung']::text[], 4, '[{"de":"Es regnete den ganzen Morgen; gleichwohl machten wir den Ausflug.","en":"It rained all morning; nonetheless we went on the trip."},{"de":"Die Aufgabe war schwer; gleichwohl gaben wir nicht auf.","en":"The task was hard; nonetheless we did not give up."}]'::jsonb) on conflict (id) do update set phrase_de=excluded.phrase_de, frame_de=excluded.frame_de, translation_en=excluded.translation_en, level=excluded.level, skill_code=excluded.skill_code, task_code=excluded.task_code, function_code=excluded.function_code, register_group=excluded.register_group, notes=excluded.notes, cloze_template=excluded.cloze_template, tokens=excluded.tokens, distractors=excluded.distractors, tags=excluded.tags, difficulty=excluded.difficulty, examples=excluded.examples;
